ZLDB.DG["BFD"]={
Name="Blackfathom Deeps",
Story="Once dedicated to the night elves' goddess Elune, Blackfathom Deeps was thought to have been destroyed during the Sundering, lost beneath the ocean. Millennia later, members of the Twilight's Hammer cult were drawn to the temple by whispers and foul dreams. After sacrificing untold numbers of innocents, the cult was rewarded with a new task: to protect one of the Old Gods' most cherished creatures, a pet that is still in need of nurturing before he can unleash his dark powers on the world.",
Background=M.."dungeons\\bfd\\background",
GridBackground=M.."dungeons\\bfd\\grid-background",
MapId=7,
IconScale=0.9,
MinLevel=22,
MaxLevel=31,
Entrances={{MapContinentId=1,MapCoordinateX=14.1,MapCoordinateY=14.4,MapZoneId=1}},
Type=T.Dungeon,
Key="BFD",
Bosses={
{Id="4887",Name="Ghamoo-ra",Story="When the Twilight's Hammer cult arrived, its followers roused and imprisoned one of the last peaceful creatures living in Elune's temple. The cult delighted in tormenting the giant turtle for years, flaying its mind and body until it succumbed to madness. Naming the beast Ghamoo-Ra, the cultists trained it to attack outsiders and defend the Old Gods' shrine.",Portrait=M.."dungeons\\bfd\\ghamoora-portrait",Frame=M.."dungeons\\bfd\\ghamoora-frame",MapCoordinateX=22.5,MapCoordinateY=41,L="6907:50,6908:50,80718:35"},
{Id="4831",Name="Lady Sarevess",Story="The Twilight's Hammer granted Lady Sarevess her own private cove within Blackfathom Deeps, continuously sending her fresh sacrifices. The cultists hope that her rituals and research will result in magical protection that will allow them to worship the terrifying hydra at the deeps' core without fear of becoming his next meal.",Portrait=M.."dungeons\\bfd\\sarevess-portrait",Frame=M.."dungeons\\bfd\\sarevess-frame",MapCoordinateX=6.7,MapCoordinateY=25.8,L="888:33,3078:33,11121:33"},
{Id="6243",Name="Gelihast",Story="The Old Gods called, and Gelihast answered, forcing his way into Blackfathom Deeps and slaughtering nearly a dozen surprised Twilight's Hammer cultists with his twin swords. Impressed by his ferocity and brutality, the cult allowed him to stay, and he built his own shrine to offer sacrifices and receive blessings from the ominous presence in the temple ruins.",Portrait=M.."dungeons\\bfd\\gelihast-portrait",Frame=M.."dungeons\\bfd\\gelihast-frame",MapCoordinateX=38,MapCoordinateY=38.2,L="1470:15,80720:35,6906:50,6905:50"},
{Id="12902",Name="Lorgus Jett",Story="A mysterious member of the Twilight's Hammer, said to possess shamanic abilities depsite being a human. Rumors says he was a member of the Knight of the Silver Hand before deserting and joining the Twilight's Hammer.",Portrait=M.."dungeons\\bfd\\jett-portrait",Frame=M.."dungeons\\bfd\\jett-frame",MapCoordinateX=42.3,MapCoordinateY=62.7},
{Id="62530",Name="Velthelaxx the Defiler",Story="An ancient satyr, skulking in the ancient temple to Elune.",Portrait=M.."dungeons\\bfd\\velthelaxx-portrait",Frame=M.."dungeons\\bfd\\velthelaxx-frame",MapCoordinateX=55.3,MapCoordinateY=63.6,L="58120:25,58121:25,58122:25,58123:25"},
{Id="4830",Name="Old Serra'kis",Story="Many of the creatures swimming beneath the Moonshrine Ruins were killed for food after the Twilight's Hammer cult took up residence, but the largest thresher in the water proved to be uncatchable, and those who persisted in hunting it inevitably died in the attempt.",Portrait=M.."dungeons\\bfd\\serrakis-portrait",Frame=M.."dungeons\\bfd\\serrakis-frame",MapCoordinateX=53.4,MapCoordinateY=78.3,L="6904:33,6902:33,6901:33"},
{Id="4832",Name="Twilight Lord Kelris",Story="When the cultists found a strange three-headed creature in the belly of Blackfathom Deeps, Twilight Lord Kelris was convinced the hydra was a herald of the Old Gods' return to Azeroth... and his ticket to immortality. Kelris personally supervises the growth of the monster, even feeding him his own subjects to satisfy his wild hunger.",Portrait=M.."dungeons\\bfd\\kelris-portrait",Frame=M.."dungeons\\bfd\\kelris-frame",MapCoordinateX=53.5,MapCoordinateY=87.5,L="1155:50,6903:35,80719:15"},
{Id="4829",Name="Aku'mai",Story="Aku'mai, an ancient evil, carries within her a small measure of the Old Gods' power. This three-headed hydra is greatly feared for her mindless savagery and insatiable hunger for living flesh, but the Twilight's Hammer worships her as a divine sign that the Old Gods will soon return.",Portrait=M.."dungeons\\bfd\\akumai-portrait",Frame=M.."dungeons\\bfd\\akumai-frame",MapCoordinateX=77.8,MapCoordinateY=91.1,L="6909:33,6910:33,6911:33,51217:1"},
}}
ZLDB.DG["BM"]={
Name="The Black Morass",
Story="Deep within the Caverns of Time, the Infinite Dragonflight seeks to alter the course of history by preventing the opening of the Dark Portal. Should they succeed, the orcs would never arrive on Azeroth, and the pivotal events that shaped the world's defense against the Burning Legion would be undone. To preserve the timeline, brave adventurers must venture back seventeen years into the swamplands of the Black Morass. There, they must protect the Guardian Medivh as he conducts his ritual, ensuring that the dark gateway opens and the threads of fate remain unbroken.",
Background=M.."dungeons\\bm\\background",
GridBackground=M.."dungeons\\bm\\grid-background",
MapId=31,
ZoneId=2,
IconScale=1,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=34.3,MapCoordinateY=85.2,MapDestinationZoneId=2,MapZoneId=4}},
Type=T.Dungeon,
Key="BM",
Bosses={
{Id="65113",Name="Chronar",Story="Once a proud defender of the timeways, Chronar broke his sacred oaths to the Bronze Dragonflight to consort with the Infinite. Now a twisted husk of his former self, he wields a 'Time-Worn Spear', a weapon he claimed from a human hero in a past conflict, as he works tirelessly to shatter the very history he once swore to protect.",Portrait=M.."dungeons\\bm\\chronar-portrait",Frame=M.."dungeons\\bm\\chronar-frame",MapCoordinateX=32,MapCoordinateY=27.4,MapId=2,MapIsBelow=true,L="61016:17,61018:17,61019:17,61036:17,61047:17,61048:17,70226:1"},
{Id="61575",Name="Epidamu",Story="As the temporal anomalies within the morass intensify, creatures from across the boundaries of time are drawn to the conflict. Epidamu serves as a harbinger of the Infinite's will, using its reality-warping powers to siphon the essence of the swamp and manifest the Corrupted Sand that plagues the broken timelines.",Portrait=M.."dungeons\\bm\\epidamu-portrait",Frame=M.."dungeons\\bm\\epidamu-frame",MapCoordinateX=26.1,MapCoordinateY=17.2,MapId=2,MapIsBelow=true,L="50431:12,61032:12,61041:12,61045:12,61055:12,61056:12,61698:12,61700:12"},
{Id="61316",Name="Drifting Avatar of Sand",Story="Formed from the collective weight of shattered possibilities, the Drifting Avatar of Sand is a mindless construct of the Infinite Dragonflight. It acts as a literal hourglass of doom, embodying the Corrupted Sand that leaks from the wounds in the timeline, crushing any who seek to repair the chronal damage.",Portrait=M.."dungeons\\bm\\avatar-portrait",Frame=M.."dungeons\\bm\\avatar-frame",MapCoordinateX=32.8,MapCoordinateY=12.9,MapId=2,L="61015:14,61020:2,61024:14,61033:14,61038:14,61042:14,61044:14,61057:14,70226:1"},
{Id="65116",Name="Time-Lord Epochronos",Story="A high-ranking strategist of the Infinite Dragonflight, Epochronos oversees the tactical assault on Medivh's ritual. He views the linear flow of time as a cage and seeks to unlock a future where the Legion's ultimate defeat is averted, believing that his 'corrections' to the past are for the greater good of the multiverse.",Portrait=M.."dungeons\\bm\\epochronos-portrait",Frame=M.."dungeons\\bm\\epochronos-frame",MapCoordinateX=29,MapCoordinateY=25.2,MapId=2,L="50428:12,50430:12,61017:12,61021:12,61022:12,61028:12,61049:1,61054:12,61058:12,70226:1"},
{Id="65124",Name="Mossheart",Story="The ancient bog beasts of the Black Morass have long been sensitive to the energies of the land. Mossheart, once a peaceful protector of the mire, has been driven to a state of primal fury by the temporal radiation leaking from the Dark Portal. It now lashes out at anything-bronze or infinite-that disturbs the murky depths of its home.",Portrait=M.."dungeons\\bm\\mossheart-portrait",Frame=M.."dungeons\\bm\\mossheart-frame",MapCoordinateX=69.1,MapCoordinateY=51,MapId=1,L="61050:16,61051:16,61059:16,61060:16,61061:16,61062:16,70226:1"},
{Id="65125",Name="Antnormi",Story="Formerly a sister-in-arms to the bronze dragon Keridormi, Antnormi's betrayal is perhaps the most personal of all. Convinced that the arrival of the orcs is a tragedy that must be erased, she has embraced the Infinite path. She stands as the final obstacle in the southern timeway, willing to kill her former kin to see her vision of a 'pure' history realized.",Portrait=M.."dungeons\\bm\\antnormi-portrait",Frame=M.."dungeons\\bm\\antnormi-frame",MapCoordinateX=48,MapCoordinateY=74.6,MapId=1,L="50427:50,61053:50,50429:33,61037:33,61046:33,51217:100,61014:1,61027:33,61031:33,61040:33,61043:1,70226:3"},
{Id="65122",Name="Rotmaw",Story="A massive crocolisk of legendary appetite, Rotmaw has feasted upon the displaced chronal energies of the swamp for years. The beast has grown unnaturally large and aggressive, its maw dripping with entropic rot. It cares little for the preservation of time, seeing the invaders of the Black Morass only as a much-needed feast.",Portrait=M.."dungeons\\bm\\rotmaw-portrait",Frame=M.."dungeons\\bm\\rotmaw-frame",MapCoordinateX=25,MapCoordinateY=79.6,MapId=1,L="61023:12,61025:12,61029:12,61030:12,61034:12,61063:12,61699:12,61701:12,70226:1"},
}}
ZLDB.DG["BRD"]={
Name="Blackrock Depths",
Story="The smoldering Blackrock Depths are home to the Dark Iron dwarves and their emperor, Dagran Thaurissan. Like his predecessors, he serves under the iron rule of Ragnaros the Firelord, a merciless being summoned into the world centuries ago. The presence of chaotic elementals has attracted Twilight's Hammer cultists to the mountain domain. Along with Ragnaros' servants, they have pushed the dwarves toward increasingly destructive ends that could soon spell doom for all of Azeroth.",
Background=M.."dungeons\\brd\\background",
GridBackground=M.."dungeons\\brd\\grid-background",
MapId=14,
IconScale=0.6,
MinLevel=50,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=24.6,MapCoordinateY=12.6,MapZoneId=6}},
Type=T.Dungeon,
Key="BRD",
Bosses={
{Id="9018",Name="High Interrogator Gerstahn",Story="The Twilight's Hammer cultist Gerstahn has always indulged in life's finer things: exotic foods, fine clothes, and gem-encrusted torture tools. Day and night, her prisoners' bloodcurdling cries echo throughout the Dark Iron clan's infamous Detention Block. Gerstahn proudly calls this horrific noise her symphony of screams, and she is always eager to add another voice to the chorus.",Portrait=M.."dungeons\\brd\\gerstahn-portrait",Frame=M.."dungeons\\brd\\gerstahn-frame",MapCoordinateX=51.3,MapCoordinateY=93.6,L="11624:25,11625:25,11626:25,22240:25,51217:5,70226:2"},
{Id="9025",Name="Lord Roccor",Story="Lord Roccor loathes the scheming and backstabbing of his fellow fire elementals. To avoid serving alongside his kind in the Molten Core, the mighty being purposefully angered the Firelord. Roccor's risky gambit paid off: he was expelled from the core and forced to guard Blackrock Depths in isolation.",Portrait=M.."dungeons\\brd\\roccor-portrait",Frame=M.."dungeons\\brd\\roccor-frame",MapCoordinateX=54.3,MapCoordinateY=77.9,IsRare=true,L="11624:25,11625:25,11626:25,22240:25,51217:5,11631:25,11632:25,22234:25,22397:25,11813:15,70226:2,11630:16"},
{Id="9319",Name="Houndmaster Grebmar",Story="Grebmar Fleabeard's hounds are the only family he's ever known. Long ago, the orphaned dwarf began breeding canines to serve as companions and guard dogs. When the houndmaster isn't patrolling Blackrock Depths with his loyal beasts, he often treats them to the Grim Guzzler's finest Dark Iron ale.",Portrait=M.."dungeons\\brd\\grebmar-portrait",Frame=M.."dungeons\\brd\\grebmar-frame",MapCoordinateX=56.3,MapCoordinateY=69.1,L="11623:25,11627:25,11628:25,11629:25,51217:5,70226:2"},
{Id="9031",Name="Ring of Law",Story="There is only one punishment for crimes committed against the Dark Iron dwarves: death. Ancient tradition calls for the guilty to pay the blood price in the Ring of the Law by battling savage creatures gathered from across Azeroth. To date, it is unknown if anyone has ever survived this brutal crucible.",Portrait=M.."dungeons\\brd\\ring-portrait",Frame=M.."dungeons\\brd\\ring-frame",MapCoordinateX=53.7,MapCoordinateY=71.7,L="11675:33,11677:33,11731:33,51217:5,70226:2,11678:15,11679:25,11685:25,11686:25,11730:25,22257:30,22271:30,22266:25,11726:15,11610:100,11702:25,11703:25,11722:25,22270:25,11633:25,11634:25,11635:25,11729:25,11662:25,11665:25,11728:25,11824:25"},
{Id="9024",Name="Pyromancer Loregrain",Story="Once a respected member of the Earthen Ring, Loregrain joined the Twilight's Hammer cult for reasons that remain a mystery to his former allies. He eventually journeyed to Blackrock Depths, where he took a sudden interest in the famed Dark Iron architect Franclorn Forgewright. The purpose of his current obsession is unclear, but Loregrain remains loyal to his cult and an enemy of all who oppose it.",Portrait=M.."dungeons\\brd\\loregrain-portrait",Frame=M.."dungeons\\brd\\loregrain-frame",MapCoordinateX=57.1,MapCoordinateY=76,IsRare=true,L="70226:2,11207:16,11750:25,11749:25,11748:25,11747:25"},
{Id="9041",Name="Warder Stilgiss",Story="After years of dedication to Emperor Thaurissan, the cunning mage Stilgiss was entrusted with protecting his clan's coffers in the Black Vault. The loyal dwarf's close friend Houndmaster Grebmar celebrated the occasion by gifting one of his vicious dogs--Verek--to Stilgiss. The mage has put the beast to good use, keeping it at his side to scare off the vault's would-be thieves.",Portrait=M.."dungeons\\brd\\stilgiss-portrait",Frame=M.."dungeons\\brd\\stilgiss-frame",MapCoordinateX=60.6,MapCoordinateY=53,IsRare=true,L="11782:25,11783:25,11784:25,22241:25,11755:13,22242:13,70226:2"},
{Id="9476",Name="Watchman Doomgrip",Story="As the watchman of the Black Vault, Doomgrip takes his occupation very seriously. If adventurers were to attempt to steal the contents of the vault, they would be certain to meet the wrath of the Dark Iron dwarf...",Portrait=M.."dungeons\\brd\\vault-portrait",Frame=M.."dungeons\\brd\\vault-frame",MapCoordinateX=61.8,MapCoordinateY=54.6,L="22256:2,22205:2,22254:1"},
{Id="9056",Name="Fineous Darkvire",Story="Chief Architect Fineous Darkvire earned his title by passing off the ideas of more gifted masons as his own. His arrogance and scheming have drawn the ire of his predecessor, Franclorn Forgewright, from beyond the grave. The ghost of the late chief architect seeks to reclaim his incredibly powerful hammer--Ironfel--from Darkvire before it can be used for ill.",Portrait=M.."dungeons\\brd\\darkvire-portrait",Frame=M.."dungeons\\brd\\darkvire-frame",MapCoordinateX=62.8,MapCoordinateY=41.2,L="11839:25,11841:25,11842:25,22223:25,56098:9,51217:5,70226:2,11840:5"},
{Id="9017",Name="Lord Incendius",Story="Baron Geddon taught Incendius to harness his destructive powers, but the baron never expected his protégé to grow so lethally efficient. Increasingly wary that Incendius might usurp him, Geddon sent the blazing elemental out of the Molten Core to guard the Dark Iron dwarves' fabled Black Anvil.",Portrait=M.."dungeons\\brd\\incendius-portrait",Frame=M.."dungeons\\brd\\incendius-frame",MapCoordinateX=57.8,MapCoordinateY=48.5,L="11764:25,11765:25,11766:25,11767:25,51217:5,70226:2"},
{Id="9016",Name="Bael'Gar",Story="The monstrous molten giant Bael'Gar lumbers across the Dark Iron Highway, a stunning feat of dwarven engineering carved into Blackrock Depths. Ragnaros pulled the giant from the heart of the Firelands to guard a massive sealed door at one end of the highway. According to legend, only the Firelord and the Dark Iron clan's highest-ranking members know what lies beyond the mysterious gate.",Portrait=M.."dungeons\\brd\\baelgar-portrait",Frame=M.."dungeons\\brd\\baelgar-frame",MapCoordinateX=35.1,MapCoordinateY=64.6,L="11802:25,11803:25,11805:25,11807:25,51217:5,70226:2"},
{Id="9033",Name="General Angerforge",Story="Through a lifetime of study, General Angerforge has become an expert on dwarven military history and tactics. He recently incurred Emperor Dagran Thaurissan's fury by writing a scathing treatise on his clan's failures in past conflicts. This political blunder aside, Angerforge is a Dark Iron to his core. He will bleed--and die, if necessary--to protect his people and his emperor.",Portrait=M.."dungeons\\brd\\angerforge-portrait",Frame=M.."dungeons\\brd\\angerforge-frame",MapCoordinateX=42.7,MapCoordinateY=66.2,L="11810:20,11816:20,11817:20,11820:20,11821:20,51217:5,70226:2"},
{Id="8983",Name="Golem Lord Argelmach",Story="Argelmach's lifelong obsession with immortality drove him to forge enchanted constructs in his own image. Rumor has it that he has also dabbled in some form of black magic that would allow the golem lord's new creations to act as vessels for his spirit should his flesh-and-blood body be destroyed.",Portrait=M.."dungeons\\brd\\argelmach-portrait",Frame=M.."dungeons\\brd\\argelmach-frame",MapCoordinateX=42.4,MapCoordinateY=52.1,L="11669:25,11819:25,11822:25,11823:25,51217:5,70226:2"},
{Id="9537",Name="Hurley Blackbreath",Story="To say Blackbreath is a regular at the Grim Guzzler would be something of an understatement. In over a decade, the mischievous drunkard has left the tavern only once to steal a top-secret recipe for Thunderbrew Lager. Blackbreath has occasionally sobered up enough to make the concoction himself, and he claims it grants unimaginable strength and courage.",Portrait=M.."dungeons\\brd\\blackbreath-portrait",Frame=M.."dungeons\\brd\\blackbreath-frame",MapCoordinateX=51.2,MapCoordinateY=47.8,L="11735:25,18043:25,18044:25,22275:25,70226:2"},
{Id="9543",Name="Ribbly Screwspigot",Story="Screwspigot has a bad habit of borrowing money and squandering it on get-rich-quick schemes. His latest failure--Ribbly's Chewable Gunpowder--earned him a place on the hit list of Booty Bay's kingpin, Baron Revilgaz. Screwspigot has since fled to the Grim Guzzler, hoping to elude bounty hunters, friends, and family looking to cash in on the baron's bounty.",Portrait=M.."dungeons\\brd\\ribbly-portrait",Frame=M.."dungeons\\brd\\ribbly-frame",MapCoordinateX=51.9,MapCoordinateY=51.3,L="2663:25,2662:25,11742:25,11612:3"},
{Id="9502",Name="Phalanx",Story="Until recently, drunken brawls raged within the Grim Guzzler on an almost daily basis. Barkeep Plugger Spazzring has reduced the frequency of these scuffles with Phalanx, a mighty golem bouncer programmed to maintain order in the tavern and eliminate raucous patrons with extreme force.",Portrait=M.."dungeons\\brd\\phalanx-portrait",Frame=M.."dungeons\\brd\\phalanx-frame",MapCoordinateX=54.5,MapCoordinateY=50.6,L="11744:33,11745:33,22212:33,70226:2"},
{Id="9499",Name="Plugger Spazzring",Story="They say that at the Grim Guzzler everyone knows your name. This sense of camaraderie is due to the hard work of Spazzring, a leper gnome who sought a new life in Blackrock Depths after the fall of Gnomeregan. Despite his history of dabbling with evil as a warlock, he takes pride in his job as the tavern's barkeep, making sure that his patrons' mugs never run dry.",Portrait=M.."dungeons\\brd\\spazzring-portrait",Frame=M.."dungeons\\brd\\spazzring-frame",MapCoordinateX=53.1,MapCoordinateY=49.4,L="18653:18,12793:18,12791:18"},
{Id="9156",Name="Ambassador Flamelash",Story="For his unwavering service to Ragnaros, Flamelash ascended to the rank of ambassador to the Dark Iron clan. This depraved being initially despised his dwarven allies, but he has come to respect their penchant for destruction. As a show of solidarity, Flamelash guards the Chamber of Enchantment, a sacred location used by the dwarves to empower their weaponry.",Portrait=M.."dungeons\\brd\\flamelash-portrait",Frame=M.."dungeons\\brd\\flamelash-frame",MapCoordinateX=56.2,MapCoordinateY=39.5,L="11809:25,11812:25,11814:25,11832:25,11808:2,70226:2,51217:5"},
{Id="8923",Name="Panzor the Invincible",Story="An elusive golem, rarely seen among the general population of Blackrock Depths. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\brd\\panzor-portrait",Frame=M.."dungeons\\brd\\panzor-frame",MapCoordinateX=50.6,MapCoordinateY=29.2,IsRare=true,L="11785:25,11786:25,11787:25,22245:25"},
{Id="9040",Name="The Seven",Story="Centuries ago, sorcerer-thane Thaurissan and seven of his most powerful Dark Iron allies accidentally summoned Ragnaros into Azeroth and damned their entire clan to enslavement. Although the Seven perished during the ritual, their restless spirits still linger in Blackrock Depths, cursed to serve their elemental master and the current Dark Iron ruler.",Portrait=M.."dungeons\\brd\\seven-portrait",Frame=M.."dungeons\\brd\\seven-frame",MapCoordinateX=55.9,MapCoordinateY=20.7,L="11920:25,11923:25,11929:25,11926:25,11921:25,11922:25,11925:25,11927:25"},
{Id="9938",Name="Magmus",Story="Ambassador Flamelash charged the molten giant Magmus with guarding Emperor Dagran Thaurissan's throne room, but not even this act put the Dark Iron ruler's concerns to rest. Ever fearful of assassins, the emperor also granted Magmus control over a series of fire-breathing statues outside his royal chambers.",Portrait=M.."dungeons\\brd\\magmus-portrait",Frame=M.."dungeons\\brd\\magmus-frame",MapCoordinateX=76.8,MapCoordinateY=10.4,L="11746:20,11935:20,22208:20,22395:20,22400:20,70226:2,51217:5"},
{Id="9019",Name="Emperor Dagran Thaurissan",Story="Emperor Dagran Thaurissan rules alongside Princess Moira of the rival Bronzebeard clan. Debate rages over whether the emperor ensorcelled his bride or she willingly joined him. Whatever the truth, Thaurissan's continued presence bodes ill for the future of his clan. So long as he lives, the Dark Irons will remain pawns of Ragnaros, and a dire threat to kingdoms throughout Azeroth.",Portrait=M.."dungeons\\brd\\emperor-portrait",Frame=M.."dungeons\\brd\\emperor-frame",MapCoordinateX=85.6,MapCoordinateY=10.4,L="51217:100,56104:30,11924:20,11928:20,11932:20,11934:20,22207:20,11815:20,11930:20,11931:20,11933:20,22204:20,70226:3,11684:1,12553:25:n1,12554:25:n1,12556:25:n1,12557:25:n1"},
}}
ZLDB.DG["CG"]={
Name="Crescent Grove",
Story="Hidden above the waterfalls of Mystral Lake, the Crescent Grove was once a tranquil sanctuary where druids and peaceful residents like Kalanar Brightshine tended to the forest in harmony. However, a dark shadow has fallen over the grove, clouding the minds of all who dwell within. The Foulweald furbolgs, fleeing madness in the north, found no refuge here; instead, they were twisted into the aggressive Groveweald tribe, their shamans and elders further fueling their savagery. Even the druidic protectors, led by Keeper Ranathos, have fallen silent or emerged warped by a deeper, more sinister source of corruption. Now, the Cenarion Circle calls upon brave souls to delve into the depths of the stone labyrinth and root out the evil festering at the grove's heart before it spreads across all of Kalimdor.",
Background=M.."dungeons\\cg\\background",
GridBackground=M.."dungeons\\cg\\grid-background",
MapId=34,
IconScale=0.9,
MinLevel=33,
MaxLevel=39,
Entrances={{MapContinentId=1,MapCoordinateX=51,MapCoordinateY=77.3,MapZoneId=1}},
Type=T.Dungeon,
Key="CG",
Bosses={
{Id="92107",Name="Grovetender Engryss",Story="Under the influence of the furbolg elders' persistent delusions, Grovetender Engryss has abandoned his original duty to protect the sanctuary. He now lashes out with irrational ferocity, acting as a tireless shield for the spiritual leaders whose maddening whisperings have entirely warped his sense of purpose.",Portrait=M.."dungeons\\cg\\engryss-portrait",Frame=M.."dungeons\\cg\\engryss-frame",MapCoordinateX=52.1,MapCoordinateY=36.7,L="83220:24,83221:24,83222:24,83223:24,83224:5,51217:1"},
{Id="92109",Name="Keeper Ranathos",Story="Keeper Ranathos was originally stationed at the grove to repel the spreading taint, but his own erratic reports eventually signaled a tragic failure. Now fully corrupted and warped, he embodies the very evil he once fought, serving as a grim warning of the darkness that has taken hold beneath the waterfalls of Mystral Lake.",Portrait=M.."dungeons\\cg\\ranathos-portrait",Frame=M.."dungeons\\cg\\ranathos-frame",MapCoordinateX=43.3,MapCoordinateY=43.5,L="83225:24,83226:24,83227:24,83228:24,83229:5,51217:1"},
{Id="92108",Name="High Priestess A'lathea",Story="Information regarding High Priestess A'lathea is absent from current Cenarion Circle research, leaving her as a shadowy figure known only to reside within the deeper reaches of the Crescent Grove.",Portrait=M.."dungeons\\cg\\alathea-portrait",Frame=M.."dungeons\\cg\\alathea-frame",MapCoordinateX=57.6,MapCoordinateY=68.1,L="51217:1,83210:10,83211:30,83209:30,83208:30"},
{Id="92111",Name="Fenektis the Deceiver",Story="Beyond his reputation as a hostile and cunning presence inside the grove, Fenektis the Deceiver remains a total enigma to scholars and adventurers alike.",Portrait=M.."dungeons\\cg\\fenektis-portrait",Frame=M.."dungeons\\cg\\fenektis-frame",MapCoordinateX=44,MapCoordinateY=78.9,L="83212:25,83213:25,83214:25,83215:25,51217:1"},
{Id="92110",Name="Master Raxxieth",Story="Identified as the core of the rot within the Crescent Grove, Master Raxxieth is the sinister architect of the region's downfall. He thrives on the misery and madness he has sown among both the furbolg and the druidic keepers, and his removal is the only hope for preventing the corruption from spreading as far as Mulgore.",Portrait=M.."dungeons\\cg\\raxxieth-portrait",Frame=M.."dungeons\\cg\\raxxieth-frame",MapCoordinateX=60.3,MapCoordinateY=88.6,L="60258:1,51217:5,83219:25,83218:25,83217:25,83216:25"},
}}
ZLDB.DG["DEADMINES"]={
Name="The Deadmines",
Story="Once the greatest gold production center in the human lands, the Deadmines were abandoned when the Horde razed Stormwind city during the First War. Now the Defias Brotherhood has taken up residence and turned the dark tunnels into their private sanctum. It is rumored that the thieves have conscripted the clever goblins to help them build something terrible at the bottom of the mines - but what that may be is still uncertain. Rumor has it that the way into the Deadmines lies through the quiet, unassuming village of Moonbrook.",
Background=M.."dungeons\\deadmines\\background",
GridBackground=M.."dungeons\\deadmines\\grid-background",
MapId=21,
IconScale=0.9,
MinLevel=16,
MaxLevel=24,
Entrances={{MapContinentId=2,MapCoordinateX=25,MapCoordinateY=51,MapZoneId=32}},
Type=T.Dungeon,
Key="DEADMINES",
Bosses={
{Id="61961",Name="Jared Voss",Story="Jared Voss is the son of William Voss, a renowned alchemist whose shop and home were burned down with Stormwind and never rebuilt, leaving his family homeless and bitter toward the nobility responsible. Jared, apprenticed to the Stonemasons before his father's death, inherited both his alchemical talents and his burning resentment.",Portrait=M.."dungeons\\deadmines\\jared-portrait",Frame=M.."dungeons\\deadmines\\jared-frame",MapCoordinateX=28.5,MapCoordinateY=30.8,L="55377:50,55375:25,55376:25"},
{Id="644",Name="Rhahk'Zor",Story="As the Defias Brotherhood's head foreman of the Deadmines, Rhahk'Zor supervises and \"motivates\" the laborers. His methods, though unconventional, are quite effective.",Portrait=M.."dungeons\\deadmines\\rhahk-portrait",Frame=M.."dungeons\\deadmines\\rhahk-frame",MapCoordinateX=17.6,MapCoordinateY=53.4,Abilities={{Effect="Rhahk'Zor slams an enemy, dealing 64 to 86 physical damage and stunning them for 3 seconds.",Icon="INV_Gauntlets_05",Id="6304",Name="Rhahk'Zor Slam"}},L="9496:100,872:33,5187:33,80706:33"},
{Id="3586",Name="Miner Johnson",Story="An elusive miner, rarely seen among the general population of the Deadmines. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\deadmines\\miner-portrait",Frame=M.."dungeons\\deadmines\\miner-frame",MapCoordinateX=31,MapCoordinateY=43.8,IsRare=true,Abilities={{Effect="Miner Johnson lunges his pickaxe into his enemy, piercing their armor and reducing its armor value by 10% for 10 seconds.",Icon="Spell_Shadow_VampiricAura",Id="6016",Name="Pierce Armor"}},L="5444:65,5443:35"},
{Id="643",Name="Sneed",Story="Sneed was hired as a lumbermaster for his ruthless efficiency. His goal is simple: construct a juggernaut as cheaply as possible. By using the shredder he built himself to lead production, he achieves terrifyingly fast results.",Portrait=M.."dungeons\\deadmines\\sneed-portrait",Frame=M.."dungeons\\deadmines\\sneed-frame",MapCoordinateX=29.8,MapCoordinateY=74.5,Abilities={{Effect="Sneed disarms his enemy, forcing them to stop wielding their weapon for 5 seconds.",Flags={F.Tank},Icon="Ability_Warrior_Disarm",Id="6713",Name="Disarm"}},L="50256:100,5195:65,80707:60,5194:35"},
{Id="1763",Name="Gilnid",Story="Glinid is a masterful engineer and head smelter of the Defias Brotherhood's operations. He ensures the juggernaut is loaded with sufficient cannons and ammunition and will tolerate no breaks until the work is complete.",Portrait=M.."dungeons\\deadmines\\gilnid-portrait",Frame=M.."dungeons\\deadmines\\gilnid-frame",MapCoordinateX=38.8,MapCoordinateY=51.4,Abilities={{Effect="Glinid throws molten metal to an enemy, inflicting fire damage every 3 seconds, increasing the time between their attacks by 54%, and reducing their movement by 50% for 15 seconds.",Icon="Spell_Fire_Fireball",Id="5213",Name="Molten Metal"}},L="5199:55,1156:45"},
{Id="61963",Name="Masterpiece Harvester",Story="The goblin mechanics of the Defias pride themselves on their greatest creation: the Masterpiece Harvester. Built deep within their hidden workshop, it is the finest harvest golem they have ever produced.",Portrait=M.."dungeons\\deadmines\\harvester-portrait",Frame=M.."dungeons\\deadmines\\harvester-frame",MapCoordinateX=36.8,MapCoordinateY=25.2,L="55380:50,55378:25,55379:25"},
{Id="646",Name="Mr. Smite",Story="As Captain Greenskin's first mate, Smite is tasked with keeping the crew on their toes. Smite is a skilled weaponmaster, trained in all manner of slicing and bashing.",Portrait=M.."dungeons\\deadmines\\smite-portrait",Frame=M.."dungeons\\deadmines\\smite-frame",MapCoordinateX=71.3,MapCoordinateY=11.6,Abilities={{Effect="Mr. Smite's nimble reflexes allows him to increase his chance to parry by 75% for 8 seconds.",Icon="Ability_MeleeDamage",Id="6264",Name="Nimble Reflexes"},{Effect="Mr. Smite slam his enemy, inflicting 50 physical damage and stunning them for 3 seconds.",Icon="INV_Gauntlets_05",Id="6435",Name="Smite Slam"},{Effect="Mr. Smite stomps the ground, stunning all enemies for 10 seconds.",Flags={F.Important,F.Deadly},Icon="Ability_WarStomp",Id="6432",Name="Smite Stomp"},{Effect="Mr. Smite gains a chance to do two additional attacks.",Icon="Ability_GhoulFrenzy",Id="3417",Name="Thrash"}},L="5192:30,5196:30,81007:20,7230:20"},
{Id="647",Name="Captain Greenskin",Story="Captain of the juggernaut-in-progress, Greenskin hails from Booty Bay where he formerly led a fleet of pirate vessels.",Portrait=M.."dungeons\\deadmines\\captain-portrait",Frame=M.."dungeons\\deadmines\\captain-frame",MapCoordinateX=75.6,MapCoordinateY=22.4,Abilities={{Effect="Captain Greenskin stabs his enemy with his poisoned harpoon, inflicting physical damage plus 30, then an additional 45 nature damage every 10 seconds for 1 minute.",Flags={F.Poison},Icon="Ability_Poisons",Id="5208",Name="Poisoned Harpoon"},{Effect="Captain Greenskin cleaves all enemies in front of him.",Icon="Ability_Warrior_Cleave",Id="845",Name="Cleave"}},L="5201:40,5200:30,10403:30"},
{Id="639",Name="Edwin VanCleef",Story="Formerly the leader of the Stonemasons Guild, disputes with the House of Nobles led VanCleef to leave Stormwind City and create the Defias Brotherhood. VanCleef then claimed the Deadmines as a base of operations to construct the juggernaut that would begin his retribution.",Portrait=M.."dungeons\\deadmines\\vancleef-portrait",Frame=M.."dungeons\\deadmines\\vancleef-frame",MapCoordinateX=75.7,MapCoordinateY=28.1,Abilities={{Effect="Edwin VanCleef gains a chance to do two additional attacks.",Icon="Ability_GhoulFrenzy",Id="3417",Name="Trash"},{Effect="Edwin VanCleef call upon his allies, summoning a pair of Defias Blackguards to assist him during the battle.",Flags={F.Important,F.Tank},Icon="Ability_Warrior_BattleShout",Id="5200",Name="VanCleef's Allies"}},L="29980:100,5193:30,5202:30,5191:20,10399:20,81005:8"},
{Id="645",Name="Cookie",Story="No one except Edwin VanCleef knows how or why Cookie was promoted to be the ship's cook. For pirates, though, a meal is a meal.",Portrait=M.."dungeons\\deadmines\\cookie-portrait",Frame=M.."dungeons\\deadmines\\cookie-frame",MapCoordinateX=81,MapCoordinateY=24.5,Abilities={{Effect="Cookie throws some acidic goop onto his enemies, cause everyone nearby to receive nature damage every 5 seconds for 30 seconds.",Flags={F.Poison},Icon="INV_Drink_06",Id="6306",Name="Acid Splash"},{Effect="Cookie eats some of his food, healing him for 111 to 129 health.",Flags={F.Interruptible},Icon="Spell_Holy_Heal",Id="5174",Name="Cookie's Cooking"}},L="9338:100,5197:65,80708:60,5198:35,8490:15"},
}}
ZLDB.DG["DME"]={
Name="Dire Maul East",
Story="The Warpwood Quarter is located east in Dire Maul. It has been taken over by the nefarious Alzzin the Wildshaper, a satyr who has corrupted the Fruit of Fertility so that it produces vile Felvine Shards. Alzzin has attracted all manner of corrupted plant life, satyrs, mages and demons to his cause. The entire district is overgrown with crazed plant life.",
Background=M.."dungeons\\dme\\background",
GridBackground=M.."dungeons\\dme\\grid-background",
MapId=13,
IconScale=0.7,
MinLevel=55,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=81.5,MapCoordinateY=40.7,MapZoneId=8},{MapContinentId=1,MapCoordinateX=94.3,MapCoordinateY=66.4,MapZoneId=8}},
Type=T.Dungeon,
Key="DME",
Bosses={
{Id="14354",Name="Pusillin",Story="A cowardly little imp, tricking adventurers into following him, only to turn on them, killing them and stealing all the belongings from their bodies.",Portrait=M.."dungeons\\dme\\pusillin-portrait",Frame=M.."dungeons\\dme\\pusillin-frame",MapCoordinateX=89.7,MapCoordinateY=75.3,L="18267:100,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10"},
{Id="13280",Name="Hydrospawn",Story="When the satyr Zevrim Thornhoof sought to control the elementals in Dire Maul, he focused on Hydrospawn, who calmly resided in the pool beneath his altar. As he performed his profane sacrificial rituals, the elemental grew agitated and restless, striking out at Thornhoof's demonic minions. As the years passed, Thornhoof used his victims' energies to whip Hydrospawn into unbridled fury, little by little binding its will to the satyr's commands.",Portrait=M.."dungeons\\dme\\hydrospawn-portrait",Frame=M.."dungeons\\dme\\hydrospawn-frame",MapCoordinateX=76.4,MapCoordinateY=75,MapIsBelow=true,L="18305:20,18307:20,18317:20,18322:20,18324:20,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10,51217:5,70226:2"},
{Id="11490",Name="Zevrim Thornhoof",Story="Desperate to show his worth to the Burning Legion, Zevrim Thornhoof told his masters he could enslave the formidable ancients who still roamed Dire Maul. When his own power proved insufficient, Thornhoof turned to other living creatures for additional energy, butchering them atop his sacrificial altar and harvesting their essence in their final, agonizing moments.",Portrait=M.."dungeons\\dme\\zevrim-portrait",Frame=M.."dungeons\\dme\\zevrim-frame",MapCoordinateX=76.4,MapCoordinateY=79.4,MapIsBelow=true,L="18306:20,18308:20,18313:20,18319:20,18323:20,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10,70226:2,51217:5"},
{Id="14327",Name="Lethtendris",Story="Dire Maul's warped energy drew Lethtendris from afar, giving her hope of satisfying her unbearable craving for arcane magic. Using the sinews and ligaments of sacrificial victims, she constructed a web to siphon the corrupt power out of the east wing. To her delight, she discovered that the device has the capacity to gather vast reserves of overwhelming strength, enough to destroy all of her enemies.",Portrait=M.."dungeons\\dme\\lethtendris-portrait",Frame=M.."dungeons\\dme\\lethtendris-frame",MapCoordinateX=74.3,MapCoordinateY=76.9,L="18301:25,18302:25,18311:25,18325:25,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1"},
{Id="11492",Name="Alzzin the Wildshaper",Story="Alzzin the Wildshaper was not always the creature that now festers within Dire Maul. Once a druid of Hyjal and a bearer of the very title he still claims, he has become a twisted mockery of the ideals he once upheld. Now counted among the satyrs, Alzzin seeks nothing less than the total corruption of Feralas. Within the Shrine of Eldretharr, he has bound ancient spirits to his will, drawing upon the vitality of the forest to shape and control it as he pleases. Where he once nurtured life, he now perverts it, turning the wilds into an extension of his own corruption.",Portrait=M.."dungeons\\dme\\alzzin-portrait",Frame=M.."dungeons\\dme\\alzzin-frame",MapCoordinateX=75.8,MapCoordinateY=55.3,L="51217:100,18309:10,18310:10,18312:10,18314:10,18315:10,18318:10,18321:10,18326:10,18327:10,18328:10,18356:10,18357:10,18358:10,18359:10,18360:10,18361:10,18362:10,18363:10,18364:10,18401:10,47413:10,47415:10,83574:10,70226:3"},
}}
ZLDB.DG["DMN"]={
Name="Dire Maul North",
Story="The Gordok Commons are located north in Dire Maul. This area of the city has been taken over by the Gordok, the elite members of the Gordunni ogre clan, and are now the seat of power for King Gordok himself. By tradition, however, whoever slays the king will become the new King Gordok.",
Background=M.."dungeons\\dmn\\background",
GridBackground=M.."dungeons\\dmn\\grid-background",
MapId=13,
IconScale=0.7,
MinLevel=57,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=70.2,MapCoordinateY=13.5,MapZoneId=8}},
Type=T.Dungeon,
Key="DMN",
Bosses={
{Id="14326",Name="Guard Mol'dar",Story="Mol'dar is a zealously loyal guard from the Gordok ogres. He is convinced King Gordok gifted him with a pair of enchanted gauntlets that have enabled him to become his people's arm wrestling champion for six years running. In truth, King Gordok threw the powerful armor away; Mol'dar simply found it first.",Portrait=M.."dungeons\\dmn\\moldar-portrait",Frame=M.."dungeons\\dmn\\moldar-frame",MapCoordinateX=52.4,MapCoordinateY=44.5,L="18450:8,18451:8,18458:8,18459:8,18460:8,18462:8,18463:8,18464:8,18493:8,18494:8,18496:8,18497:8,18498:8,51217:5,70226:2"},
{Id="14322",Name="Stomper Kreeg",Story="On more than one occasion, skulking assassins have met their doom after accidentally disturbing Kreeg's ale mug. Though he's often passed out drunk on duty, nothing rouses the ogre into a berserker fury faster than the sound of his precious drink splattering on the stone floor.",Portrait=M.."dungeons\\dmn\\kreeg-portrait",Frame=M.."dungeons\\dmn\\kreeg-frame",MapCoordinateX=46.3,MapCoordinateY=38.5,L="18425:40,70226:2"},
{Id="14321",Name="Guard Fengus",Story="Ever since Cho'Rush the Observer told him he was destined to meet a mate while on duty, Fengus has spent almost every waking moment patrolling Gordok territory.",Portrait=M.."dungeons\\dmn\\fengus-portrait",Frame=M.."dungeons\\dmn\\fengus-frame",MapCoordinateX=39.2,MapCoordinateY=45.4,L="18450:13,18451:13,18458:13,18459:13,18460:13,18462:13,18463:13,18464:13,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1"},
{Id="14323",Name="Guard Slip'kik",Story="Some might think Slip'kik is merely cautious, but he's also lazy. Rather than challenge King Gordok directly, Slip'kik tinkers with traps and old, broken magical devices, hoping to eventually deliver a coup de grace without an ounce of risk or a drop of sweat.",Portrait=M.."dungeons\\dmn\\slipkik-portrait",Frame=M.."dungeons\\dmn\\slipkik-frame",MapCoordinateX=21.8,MapCoordinateY=37.5,L="18450:8,18451:8,18458:8,18459:8,18460:8,18462:8,18463:8,18464:8,18493:8,18494:8,18496:8,18497:8,18498:8,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18362:1,18361:1,18363:1,18364:1,18401:1"},
{Id="14325",Name="Captain Kromcrush",Story="Even among ogres, Captain Kromcrush is infamous for his hair-trigger rage toward anyone who dares to insult him or King Gordok. He crushes dissent ruthlessly, but he has still less patience for those who continue to spread the rumor of his torrid affair with a gnoll long ago.",Portrait=M.."dungeons\\dmn\\kromcrush-portrait",Frame=M.."dungeons\\dmn\\kromcrush-frame",MapCoordinateX=27.5,MapCoordinateY=28.4,L="18502:25,18503:25,18505:25,18507:25,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1"},
{Id="11501",Name="King Gordok",Story="To rule the Gordok ogres, one must simply proclaim oneself king... and then destroy all who might disagree. King Gordok--then merely known as Ulrok--solidified his power by convincing a dozen of his people's strongest warriors to challenge the king at the same time. The wild melee left most of the contestants dead or wounded, and Ulrok's blade easily cut down the survivors and the battle-weary king. To this day, Gordok ogres speak in hushed tones about the \"Day of Da Blood.\"",Portrait=M.."dungeons\\dmn\\gordok-portrait",Frame=M.."dungeons\\dmn\\gordok-frame",MapCoordinateX=27.8,MapCoordinateY=11.8,L="51217:100,18520:13,18522:13,18521:13,18523:13,18524:13,18525:13,18526:13,18527:13,47413:10,47415:10,18780:9,70226:3,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1,18538:1:n2,18655:11:n2,18482:11:n2,18481:11:n2,18480:11:n2,18479:11:n2,18478:11:n2,18477:11:n2,18476:11:n2,18475:11:n2,18532:23:n2,18531:23:n2,18530:23:n2,18499:23:n2,18537:25:n2,18534:25:n2,18533:25:n2,18495:25:n2,18529:33:n2,18528:33:n2,18500:33:n2"},
}}
ZLDB.DG["DMR"]={
Name="Dragonmaw Retreat",
Story="Hidden within the decrepit mining facilities far to the east of the Wetlands, the Dragonmaw Retreat serves as the final bastion for the seasoned veterans of the Second War. Following their defeat at Grim Batol, these orcs have gathered beneath the mountain to rebuild their strength, kidnapping citizens from Menethil Harbor and conducting heinous rituals to bolster their ranks. Under the fanatical leadership of Zuluhed the Whacked, who has returned bearing a shard of the legendary Demon Soul, the clan has once again begun the brutal subjugation of the Red Dragonflight. Adventurers must navigate the unstable shafts and ancient dwarven halls to extinguish the Dragonmaw's influence before their 'Dark Horde' can rise again.",
Background=M.."dungeons\\dmr\\background",
GridBackground=M.."dungeons\\dmr\\grid-background",
MapId=41,
IconScale=0.9,
MinLevel=26,
MaxLevel=35,
Entrances={{MapContinentId=2,MapCoordinateX=67.3,MapCoordinateY=63.3,MapZoneId=39}},
Type=T.Dungeon,
Key="DMR",
Bosses={
{Id="62057",Name="Gowlfang",Story="Gowlfang was once the leader of the Mosshide gnolls before he abandoned his people to side with the Dragonmaw orcs. Driven by a slobbering, unbridled rage, this 'big betrayer' now leads a splinter group of Mosshides in service to the green-skinned warriors. He guards the entrance to the mountain caves with savage ferocity, eager to prove his worth to the masters of the fire-breathing lizards.",Portrait=M.."dungeons\\dmr\\gowlfang-portrait",Frame=M.."dungeons\\dmr\\gowlfang-frame",MapCoordinateX=12.1,MapCoordinateY=36.6,L="41571:20,41572:20,41573:20,41574:20,41575:20"},
{Id="62066",Name="Cavernweb Broodmother",Story="The Dragonmaw orcs have used their dark arts to enslave and magically enhance the arachnids living within the mining shafts of Grim Batol. The Cavernweb Broodmother is the terrifying result of these rituals, possessing an unparalleled poison that causes agonizing pain. She and her enhanced brood act as a lethal defense mechanism, protecting the deeper reaches of the retreat from any who would disrupt the clan's operations.",Portrait=M.."dungeons\\dmr\\broodmother-portrait",Frame=M.."dungeons\\dmr\\broodmother-frame",MapCoordinateX=33.1,MapCoordinateY=46.3,L="58039:20,58040:20,58041:20,58042:20,58043:20,37009:10"},
{Id="62067",Name="Web Master Torkon",Story="Little information is available regarding Web Master Torkon, though his presence has been noted as a significant inhabitant of the Dragonmaw Retreat.",Portrait=M.."dungeons\\dmr\\torkon-portrait",Frame=M.."dungeons\\dmr\\torkon-frame",MapCoordinateX=37.5,MapCoordinateY=63.7,L="41874:100,41566:20,41567:20,41568:20,41569:20,41570:20"},
{Id="62071",Name="Garlok Flamekeeper",Story="Garlok is a powerful pyremaster who nurtures the 'Eternal Flame,' a source of potent energy kept hidden by the orcs' primitive sorcery. He protects this ancient magic with a fanatical devotion, using the flame to power the Dragonmaw's machinations. For those seeking to undermine the clan or claim the relic for the Dark Lady, Garlok stands as a wall of incinerating heat.",Portrait=M.."dungeons\\dmr\\garlok-portrait",Frame=M.."dungeons\\dmr\\garlok-frame",MapCoordinateX=42,MapCoordinateY=64.7,L="41578:25,41579:25,41580:25,41581:25"},
{Id="62069",Name="Halgan Redbrand",Story="A spectral reminder of the mine's dwarven past, Halgan Redbrand haunts the halls where his family once worked. He guards the Redbrand Tablet, an ancient piece of dwarven typography that holds a shocking secret: the lineage of the Redbrand family, long thought to be Bronzebeard, actually lies deep within the Wildhammer clan. Halgan's lingering ghost is all that remains of this forgotten chapter of Khaz Modan's history.",Portrait=M.."dungeons\\dmr\\halgan-portrait",Frame=M.."dungeons\\dmr\\halgan-frame",MapCoordinateX=34.8,MapCoordinateY=92.5,L="58044:25,58045:25,58046:25,58047:25,76:6,77:6"},
{Id="62068",Name="Slagfist Destroyer",Story="An ancient stone golem still following protocols from the mine's original dwarven builders, Slagfist Destroyer roams the unstable tunnels of the retreat. Powered by a glowing runestone, this crumbling construct views the orcish occupiers and intruding adventurers alike as threats to be dismantled. It is a mindless relic of industry, serving as a dangerous obstacle in the dark.",Portrait=M.."dungeons\\dmr\\slagfist-portrait",Frame=M.."dungeons\\dmr\\slagfist-frame",MapCoordinateX=45,MapCoordinateY=90.1,L="41558:25,41559:25,41560:25,41719:25"},
{Id="62070",Name="Overlord Blackheart",Story="A true monster through and through, Overlord Blackheart is the architect of the vicious raiding parties that plague the Wetlands. Responsible for the abduction and death of many citizens of Menethil Harbor, he is the iron fist of the Dragonmaw veterans. As the primary military leader within the retreat, his demise is essential to ensuring the safety of the southern lands.",Portrait=M.."dungeons\\dmr\\blackheart-portrait",Frame=M.."dungeons\\dmr\\blackheart-frame",MapCoordinateX=53.3,MapCoordinateY=65.5,L="41724:25,41725:25,41726:25,41727:25,74:6"},
{Id="62038",Name="Elder Hollowblood",Story="Records regarding Elder Hollowblood are remarkably scarce, aside from the fact that he is a confirmed denizen of the Dragonmaw Retreat.",Portrait=M.."dungeons\\dmr\\hollowblood-portrait",Frame=M.."dungeons\\dmr\\hollowblood-frame",MapCoordinateX=56.9,MapCoordinateY=55.8,L="41720:25,41721:25,41722:25,41723:25,31:6"},
{Id="62072",Name="Searistrasz",Story="The brother of Nydiszanz, Searistrasz is a noble red dragon currently suffering the 'plight of submission.' Enslaved by the Dragonmaw using the power of the Demon Soul, he is forced to follow their heinous bidding within the ancient mines. His painful cries echo through the caverns, a tragic testament to the orcs' continued subjugation of the Red Dragonflight.",Portrait=M.."dungeons\\dmr\\searistrasz-portrait",Frame=M.."dungeons\\dmr\\searistrasz-frame",MapCoordinateX=52.9,MapCoordinateY=36.2,L="41561:20,41562:20,41563:20,41564:20,41565:20"},
{Id="62037",Name="Zuluhed the Whacked",Story="The mad Chieftain of the Dragonmaw Clan, Zuluhed has returned to Azeroth bearing a glimmering shard of the original Demon Soul. While some within his clan, like Korlag Doomsong, view him as a coward who abandoned them for his own glory, Zuluhed continues to plot in the underbelly of Grim Batol. He remains determined to unite the chieftains under his banner, using the shard's tainted power to once again enslave the flight of the Dragon Queen.",Portrait=M.."dungeons\\dmr\\zuluhed-portrait",Frame=M.."dungeons\\dmr\\zuluhed-frame",MapCoordinateX=41.9,MapCoordinateY=47.1,L="41845:20,41846:20,41847:20,41848:20,58099:20,69:5,71:5,41895:2"},
}}
ZLDB.DG["DMW"]={
Name="Dire Maul West",
Story="The Capital Gardens are located west in Dire Maul. The area might once have been a pristine city park district, but now the trees stand gray and withered, and the broken streets are full of dangerous ancients.",
Background=M.."dungeons\\dmw\\background",
GridBackground=M.."dungeons\\dmw\\grid-background",
MapId=13,
IconScale=0.7,
MinLevel=57,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=57.4,MapCoordinateY=39.2,MapZoneId=8},{MapContinentId=1,MapCoordinateX=57.4,MapCoordinateY=49.9,MapZoneId=8}},
Type=T.Dungeon,
Key="DMW",
Bosses={
{Id="11489",Name="Tendris Warpwood",Story="Tendris Warpwood was a staunch defender of Eldre'Thalas, his heart inexorably entwined with the fate of the city. When the Sundering shattered the land, his resolve never wavered, but as corruption seeped into the ruins over the next 10,000 years, so too did it infect the ancient's spirit.",Portrait=M.."dungeons\\dmw\\tendris-portrait",Frame=M.."dungeons\\dmw\\tendris-frame",MapCoordinateX=28.1,MapCoordinateY=75,L="18352:25,18353:25,18390:25,18393:25,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1"},
{Id="11488",Name="Illyanna Ravenoak",Story="Illyanna Ravenoak, along with her faithful companion Ferra, was once Prince Tortheldrin's most valued hunter, until she refused to carry out her leader's order to execute her friends. As punishment, he killed Illyanna and her bear, but he used his demonic power to bind their spirits to their bodies, condemning them to remain in Dire Maul as undead protectors.",Portrait=M.."dungeons\\dmw\\ravenoak-portrait",Frame=M.."dungeons\\dmw\\ravenoak-frame",MapCoordinateX=24.4,MapCoordinateY=81.5,L="18347:25,18349:25,18383:25,18386:25,55580:17,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1"},
{Id="11487",Name="Magister Kalendris",Story="When Prince Tortheldrin demanded the slaughter of the majority of his subjects, his most loyal lieutenants were tasked with executing his will. Magister Kalendris murdered many unsuspecting Shen'dralar without hesitation, but one of the doomed elves mortally wounded him during a destructive battle. Despite his demise, Kalendris's spirit still roams Dire Maul as a defender of Tortheldrin's rule.",Portrait=M.."dungeons\\dmw\\kalendris-portrait",Frame=M.."dungeons\\dmw\\kalendris-frame",MapCoordinateX=24.4,MapCoordinateY=68.7,L="18350:20,18351:20,18371:20,18374:20,18397:20,22309:15,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1"},
{Id="11467",Name="Tsu'zee",Story="An elusive ghost of a night elf, rarely seen among the denizens of the Capital Gardens. She is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter her in the first place...",Portrait=M.."dungeons\\dmw\\tsuzee-portrait",Frame=M.."dungeons\\dmw\\tsuzee-frame",MapCoordinateX=29.1,MapCoordinateY=66.5,L="18345:33,18346:33,18387:33"},
{Id="11496",Name="Immol'thar",Story="In a desperate bid to restore the power and immortality they lost when the Well of Eternity was destroyed, the Shen'dralar summoned a demon into the western wing of Dire Maul and captured him within a force field, allowing them to use the void terror's energy for their own spells. Unable to fight back or even move for nearly 10,000 years, Immol'thar could only watch and wait for the day he might break free and rend the flesh of his captors.",Portrait=M.."dungeons\\dmw\\immolthar-portrait",Frame=M.."dungeons\\dmw\\immolthar-frame",MapCoordinateX=10.2,MapCoordinateY=78.8,L="18370:10,18372:10,18377:10,18379:10,18381:10,18384:10,18385:10,18389:10,18391:10,18394:10,47413:10,47415:10,51217:5,70226:2,18356:1,18357:1,18358:1,18359:1,18360:1,18361:1,18362:1,18363:1,18364:1,18401:1"},
{Id="11486",Name="Prince Tortheldrin",Story="After the Well of Eternity's destruction, Prince Tortheldrin maintained control over the surviving Shen'dralar by imprisoning a demon in the ruins of Eldre'Thalas and letting his subjects siphon its strength. The exposure to demonic power twisted Tortheldrin's mind, and when the creature faltered, the prince ordered the deaths of many of his vassals so only he and his most fanatical followers would be left to enjoy the corrupt energy.",Portrait=M.."dungeons\\dmw\\prince-portrait",Frame=M.."dungeons\\dmw\\prince-frame",MapCoordinateX=20.9,MapCoordinateY=65.7,L="51217:100,18373:10,18375:10,18376:10,18378:10,18380:10,18382:10,18388:10,18392:10,18395:10,18396:10,70226:3"},
}}
ZLDB.DG["FH"]={
Name="Frostmane Hollow",
Story="Nestled deep within the frozen peaks of Dun Morogh, Frostmane Hollow has been the stronghold of the Frostmane tribe since long before the dwarves carved their great halls into the mountain. Once a proud and expansive people, the Frostmane have been pushed further and further into the cold by Ironforge's relentless expansion; their hunting grounds seized, their shrines defiled. What remains of the tribe has grown feral with fury, conducting raids on dwarven settlements with a ferocity born not of savagery, but of desperation. To the Frostmane, this is not war. It is survival.",
Background=M.."dungeons\\fh\\background",
GridBackground=M.."dungeons\\fh\\grid-background",
MapId=46,
IconScale=1,
MinLevel=13,
MaxLevel=20,
Entrances={{MapContinentId=2,MapCoordinateX=66.9,MapCoordinateY=40.3,MapZoneId=10}},
Type=T.Dungeon,
Key="FH",
Bosses={
{Id="tansha",Name="Tan'sha the Sleek",Story="Frostmane Hollow keeps its secrets well - Tan'sha the Sleek among them.",Portrait=M.."dungeons\\fh\\tansha-portrait",Frame=M.."dungeons\\fh\\tansha-frame",MapCoordinateX=16.2,MapCoordinateY=14.5,Abilities={{Icon="ability_mount_whitetiger",Id="tansha",Name="Tan'sha the Sleek",SubAbilities={{Effect="Tan'sha shouts at nearby enemies, causing them to flee in fear for 8 seconds.",Flags={F.Important},Icon="ability_golemthunderclap",Id="tanshaintimidatingshout",Name="Intimidating Shout"}}},{Icon="inv_ammo_arrow_02",Id="oboka",Name="Handler Oboka",SubAbilities={{Effect="Oboka stops fighting to heal Tan'sha.",Icon="ability_hunter_mendpet",Id="obokamendpet",Name="Mend Pet"}}}},L="162:33,184:33,197:33"},
{Id="ubukaz",Name="Battlemaster Ubukaz",Story="No chronicle, no record, no account - Battlemaster Ubukaz exists beyond the reach of history entirely.",Portrait=M.."dungeons\\fh\\ubukaz-portrait",Frame=M.."dungeons\\fh\\ubukaz-frame",MapCoordinateX=52.4,MapCoordinateY=39.4,Abilities={{Effect="At 20% remaining health, Ubukaz becomes enraged, increasing the damage he deals to his enemies significantly.",Flags={F.Enrage},Icon="spell_shadow_unholyfrenzy",Id="enrage",Name="Enrage"}},L="150:33,134:33,157:33"},
{Id="kanza",Name="Kan'za the Seer",Story="Those who have entered Frostmane Hollow and lived to speak of Kan'za the Seer are, if they exist at all, silent on the matter.",Portrait=M.."dungeons\\fh\\kanza-portrait",Frame=M.."dungeons\\fh\\kanza-frame",MapCoordinateX=32.4,MapCoordinateY=45.8,Abilities={{Effect="Kan'za starts the fight with two Frostmane Snowcaller that will assist him.\
\
These adds should be prioritized by the damage dealers over the boss",Flags={F.DPS},Icon="inv_misc_head_troll_01",Id="kanzaadds",Name="Kan'za's Adds",SubAbilities={{Effect="The Frostmane Snowcaller casts a frostbolt at his target, dealing frost damage and slowing them.",Flags={F.Interruptible},Icon="spell_frost_frostbolt02",Id="kanzaaddsfrostbolt",Name="Frostbolt"}}},{Effect="Kan'za casts a chilling blizzard, dealing frost damage in an area of effect.",Flags={F.Interruptible},Icon="spell_frost_icestorm",Id="kanzablizzard",Name="Blizzard"},{Effect="Kan'za casts a frostbolt at his target, dealing frost damage and slowing them.",Flags={F.Interruptible},Icon="spell_frost_frostbolt02",Id="kanzafrostbolt",Name="Frostbolt"}},L="205:33,241:33,213:33"},
{Id="hailar",Name="Hailar the Frigid",Story="The frozen depths of Frostmane Hollow have claimed many lives; whether any of them ever learned who Hailar the Frigid truly was remains unknown.",Portrait=M.."dungeons\\fh\\hailar-portrait",Frame=M.."dungeons\\fh\\hailar-frame",MapCoordinateX=30.5,MapCoordinateY=86.1,Abilities={{Effect="Hailar starts the fight with five Frostmane Ritualists that will keep on healing him as long as they are alive.\
\
The group needs to kill these adds before being able to kill Hailar.",Flags={F.DPS,F.Important},Icon="inv_misc_head_troll_01",Id="hailaradds",Name="Frostmane Ritualists"},{Effect="Hailar casts a flash freeze, blasting all enemies within 10 yards for 56 frost damage and freezing them in place for up to 5 seconds.",Flags={F.Deadly},Icon="spell_frost_frostnova",Id="16803",Name="Flash Freeze"},{Effect="Hailar casts a frostbolt at his target, dealing frost damage and slowing them.",Flags={F.Interruptible},Icon="spell_frost_frostbolt02",Id="hailarfrostbolt",Name="Frostbolt"}},L="110:33,126:33,116:33"},
}}
ZLDB.DG["GC"]={
Name="Gilneas City",
Story="Once the proud jewel of the peninsula, Gilneas City has become a fractured battlefield of civil war, draconic shadow, and feral madness. While the Greymane Wall has fallen, the city remains an impenetrable fortress held by royalist forces and their mysterious benefactors. Beneath the surface of the rebellion led by Lord Darius Ravenwood, a darker rot persists-the Harlow family, secret agents of the Black Dragonflight, have manipulated the kingdom's pride to fuel years of decay. Adventurers must navigate the blood-stained streets to recover lost family deeds, stolen masterpieces, and ancient manuscripts of hydromancy, all while deciding the ultimate fate of King Genn Greymane himself.",
Background=M.."dungeons\\gc\\background",
GridBackground=M.."dungeons\\gc\\grid-background",
MapId=32,
IconScale=0.9,
MinLevel=43,
MaxLevel=52,
Entrances={{MapContinentId=2,MapCoordinateX=27.4,MapCoordinateY=30.1,MapZoneId=15}},
Type=T.Dungeon,
Key="GC",
Bosses={
{Id="61419",Name="Matthias Holtz",Story="WhiIn the wake of the worgen outbreak, Holtz and his detachment enforced a strict lockdown over the city’s entrance district after it was overrun, sealing it off in a desperate attempt to contain the chaos. Though little is known of the man himself, his role in those frantic hours endures as a testament to the grim measures taken to preserve what remained of Gilneas.",Portrait=M.."dungeons\\gc\\holtz-portrait",Frame=M.."dungeons\\gc\\holtz-frame",MapCoordinateX=75.8,MapCoordinateY=40.5,L="61305:33,61304:33,61306:33,61307:2"},
{Id="61420",Name="Packmaster Ragetooth",Story="As leader of the Darkpelt pack, he spearheaded the worgen assault that overran the city’s entrance, turning once-guarded streets into hunting grounds. His ferocity forced the crown’s soldiers to seal the district under strict lockdown, dispatching royalist detachments to contain the spread and cull the beasts within.",Portrait=M.."dungeons\\gc\\ragetooth-portrait",Frame=M.."dungeons\\gc\\ragetooth-frame",MapCoordinateX=84.6,MapCoordinateY=63.5,L="61300:33,61301:33,61302:33,61303:2"},
{Id="61421",Name="Judge Sutherland",Story="A man of immense cruelty, Judge Sutherland presided over the meritless conspiracy trials that saw the prominent Glaymore family butchered one by one. He continues to pass his brutal judgments with each swing of his gavel, acting as a cold reminder of the corruption that turned the kingdom's justice into a weapon of fear.",Portrait=M.."dungeons\\gc\\sutherland-portrait",Frame=M.."dungeons\\gc\\sutherland-frame",MapCoordinateX=77.2,MapCoordinateY=84.1,L="61308:25,61309:25,61310:25,61311:25,61312:2"},
{Id="61422",Name="Dustivan Blackcowl",Story="A swindling rogue and a self-serving lackey, Dustivan Blackcowl serves King Greymane like an obedient dog. He was recently employed to steal the deed of Ebonmere Farm, hiding deep within the bowels of the city to protect his ill-gotten gains from those seeking to reclaim their family birthright.",Portrait=M.."dungeons\\gc\\dustivan-portrait",Frame=M.."dungeons\\gc\\dustivan-frame",MapCoordinateX=57.6,MapCoordinateY=83.2,L="61330:25,61331:25,61332:25,61333:25,61334:5"},
{Id="61423",Name="Marshal Magnus Greystone",Story="The history of Marshal Magnus Greystone remains largely unwritten, yet what little is known speaks of a life spent in constant war. A veteran of the Second War, he served as Marshal throughout the orcish incursions, standing as a steadfast defender of Gilneas in its darkest hours. Years later, as civil war consumed the kingdom, Greystone commanded the defenses of Gilneas City, holding the line not only against invaders, but against the very people he once fought to protect. Even so, his deeds were never fully recorded, leaving behind only the memory of a soldier who never abandoned his post.",Portrait=M.."dungeons\\gc\\magnus-portrait",Frame=M.."dungeons\\gc\\magnus-frame",MapCoordinateX=46.3,MapCoordinateY=44.7,L="61313:24,61314:24,61315:24,61316:24,61368:5,61317:5,113:5"},
{Id="61605",Name="Horsemaster Levvin",Story="Information on Horsemaster Levvin is currently limited, though he is recognized as a confirmed dweller of the heavily fortified Gilneas City.",Portrait=M.."dungeons\\gc\\levvin-portrait",Frame=M.."dungeons\\gc\\levvin-frame",MapCoordinateX=29,MapCoordinateY=19.2,L="83157:1,61737:25,61736:25,61735:25,61734:25"},
{Id="61263",Name="Harlow Family",Story="Regent-Lady Celia and Regent-Lord Mortimer Harlow are the secret architects of the kingdom's decay. In truth, they are Dragonkin of the Black Dragonflight who have long manipulated the pride of Gilneas to stoke civil war and conflict. Their evil machinations are the root of the draconic influence that must be undone to save the land.",Portrait=M.."dungeons\\gc\\family-portrait",Frame=M.."dungeons\\gc\\family-frame",MapCoordinateX=28.1,MapCoordinateY=23.8,L="61318:24,61319:24,61320:24,61321:24,61322:5"},
{Id="61418",Name="Genn Greymane",Story="The stubborn and proud King of Gilneas was once a legendary force within the Alliance, but he now presides over a crumbling kingdom. Within the Greymane Tower, he guards the Shard of Midnight-a corrupting artifact bestowed upon him by Lord Prestor. Though his grip on the nation has slipped, his power and pride make him a dangerous quarry for any who seek to end his reign.",Portrait=M.."dungeons\\gc\\genn-portrait",Frame=M.."dungeons\\gc\\genn-frame",MapCoordinateX=26.1,MapCoordinateY=20.9,L="61323:14,61324:14,61325:14,61326:14,61327:14,61328:14,61329:14,69000:2,61406:1,61738:6"},
}}
ZLDB.DG["GNOMEREGAN"]={
Name="Gnomeregan",
Story="Located in Dun Morogh, the technological wonder known as Gnomeregan has been the gnomes' capital city for generations. Recently, a hostile race of mutant troggs infested several regions of Dun Morogh - including the great gnome city. In a desperate attempt to destroy the invading troggs, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Several gnomes sought shelter from the airborne pollutants as they waited for the troggs to die or flee. Unfortunately, though the troggs became irradiated from the toxic assault - their siege continued, unabated. Those gnomes who were not killed by noxious seepage were forced to flee, seeking refuge in the nearby dwarven city of Ironforge. There, High Tinker Mekkatorque set out to enlist brave souls to help his people reclaim their beloved city. It is rumored that Mekkatorque's once-trusted advisor, Mekgineer Thermaplugg, betrayed his people by allowing the invasion to happen. Now, his sanity shattered, Thermaplugg remains in Gnomeregan - furthering his dark schemes and acting as the city's new techno-overlord.",
Background=M.."dungeons\\gnomeregan\\background",
GridBackground=M.."dungeons\\gnomeregan\\grid-background",
MapId=9,
IconScale=0.9,
MinLevel=28,
MaxLevel=37,
Entrances={{MapContinentId=2,MapCoordinateX=29.5,MapCoordinateY=74.8,MapZoneId=16},{MapContinentId=2,MapCoordinateX=42.5,MapCoordinateY=12.7,MapZoneId=16}},
Type=T.Dungeon,
Key="GNOMEREGAN",
Bosses={
{Id="7361",Name="Grubbis",Story="The radioactive gas that flooded the city was meant to anger the troggs and kill the gnomes, and Thermaplugg's plan was brutally effective. One trogg, however, reacted oddly to the substance: Grubbis grew. And grew. It was a side effect that Sicco had not anticipated, but he's never been one to waste valuable (and dangerous) resources. This giant trogg now patrols the tunnels of Gnomeregan. His loyal basilisk pet, Chomper, helps Grubbis sniff out gas leaks, tasty fungi, and even tastier intruders.",Portrait=M.."dungeons\\gnomeregan\\grubbis-portrait",Frame=M.."dungeons\\gnomeregan\\grubbis-frame",MapCoordinateX=87,MapCoordinateY=38.2,L="9445:25,80737:25,80738:25,80739:25"},
{Id="7079",Name="Viscous Fallout",Story="The formerly robust and elegantly complex waterways of Gnomeregan are now an irradiated mess filled with toxic slime. A lone water elemental who had dwelt in the gnomes' aquifer became trapped in the contamination, and the pollution corrupted its pure form. It currently wanders the halls of Gnomeregan in anger and agony, a liquid embodiment of the vile poison of Thermaplugg's betrayal.",Portrait=M.."dungeons\\gnomeregan\\fallout-portrait",Frame=M.."dungeons\\gnomeregan\\fallout-frame",MapCoordinateX=65.6,MapCoordinateY=29.9,L="9452:33,9453:33,9454:33"},
{Id="6235",Name="Electrocutioner 6000",Story="Mekgineer Thermaplugg is not a patient gnome. Rather than putting his inventions through a battery of tests to determine their safety and effectiveness, he rushes them into the field and moves on to the next project. The Electrocutioner 6000 was his first attempt at harnessing electricity as a weapon via a super-charged mechano-tank. Lieutenant Tom \"Sizzlepants\" Crankle, the only soldier to survive piloting the Electrocutioner, is now something of a hero among the leper gnomes.",Portrait=M.."dungeons\\gnomeregan\\electrocutioner-portrait",Frame=M.."dungeons\\gnomeregan\\electrocutioner-frame",MapCoordinateX=32.6,MapCoordinateY=41.4,L="9446:33,9447:33,9448:33"},
{Id="6229",Name="Crowd Pummeler 9-60",Story="In Gnomeregan's heyday, inventors would compete for status by pitting their creations against one another. The mekgineer Oglethorpe Obnoticus built an unbeatable robot, and this earned his respect in the high tinker's court. Sicco Thermaplugg stole Obnoticus's blueprints and then made a giant version of the machine. He set his forgery loose, and the horrific results drove the ruling council to banish the innocent Obnoticus. The Crowd Pummeler 9-60 is still one of Thermaplugg's favorite (stolen) inventions.",Portrait=M.."dungeons\\gnomeregan\\pummeler-portrait",Frame=M.."dungeons\\gnomeregan\\pummeler-frame",MapCoordinateX=44.7,MapCoordinateY=88.5,L="9449:33,9450:33,80740:33"},
{Id="6228",Name="Dark Iron Ambassador",Story="Nobody knows why an ambassador of the Dark Iron dwarves was sent to the fallen capital city of Gnomeregan. Some rumors spread that the Dark Irons had a deal with Thermaplugg to direct the troggs to Gnomeregan from their operations in Uldaman where the troggs originated.",Portrait=M.."dungeons\\gnomeregan\\ambassador-portrait",Frame=M.."dungeons\\gnomeregan\\ambassador-frame",MapCoordinateX=19.5,MapCoordinateY=67.3,IsRare=true,L="9455:33,9456:33,9457:33"},
{Id="7800",Name="Mekgineer Thermaplugg",Story="Murderer, traitor, and self-proclaimed king of the gnomes, the mekgineer Sicco Thermaplugg rules over the radioactive halls of Gnomeregan with a malfunctioning iron fist. His subjects are numerous, vicious, and insane enough to defend their crazed king against any intrusion from the upper world. It is Thermaplugg's madness that makes him so dangerous; he possesses the cunning to destroy everything around him, with no thought for his own life. There is a reason that even the monsters of Gnomeregan fear him.",Portrait=M.."dungeons\\gnomeregan\\thermaplugg-portrait",Frame=M.."dungeons\\gnomeregan\\thermaplugg-frame",MapCoordinateX=17.3,MapCoordinateY=38.5,L="9458:25,9459:25,9461:25,9492:25,40084:4,4411:2,4413:2,4415:2,7742:2,51217:1"},
}}
ZLDB.DG["HQ"]={
Name="Hateforge Quarry",
Story="Excavated deep within the Burning Steppes, the Hateforge Quarry was originally the brainchild of Orvak Sternrock, designed to expand the reach of the Dark Iron Miners Union. However, underhanded deceit led to Orvak's removal as High Foreman, replaced by the fraudulent Bargul Blackhammer. Since then, the quarry has become a hive of illicit activity; rumors swirl of a volatile 'Hateforge Brew' being concocted in secret, while acid-born elementals manifest in the potent runoff pools. Most concerning to King Magni Bronzebeard and the Horde alike is the arrival of the Twilight's Hammer, who have moved into the depths to exploit the Dark Iron's labor for their own apocalyptic ends.",
Background=M.."dungeons\\hq\\background",
GridBackground=M.."dungeons\\hq\\grid-background",
MapId=35,
IconScale=0.9,
MinLevel=51,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=97.5,MapCoordinateY=59.1,MapZoneId=8}},
Type=T.Dungeon,
Key="HQ",
Bosses={
{Id="60735",Name="High Foreman Bargul Blackhammer",Story="Bargul Blackhammer spent years utilizing violence and underhanded tactics to usurp the position of High Foreman. After convincing the Senate to back his vision for the Hateforge Quarry, he successfully ousted his predecessor through fraud. Now ensconced in his stolen office, he holds the Senate's Orders tight, ruling the Miners Union with an iron fist and ensuring that the quarry's true, dark purpose remains shielded from those he betrayed.",Portrait=M.."dungeons\\hq\\bargul-portrait",Frame=M.."dungeons\\hq\\bargul-frame",MapCoordinateX=56.5,MapCoordinateY=82.8,L="60565:20,60566:20,60567:20,60568:20,60569:20,60570:15,51217:5,70226:2"},
{Id="60736",Name="Engineer Figgles",Story="With an ego that rivals the masters of Blackrock Spire, Engineer Figgles is an arrogant mastermind who insists on branding every mechanical creation with his own name. He oversees the quarry's complex machinery and the mysterious plans involving dragon whelpings. His technical genius is matched only by his narcissism, making him a primary target for the Blackrock Clan who seek to halt the Dark Iron's technological expansion.",Portrait=M.."dungeons\\hq\\figgles-portrait",Frame=M.."dungeons\\hq\\figgles-frame",MapCoordinateX=57.7,MapCoordinateY=44.6,L="60540:20,60541:20,60542:20,60543:20,60545:20,60539:15,51217:5,70226:2,13325:1"},
{Id="60829",Name="Corrosis",Story="The acid pools within the Hateforge Quarry are so incredibly potent that they eventually gave birth to a malevolent entity of pure dissolution. Manifested from the chemical runoff of the Dark Iron's secret brewing process, Corrosis is a being of shifting, corrosive liquid. Its very essence is sought by master smiths like Frig Thunderforge, who believe the elemental's core holds the key to tempering weapons of unimaginable power.",Portrait=M.."dungeons\\hq\\corrosis-portrait",Frame=M.."dungeons\\hq\\corrosis-frame",MapCoordinateX=72.7,MapCoordinateY=73.3,L="80670:20,80671:20,80674:20,80673:20,80672:20"},
{Id="60734",Name="Hatereaver Annihilator",Story="While confirmed to be a resident of the Hateforge Quarry, little else is known about the Hatereaver Annihilator or the role it plays within the excavation.",Portrait=M.."dungeons\\hq\\hatereaver-portrait",Frame=M.."dungeons\\hq\\hatereaver-frame",MapCoordinateX=75.1,MapCoordinateY=18.4,L="60559:20,60561:20,60562:20,60563:20,60564:20,60560:15,51217:5,70226:2"},
{Id="60737",Name="Har'gesh Doomcaller",Story="Har'gesh Doomcaller is the shadow behind the Dark Iron's toil, overseeing the Twilight's Hammer's operations from the deepest reaches of the quarry. His presence is a direct threat to the safety of the kingdom, prompting both the Alliance and the Horde to demand his removal to prevent the cult's influence from spreading further.",Portrait=M.."dungeons\\hq\\hargesh-portrait",Frame=M.."dungeons\\hq\\hargesh-frame",MapCoordinateX=94.6,MapCoordinateY=79,L="51217:100,51045:25,51046:25,60551:2,70226:3,60550:20,60549:20,60548:20,60547:20,60546:20,51048:25,51047:25"},
}}
ZLDB.DG["KC"]={
Name="Karazhan Crypts",
Story="Beneath the shadow of Karazhan lies a subterranean ossuary that the Kirin Tor has long kept sealed. It is a place where time has stagnated, housing a 'great evil' that both the Alliance and Horde now race to extinguish. From the missing pages of goblin recipe books to the 'foul blackness' of its deepest reaches, the crypts serve as a grim reminder of the tower's corruptive influence on the very earth it stands upon.",
Background=M.."dungeons\\kc\\background",
GridBackground=M.."dungeons\\kc\\grid-background",
MapId=36,
IconScale=0.8,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=39.6,MapCoordinateY=73.1,MapZoneId=9}},
Type=T.Dungeon,
Key="KC",
Bosses={
{Id="91920",Name="Marrowspike",Story="Not much has been chronicled regarding Marrowspike, leaving the creature as a mystery to those exploring the Karazhan Crypts.",Portrait=M.."dungeons\\kc\\marrowspike-portrait",Frame=M.."dungeons\\kc\\marrowspike-frame",MapCoordinateX=89.2,MapCoordinateY=77.8,MapIsBelow=true,L="83441:18,83442:18,83443:18,83444:18,83445:18,83440:10,51217:5,70226:2"},
{Id="91929",Name="Hivaxxis",Story="Beyond its reputation as a lethal dweller of the lightless ossuary, Hivaxxis remains an enigma within the Karazhan Crypts.",Portrait=M.."dungeons\\kc\\hivaxxis-portrait",Frame=M.."dungeons\\kc\\hivaxxis-frame",MapCoordinateX=81.8,MapCoordinateY=86.8,L="83447:18,83448:18,83449:18,83450:18,83451:18,83446:10,51217:5,70226:2"},
{Id="91917",Name="Corpsemuncher",Story="Documentation on the scavenger known as Corpsemuncher is non-existent, marking it only as a verified resident of the Karazhan Crypts.",Portrait=M.."dungeons\\kc\\corpsemuncher-portrait",Frame=M.."dungeons\\kc\\corpsemuncher-frame",MapCoordinateX=21,MapCoordinateY=78.1,L="70057:15,83459:15,83460:15,83461:15,83462:15,83463:15,83458:10,51217:5,70226:2"},
{Id="92935",Name="Guard Captain Gort",Story="Historical texts provide no details on the life or death of Guard Captain Gort, confirming only his station inside the Karazhan Crypts.",Portrait=M.."dungeons\\kc\\gort-portrait",Frame=M.."dungeons\\kc\\gort-frame",MapCoordinateX=55.6,MapCoordinateY=78.4,L="60792:17,60793:17,60794:17,60795:17,60790:17,60791:17,51217:5,70226:2"},
{Id="91916",Name="Archlich Enkhraz",Story="The legacy of Archlich Enkhraz is entirely unknown, establishing him merely as a powerful undead force occupying the Karazhan Crypts.",Portrait=M.."dungeons\\kc\\enkhraz-portrait",Frame=M.."dungeons\\kc\\enkhraz-frame",MapCoordinateX=90,MapCoordinateY=72.1,L="83453:18,83454:18,83455:18,83456:18,83457:18,83452:10,51217:5,80010:5,70226:2"},
{Id="91919",Name="Commander Andreon",Story="Commander Andreon once counted among the tower’s guard alongside his twin brother, Captain Rothynn, he was entrusted with a Mark of Karazhan, a symbol of his station and duty. While Rothynn’s fate is known, his spirit bound to the cellars below, Andreon’s disappearance was never explained. Now he lingers within the crypts as a restless presence, a fallen guardian whose purpose endures even in death.",Portrait=M.."dungeons\\kc\\andreon-portrait",Frame=M.."dungeons\\kc\\andreon-frame",MapCoordinateX=46.5,MapCoordinateY=36.1,L="50188:17,50189:17,50190:17,50191:17,50192:17,50193:17,51217:5,70226:2"},
{Id="91928",Name="Alarus",Story="Known as the Watcher of the Crypts, Alarus is the primary sentinel of the foul magic festering beneath the tower. The Kirin Tor views his destruction as vital to the safety of Azeroth, while the Horde seeks to strike him down as an act of glory, knowing that only by vanquishing this 'great evil' can the suffocating fog and madness of the depths be lifted.",Portrait=M.."dungeons\\kc\\alarus-portrait",Frame=M.."dungeons\\kc\\alarus-frame",MapCoordinateX=85.4,MapCoordinateY=43.9,L="51217:100,83465:25,83466:25,83467:25,83468:25,83469:21,83470:21,83471:21,83472:21,83571:15,70226:3,83464:1"},
}}
ZLDB.DG["LBRS"]={
Name="Lower Blackrock Spire",
Story="This imposing fortress, carved into the fiery core of Blackrock Mountain, represented the might of the Dark Iron clan for centuries. More recently, the black dragon Nefarian and his spawn seized the keep's upper spire and ignited a brutal war against the dwarves. The draconic armies have since allied with Warchief Rend Blackhand and his false Horde. This combined force lords over the spire, conducting horrific experiments to bolster its ranks while plotting the meddlesome Dark Irons' downfall.",
Background=M.."dungeons\\lbrs\\background",
GridBackground=M.."dungeons\\lbrs\\grid-background",
MapId=17,
IconScale=0.9,
MinLevel=55,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=81.7,MapCoordinateY=43.4,MapZoneId=6}},
Type=T.Dungeon,
Key="LBRS",
Bosses={
{Id="9219",Name="Spirestone Butcher",Story="An elusive ogre, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\lbrs\\butcher-portrait",Frame=M.."dungeons\\lbrs\\butcher-frame",IsRare=true,L="12608:50,13286:50"},
{Id="9196",Name="Highlord Omokk",Story="Omokk rules over the spire's ogres with an iron fist. Many underlings have challenged him to single combat in the hopes of seizing the highlord's title, but all have fallen without landing a solitary blow. This mysterious phenomenon has led to rumors that dark magic is protecting Omokk.",Portrait=M.."dungeons\\lbrs\\omokk-portrait",Frame=M.."dungeons\\lbrs\\omokk-frame",L="13166:17,13167:17,13168:17,13169:17,13170:17,16670:17,12336:25,51217:5,70226:2"},
{Id="9218",Name="Spirestone Battle Lord",Story="An elusive ogre, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\lbrs\\battlelord-portrait",Frame=M.."dungeons\\lbrs\\battlelord-frame",IsRare=true,L="13285:60,13284:40"},
{Id="9217",Name="Spirestone Lord Magus",Story="An elusive ogre, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\lbrs\\magus-portrait",Frame=M.."dungeons\\lbrs\\magus-frame",IsRare=true,L="13261:33,13282:33,13283:33"},
{Id="9236",Name="Shadow Hunter Vosh'gajin",Story="Vosh'gajin is renowned for her beauty--and psychotic tendencies--among the trolls. A master of the shadow hunter arts, she wields formidable hexes, curses, and healing magics.",Portrait=M.."dungeons\\lbrs\\voshgajin-portrait",Frame=M.."dungeons\\lbrs\\voshgajin-frame",L="12626:17,12651:17,12653:17,13255:17,13257:17,16712:17,51217:5,70226:2"},
{Id="9237",Name="War Master Voone",Story="During the Second War, Voone led small strike teams on daring missions into the heart of high elven territory. The cunning troll joined the false Horde because he wanted to be its chief strategist, not because he believed in Blackhand's ideology. Voone sees the splinter faction as an underdog, and he enjoys the satisfaction of overcoming insurmountable odds.",Portrait=M.."dungeons\\lbrs\\voone-portrait",Frame=M.."dungeons\\lbrs\\voone-frame",MapCoordinateX=52.4,MapCoordinateY=54.8,L="13173:100,12335:20,12582:20,13177:20,13179:20,16676:20,22231:20,51217:5,70226:2,13175:1"},
{Id="9596",Name="Bannok Grimaxe",Story="An elusive orc, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\lbrs\\bannok-portrait",Frame=M.."dungeons\\lbrs\\bannok-frame",MapCoordinateX=47.9,MapCoordinateY=60,IsRare=true,L="12621:33,12634:33,12637:33,12838:7"},
{Id="10596",Name="Mother Smolderweb",Story="Centuries ago, the Dark Iron dwarves dug into the lair of Mother Smolderweb, releasing the massive arachnid into the spire's halls. Her brood has continued to swell in number since that time, so much so that even Blackhand's forces fear traveling through Smolderweb's domain.",Portrait=M.."dungeons\\lbrs\\mother-portrait",Frame=M.."dungeons\\lbrs\\mother-frame",L="13183:20,70226:2,13244:20,16715:20,51217:5,13213:20,80758:20"},
{Id="10376",Name="Crystal Fang",Story="An elusive spider, rarely seen among the general population of Lower Blackrock Spire. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\lbrs\\fang-portrait",Frame=M.."dungeons\\lbrs\\fang-frame",IsRare=true,L="13184:33,13185:33,13218:33"},
{Id="10584",Name="Urok Doomhowl",Story="Doomhowl is the true leader of the spire's ogres. This sinister figure has charmed his trusted aid, Highlord Omokk, with insidious magic to control Doomhowl's minions in his stead. He has gone to great lengths to keep up this charade, ruthlessly killing any ogres who challenge the highlord's rule.",Portrait=M.."dungeons\\lbrs\\urok-portrait",Frame=M.."dungeons\\lbrs\\urok-frame",L="13178:25,13258:25,13259:25,22232:25,18784:16,51217:5,70226:2"},
{Id="9736",Name="Quartermaster Zigris",Story="After the First War, the orc hunter Zigris became infamous for tracking down Stormwind refugees and slaughtering them like game. He loathes Blackrock Spire's claustrophobic halls, but he is certain a day will come when he'll hunt in the open air again.",Portrait=M.."dungeons\\lbrs\\zigris-portrait",Frame=M.."dungeons\\lbrs\\zigris-frame",L="56101:30,12835:10,13252:10,13253:10,80759:10,51217:5,16673:2,16703:2,16713:2,16716:2,16735:2,70221:2,70226:2"},
{Id="10220",Name="Halycon",Story="Halycon comes from a long line of great worgs bred for their ferocity and loyalty. Over the years, the den mother has produced an astonishing number of savage offspring. Rumors have spread that she is a demonic hound gifted to Rend Blackhand by a pit lord of the Burning Legion.",Portrait=M.."dungeons\\lbrs\\halycon-portrait",Frame=M.."dungeons\\lbrs\\halycon-frame",L="13210:25,13211:25,13212:25,22313:25,51217:5,70226:2"},
{Id="10268",Name="Gizrul the Slavener",Story="Very few of the Dark Horde have seen the reclusive and unpredictable Gizrul. The beast emerges from his shadowy den only when his mate, Halycon, calls to him. The two monstrous creatures have produced some of the largest--and most ferocious--worgs ever bred in orcish history.",Portrait=M.."dungeons\\lbrs\\gizrul-portrait",Frame=M.."dungeons\\lbrs\\gizrul-frame",L="13205:25,13206:25,13208:25,16718:25,83573:15,51217:5,70226:2"},
{Id="9718",Name="Ghok Bashguud",Story="An elusive orc, rarely seen among the general population of Lower Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\lbrs\\ghok-portrait",Frame=M.."dungeons\\lbrs\\ghok-frame",IsRare=true,L="13198:33,13203:33,13204:33"},
{Id="9568",Name="Overlord Wyrmthalak",Story="The black dragonspawn Wyrmthalak oversees the lower spire's forces as they prepare for their assault against the dwarves. He has no love for the false Horde or its brutish members, and he will sacrifice any number of Blackhand's minions to protect his master, Nefarian.",Portrait=M.."dungeons\\lbrs\\wyrmthalak-portrait",Frame=M.."dungeons\\lbrs\\wyrmthalak-frame",L="51217:100,12337:30,13148:13,13161:13,13162:13,13163:13,13164:13,16679:13,22321:13,80760:13,47413:10,47415:10,56097:6,70226:3,13143:2"},
}}
ZLDB.DG["MARA"]={
Name="Maraudon",
Story="According to legend, Zaetar, son of Cenarius, and the earth elemental princess Theradras begot the barbaric centaur race. Shortly after the centaur's creation, the ruthless creatures murdered their father. The grief-stricken Theradras is said to have trapped her lover's spirit within Maraudon, corrupting the region. Now, vicious centaur ghosts and twisted elemental minions roam every corner of the sprawling caves.",
Background=M.."dungeons\\mara\\background",
GridBackground=M.."dungeons\\mara\\grid-background",
MapId=19,
IconScale=0.6,
MinLevel=43,
MaxLevel=54,
Entrances={{MapContinentId=1,MapCoordinateX=72,MapCoordinateY=73.6,MapZoneId=17},{MapContinentId=1,MapCoordinateX=45.3,MapCoordinateY=20.8,MapZoneId=17}},
Type=T.Dungeon,
Key="MARA",
Bosses={
{Id="13282",Name="Noxxion",Story="Noxxion is a living embodiment of corruption. Theradras ordered her ally Lord Vyletongue to create this putrid elemental to be a powerful servant and a loyal pet to ease the princess's loneliness. Noxxion spreads its toxic essence into areas of Maraudon that have not yet withered under Theradras's malign influence.",Portrait=M.."dungeons\\mara\\noxxion-portrait",Frame=M.."dungeons\\mara\\noxxion-frame",MapCoordinateX=32.3,MapCoordinateY=4.7,L="17746:33,17745:33,17744:33"},
{Id="12258",Name="Razorlash",Story="Razorlash was made to accompany Noxxion through Maraudon. In time, this new creation became one of the princess's most cherished servants. Razorlash constantly wanders the caves alongside Noxxion, using thorny tendrils to shred any untainted plant life it can find.",Portrait=M.."dungeons\\mara\\razorlash-portrait",Frame=M.."dungeons\\mara\\razorlash-frame",MapCoordinateX=23.1,MapCoordinateY=15.5,L="17748:25,17749:25,51802:8,17751:25,17750:25,60780:3"},
{Id="12237",Name="Meshlok the Harvester",Story="An elusive bog beast, rarely seen among the denizens of Maraudon. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\mara\\meshlok-portrait",Frame=M.."dungeons\\mara\\meshlok-frame",MapCoordinateX=26.2,MapCoordinateY=30.6,IsRare=true,L="60780:10,17767:33,17742:33,17741:33"},
{Id="12236",Name="Lord Vyletongue",Story="The satyr lord Vyletongue journeyed into Maraudon's depths after hearing of its corruption. Theradras was wary of the conniving demon at first, but Vyletongue proved his worth by creating an array of wretched minions, such as Noxxion and Razorlash, for the princess.",Portrait=M.."dungeons\\mara\\vyletongue-portrait",Frame=M.."dungeons\\mara\\vyletongue-frame",MapCoordinateX=33,MapCoordinateY=32.8,L="17752:33,17754:33,17755:33,51217:1"},
{Id="12225",Name="Celebras the Cursed",Story="Upon learning of his uncle's tragic fate, the noble Celebras swore to free Zaetar's spirit. Yet the keeper of the grove was not prepared for the horrors that awaited him in Maraudon's shadowy corridors. The dark energies permeating the area quickly overcame Celebras, filling his heart with uncontrollable rage.",Portrait=M.."dungeons\\mara\\celebras-portrait",Frame=M.."dungeons\\mara\\celebras-frame",MapCoordinateX=19.1,MapCoordinateY=32.9,L="17738:33,17739:33,17740:33,60780:3,51217:1"},
{Id="13601",Name="Tinkerer Gizlock",Story="Tinkerer Gizlock and five other gem hunters snuck into Maraudon to mine its highly prized crystals. Their plan went horribly wrong when satyrs slaughtered everyone in the party save for Gizlock. The goblin, trapped within the caves and driven to the brink of madness, sees himself as the subterranean region's new ruler.",Portrait=M.."dungeons\\mara\\gizlock-portrait",Frame=M.."dungeons\\mara\\gizlock-frame",MapCoordinateX=37.7,MapCoordinateY=75.1,L="17717:33,17718:33,17719:33,40083:8,51809:8"},
{Id="12203",Name="Landslide",Story="For years, the ancient mountain giant known as Landslide cultivated brilliant crystal gardens in Maraudon, but Theradras enthralled the behemoth when she took up residence there. This once-stoic giant now lives only to serve his tyrannical new master.",Portrait=M.."dungeons\\mara\\landslide-portrait",Frame=M.."dungeons\\mara\\landslide-frame",MapCoordinateX=32.2,MapCoordinateY=60.3,L="17734:25,17736:25,17737:25,17943:25"},
{Id="13596",Name="Rotgrip",Story="Rumor has it that Rotgrip has dwelled in Maraudon's subterranean waters for millennia. The famed dwarven hunter Hemet Nesingwary once proclaimed that the beast could not be found, and a number of amateur trackers accepted the challenge of seeking out the legendary creature. None of them ever returned.",Portrait=M.."dungeons\\mara\\rotgrip-portrait",Frame=M.."dungeons\\mara\\rotgrip-frame",MapCoordinateX=32.1,MapCoordinateY=86.1,L="17728:33,17730:33,17732:33"},
{Id="12201",Name="Princess Theradras",Story="The earth elemental Theradras, Therazane the Stonemother's sole daughter, resides in Maraudon's inner sanctum. Influenced by the Old Gods, the princess transformed her home into a den of corruption and suffering. Some believe that her foul powers are tied to the spirit of her dead lover, Zaetar. If so, liberating the fallen keeper of the grove might be the only hope of cleansing Maraudon.",Portrait=M.."dungeons\\mara\\princess-portrait",Frame=M.."dungeons\\mara\\princess-frame",MapCoordinateX=20.2,MapCoordinateY=83.1,L="17707:14,17710:14,17711:14,17713:14,17714:14,17715:14,17766:14,17780:1,51217:5"},
}}
ZLDB.DG["RFC"]={
Name="Ragefire Chasm",
Story="Ragefire Chasm consists of a network of volcanic caverns that lie below the orcs' new capital city of Orgrimmar. Recently, rumors have spread that a cult loyal to the demonic Shadow Council has taken up residence within the Chasm's fiery depths. This cult, known as the Burning Blade, threatens the very sovereignty of Durotar. Many believe that the orc Warchief, Thrall, is aware of the Blade's existence and has chosen not to destroy it in the hopes that its members might lead him straight to the Shadow Council. Either way, the dark powers emanating from Ragefire Chasm could undo all that the orcs have fought to attain.",
Background=M.."dungeons\\rfc\\background",
GridBackground=M.."dungeons\\rfc\\grid-background",
MapId=4,
IconScale=0.8,
MinLevel=13,
MaxLevel=19,
Entrances={{MapContinentId=1,MapCoordinateX=53,MapCoordinateY=48.6,MapZoneId=21}},
Type=T.Dungeon,
Key="RFC",
Bosses={
{Id="11517",Name="Oggleflint",Story="Oggleflint and the other troggs retreated to the upper levels of Ragefire Chasm once the Searing Blade cultists moved in.",Portrait=M.."dungeons\\rfc\\oggleflint-portrait",Frame=M.."dungeons\\rfc\\oggleflint-frame",MapCoordinateX=56.3,MapCoordinateY=38.1,Abilities={{Effect="Oggleflint cleaves all enemies in front of him.",Icon="Ability_Warrior_Cleave",Id="845",Name="Cleave"}},L="80700:35,80701:35,80702:30,17041:30"},
{Id="11520",Name="Taragaman the Hungerer",Story="Thought to be the leader of the Searing Blade, Taragaman can be found hiding in the fiery depths of Ragefire Chasm and using his demonic influence to corrupt the citizens of Orgrimmar.",Portrait=M.."dungeons\\rfc\\taragaman-portrait",Frame=M.."dungeons\\rfc\\taragaman-frame",MapCoordinateX=40.9,MapCoordinateY=57.9,Abilities={{Effect="Taragaman the Hungerer inflicts fire damage to nearby enemies.",Icon="Spell_Fire_SealOfFire",Id="11970",Name="Fire Nova"},{Effect="Taragaman the Hungerer punches an enemy, knocking them back.",Icon="INV_Gauntlets_05",Id="18072",Name="Uppercut"}},L="14145:33,14148:33,14149:33,64:25"},
{Id="11518",Name="Jergosh the Invoker",Story="Jergosh the Invoker has rejected the ideals of the orcs and practices the dark and demonic arts of the warlock. A leader of the Searing Blade cultists, Jergosh dwells within Ragefire Chasm, concocting a scheme dangerous enough to draw the attention of Thrall himself.",Portrait=M.."dungeons\\rfc\\jergosh-portrait",Frame=M.."dungeons\\rfc\\jergosh-frame",MapCoordinateX=34.1,MapCoordinateY=81.5,Abilities={{Effect="Jergosh the Invoker burns an enemy, inflicting fire damage over time.",Icon="Spell_Fire_Immolation",Id="348",Name="Immolate"},{Effect="Jergosh the Invoker curses an enemy, reducing their physical damage dealt for 30 seconds.",Flags={F.Curse},Icon="Spell_Shadow_CurseOfMannoroth",Id="702",Name="Curse of Weakness"}},L="14147:33,14150:33,14151:33,80111:25,55004:25"},
{Id="11519",Name="Bazzalan",Story="Bazzalan leads the Searing Blade cultists along with Jergosh the Invoker. His motives are unclear, but like all satyr, he is a swift and cunning foe.",Portrait=M.."dungeons\\rfc\\bazzalan-portrait",Frame=M.."dungeons\\rfc\\bazzalan-frame",MapCoordinateX=41.6,MapCoordinateY=87.2,Abilities={{Effect="Bazzalan poisons an enemy, dealing nature damage over time.",Flags={F.Poison},Icon="Spell_Nature_CorrosiveBreath",Id="744",Name="Poison"},{Effect="Bazzalan strikes an enemy, dealing physical damage.",Icon="Spell_Shadow_RitualOfSacrifice",Id="14873",Name="Sinister Strike"}},L="80703:30,80704:30,80705:30,5235:100"},
}}
ZLDB.DG["RFD"]={
Name="Razorfen Downs",
Story="Legends state that where the demigod Agamaggan fell, his blood gave rise to great masses of thorny vines. Many quilboar have taken up residence in the largest cluster of giant thorns, the Razorfen, which they revere as Agamaggan's resting place. Recently, scouts have reported seeing undead milling about the region, engendering fears that the dreaded Scourge may be moving to conquer Kalimdor.",
Background=M.."dungeons\\rfd\\background",
GridBackground=M.."dungeons\\rfd\\grid-background",
MapId=22,
IconScale=0.9,
MinLevel=35,
MaxLevel=44,
Entrances={{MapContinentId=1,MapCoordinateX=49.6,MapCoordinateY=94.5,MapZoneId=27}},
Type=T.Dungeon,
Key="RFD",
Bosses={
{Id="7356",Name="Plaguemaw the Rotting",Story="A rotting abomination sent to kill any adventurers that dares enter Razorfen Downs.",Portrait=M.."dungeons\\rfd\\plaguemaw-portrait",Frame=M.."dungeons\\rfd\\plaguemaw-frame",MapCoordinateX=36.3,MapCoordinateY=17.8,L="10760:33,10766:33,80744:33,51217:1"},
{Id="7355",Name="Tuten'kash",Story="Though blinded during the War of the Spider before his conversion to undeath, Tuten'kash still serves the Scourge as one of its deadliest crypt fiend commanders. Tutaen'kash compensates for his blindness by decorating his lair with fine, almost invisible webs that allow him to sense every footstep and the lightest touch, alerting him to send out minions to ambush his hapless prey. Strong vibrations can send him into a disoriented rage, drawing him from his hiding spot deep within Razorfen Downs' recesses.",Portrait=M.."dungeons\\rfd\\tutenkash-portrait",Frame=M.."dungeons\\rfd\\tutenkash-frame",MapCoordinateX=46.1,MapCoordinateY=26.9,L="51217:1,10777:33,10776:33,10775:33"},
{Id="7357",Name="Mordresh Fire Eye",Story="Through necromantic magic Death Speaker Blackthorn was able to rekindle the flames of Mordresh Fire Eye's soul, returning him to undeath. As a former shaman, Mordresh has exerted his twisted control over the elements. He burns and scorches all those who threaten the Death Speaker's work.",Portrait=M.."dungeons\\rfd\\mordresh-portrait",Frame=M.."dungeons\\rfd\\mordresh-frame",MapCoordinateX=66.4,MapCoordinateY=37.1,L="10769:33,10770:33,10771:33,51217:1"},
{Id="8567",Name="Glutton",Story="Living up to his name, this massive abomination has spent much of his time in Razorfen Downs gorging himself on the spoiled corpses of boars and their quilboar masters. The mass of rancid meat within his gut emanates a cloud of noxious fumes and crippling diseases, choking unfortunate adventurers who stray too close.",Portrait=M.."dungeons\\rfd\\glutton-portrait",Frame=M.."dungeons\\rfd\\glutton-frame",MapCoordinateX=27.6,MapCoordinateY=55.6,L="80745:33,10774:33,10772:33,51217:1"},
{Id="62679",Name="Death Prophet Rakameg",Story="As Amnennar the Coldbringer's influence expands, he has appointed Death Prophet Rakameg to oversee the collection of dark obsidian required for the Lich's most nefarious sorceries. Rakameg acts as a conduit for the malevolent essence surging through the Downs, preaching a gospel of undeath to the displaced quilboar. He is fiercely protective of the obsidian artifacts within the bastion of darkness, viewing them as the key to ensuring his master's immortal essence remains unassailable by those who seek to mend the world's fractures.",Portrait=M.."dungeons\\rfd\\rakameg-portrait",Frame=M.."dungeons\\rfd\\rakameg-frame",MapCoordinateX=44.6,MapCoordinateY=81.1,L="58172:25,58173:25,58174:25,58175:25"},
{Id="7354",Name="Ragglesnout",Story="An elusive quillboar, rarely seen among the denizens of Razorfen Downs. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\rfd\\ragglesnout-portrait",Frame=M.."dungeons\\rfd\\ragglesnout-frame",MapCoordinateX=27.9,MapCoordinateY=47.3,IsRare=true,L="10758:33,10767:33,10768:33"},
{Id="7358",Name="Amnennar the Coldbringer",Story="The lich Amnennar began plans to create a base from which to strike at Orgrimmar and Theramore. To that end, Amnennar has set his sights on recruiting the recently displaced and desperate quilboar people, promising them power over death so they can repel invaders in their lands.",Portrait=M.."dungeons\\rfd\\amnennar-portrait",Frame=M.."dungeons\\rfd\\amnennar-frame",MapCoordinateX=34.1,MapCoordinateY=49.1,L="10761:20,10762:20,10763:20,10764:20,10765:20,51217:5"},
}}
ZLDB.DG["RFK"]={
Name="Razorfen Kraul",
Story="Legends state that where the demigod Agamaggan fell, his blood gave rise to great masses of thorny vines. Many quilboar have taken up residence in the largest cluster of giant thorns, the Razorfen, which they revere as Agamaggan's resting place.",
Background=M.."dungeons\\rfk\\background",
GridBackground=M.."dungeons\\rfk\\grid-background",
MapId=23,
IconScale=0.9,
MinLevel=29,
MaxLevel=36,
Entrances={{MapContinentId=1,MapCoordinateX=40.8,MapCoordinateY=89.4,MapZoneId=27}},
Type=T.Dungeon,
Key="RFK",
Bosses={
{Id="4428",Name="Death Speaker Jargba",Story="The Death Speakers of the Death's Head tribe serve two functions: to disseminate propaganda and to discipline those who refuse to obey Charlga Razorflank and, by extension, her mysterious new allies. Jargba has made a name for himself among the Death Speakers by dominating the very minds of dissidents, forcing them to accept the will of their leaders.",Portrait=M.."dungeons\\rfk\\jargba-portrait",Frame=M.."dungeons\\rfk\\jargba-frame",MapCoordinateX=87.7,MapCoordinateY=41.9,L="2816:33,6682:33,6685:33"},
{Id="4424",Name="Aggem Thorncurse",Story="The commander of the Razorfen military forces, Warlord Ramtusk is a massive aging Quilboar whose thick hide bears the scars of many battles with centaur, harpies, orcs, and even tauren. In his later years, Ramtusk has embraced the company of Quilboar spirit leaders; Aggem Thorncurse and Death Speaker Jargba guide his thoughts from the spirit realm.",Portrait=M.."dungeons\\rfk\\aggem-portrait",Frame=M.."dungeons\\rfk\\aggem-frame",MapCoordinateX=80.7,MapCoordinateY=52,L="80732:35,80733:35"},
{Id="4420",Name="Overlord Ramtusk",Story="The commander of the Death's Head military forces, Overlord Ramtusk is a massive aging quilboar whose thick hide bears the scars of many battles with centaur, harpies, orcs, and even tauren. Rather than being slowed by his advanced years, Ramtusk directs his troops with the swift and confident authority of a battle-forged veteran. Striking him down would surely deal a crippling blow to the Death's Head.",Portrait=M.."dungeons\\rfk\\ramtusk-portrait",Frame=M.."dungeons\\rfk\\ramtusk-frame",MapCoordinateX=56.8,MapCoordinateY=30.1,L="6686:33,6687:33,80734:33"},
{Id="4842",Name="Earthcaller Halmgar",Story="An elusive quillboar, rarely seen among the denizens of Razorfen Kraul. She is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter her in the first place...",Portrait=M.."dungeons\\rfk\\halmgar-portrait",Frame=M.."dungeons\\rfk\\halmgar-frame",MapCoordinateX=48.5,MapCoordinateY=45.1,IsRare=true,L="6688:50,6689:50"},
{Id="62503",Name="Rotthorn",Story="Rotthorn is the living embodiment of the gnarled natural magic that has twisted the order of Razorfen Kraul into a mess of bramble and thorn. Originally thought to be a product of primitive quilboar magic, this Bramblehide elemental was actually driven to madness by a much darker, sinister presence lurking within the lair. It now manifests in a state of perpetual anger, its very heart-the Tainted Brambleheart-pulsating with a foreign energy that even the most experienced druids find inscrutable and deeply unsettling.",Portrait=M.."dungeons\\rfk\\rotthorn-portrait",Frame=M.."dungeons\\rfk\\rotthorn-frame",MapCoordinateX=31,MapCoordinateY=75.7,L="50800:25,58089:25,58090:25,58091:25"},
{Id="4422",Name="Agathelos the Raging",Story="Boars are revered within quilboar culture, and particularly large and tenacious ones are seen as a favor from Agamaggan. Already a powerful creature, Agathelos has been fed Kraul bat guano, which produces a maddening effect, resulting in increased stamina and strength. The Death's Head plan to utilize Agathelos as a powerful weapon to crush all who oppose them.",Portrait=M.."dungeons\\rfk\\agathelos-portrait",Frame=M.."dungeons\\rfk\\agathelos-frame",MapCoordinateX=8.2,MapCoordinateY=68.4,L="6690:25,6691:25,80735:25,80736:25,69170:1"},
{Id="4425",Name="Blind Hunter",Story="An elusive bat, rarely seen among the denizens of Razorfen Kraul. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\rfk\\hunter-portrait",Frame=M.."dungeons\\rfk\\hunter-frame",MapCoordinateX=12.3,MapCoordinateY=32.5,IsRare=true,L="6695:33,6696:33,6697:33"},
{Id="4421",Name="Charlga Razorflank",Story="The leader (or \"crone\") of the Razorfen tribes is Charlga Razorflank, a quilboar whose experimental and powerful Geomancy practices are second to none. Her meteoric rise to power and the rapidly increasing violence between quilboar tribesmen can only lead to one thing: war.",Portrait=M.."dungeons\\rfk\\charlga-portrait",Frame=M.."dungeons\\rfk\\charlga-frame",MapCoordinateX=21.8,MapCoordinateY=30.9,L="6692:33,6693:33,6694:33,51217:1"},
}}
ZLDB.DG["SCHOLO"]={
Name="Scholomance",
Story="Individuals seeking to master the powers of undeath know well of Scholomance, the infamous school of necromancy located in the dark and foreboding crypts beneath Caer Darrow. In recent years, several of the instructors have changed, but the institution remains under the control of Darkmaster Gandling, a particularly sadistic and insidious practitioner of necromantic magic.",
Background=M.."dungeons\\scholo\\background",
GridBackground=M.."dungeons\\scholo\\grid-background",
MapId=25,
IconScale=0.9,
MinLevel=58,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=69,MapCoordinateY=74.9,MapZoneId=37}},
Type=T.Dungeon,
Key="SCHOLO",
Bosses={
{Id="10506",Name="Kirtonos the Herald",Story="Long ago, he became the master of Scholomance's Doctor Theolen Krastinov. Responsible for many of the atrocities during Krastinov's rule over Scholomance, Kirtonos fed on the blood of his innocent victims. To appease his master, Doctor Krastinov had to provide the gargoyle with more and more blood.",Portrait=M.."dungeons\\scholo\\kirtonos-portrait",Frame=M.."dungeons\\scholo\\kirtonos-frame",L="13955:11,13956:11,13957:11,13960:11,13967:11,13969:11,13983:11,14024:11,16734:11,51217:5"},
{Id="10503",Name="Jandice Barov",Story="Jandice Barov was once an archmage of Dalaran and a powerful illusionist. In life, she developed a spell that \"displayed several images of her body that were nearly indistinguishable from her real form. These images duplicated her actions from different locations, making it nearly impossible for her enemies to find her. It was almost infallible.\" After House Barov pledged their allegiance to the Cult of the Damned, Jandice was turned into an undead ghost within Scholomance.",Portrait=M.."dungeons\\scholo\\jandice-portrait",Frame=M.."dungeons\\scholo\\jandice-frame",L="14541:14,14545:14,14548:14,16701:14,18689:14,18690:14,22394:14,51217:5,70226:2"},
{Id="11622",Name="Rattlegore",Story="Rattlegore is made from the remains of his defeated enemies. He guard Scholomance against intruders to this day.",Portrait=M.."dungeons\\scholo\\rattlegore-portrait",Frame=M.."dungeons\\scholo\\rattlegore-frame",L="18782:40,14528:14,14531:14,14537:14,14538:14,14539:14,16711:14,18686:14,51217:5,70226:2"},
{Id="14516",Name="Death Knight Darkreaver",Story="Once a celebrated paladin, the man who would come to be known as Darkreaver was seduced by the call of the Lich King, and became an insidious death knight. His corruption spread to his steed, who was transformed into an undead horse. Darkreaver was sent to the Scholomance. In the dungeon below the Great Ossuary, he attempted to bend the spirit realm to his whim, summoning and corrupting spirits to do his bidding.",Portrait=M.."dungeons\\scholo\\darkreaver-portrait",Frame=M.."dungeons\\scholo\\darkreaver-frame",L="18758:25,18759:25,18760:25,18761:25"},
{Id="10433",Name="Marduk Blackpool",Story="Marduk Blackpool, also known as Marduk the Black, is an infamous death knight of the Scourge. He is a tutor at Scholomance, sharing his dark secrets to the students of necromancy.",Portrait=M.."dungeons\\scholo\\marduk-portrait",Frame=M.."dungeons\\scholo\\marduk-frame",L="14576:7,18692:7,51217:5,70226:2"},
{Id="10432",Name="Vectus",Story="Vectus developed the plagued dragons found inside Scholomance, which he got by paying Tinkee Steamboil in the Burning Steppes to deliver dragon eggs from Blackrock Spire.",Portrait=M.."dungeons\\scholo\\vectus-portrait",Frame=M.."dungeons\\scholo\\vectus-frame",L="14577:7,18691:7,51217:5,70226:2"},
{Id="10508",Name="Ras Frostwhisper",Story="Ras Frostwhisper was once a human mage from Stromgarde. He was a hedge mage, a rogue wizard that never received his formal training from Dalaran. He was among the first to join the Cult of the Damned and quickly advanced through its ranks. He is now an overseer of Scholomance.",Portrait=M.."dungeons\\scholo\\ras-portrait",Frame=M.."dungeons\\scholo\\ras-frame",L="13952:8,14340:8,14487:8,14502:8,14503:8,14522:8,14525:8,16689:8,18693:8,18694:8,18695:8,18696:8,13314:2,13521:3,51217:5,70226:2"},
{Id="16118",Name="Kormok",Story="Kormok is an ogre necromancer boss found in Scholomance. One of his heads was always cheerful if not a little foolish, while the other was sly, calculating and had an almost dead look to its eyes. While initially a mere mage and not being that bad as a member of the Veiled Blade, he became exposed to the necromantic side of magic and ended up delighting in summoning forth the souls of the banished dead of Purgation Isle. After quitting his mercenary company he enrolled at the Scholomance.",Portrait=M.."dungeons\\scholo\\kormok-portrait",Frame=M.."dungeons\\scholo\\kormok-frame",L="22303:20,22326:20,22331:20,22332:20,22333:20"},
{Id="10505",Name="Instructor Malicia",Story="A former high elf of Quel'Thalas, Malicia was one of the few of her kind to willingly join the Cult of the Damned before the fall of Silvermoon. Now an unliving tutor of the dark arts, she oversees the physical and tactical training of the school's acolytes. Malicia is notorious for her cruelty, often using her students as living targets for her devastating shadow magic to ensure that only the most ruthless and resilient survive to serve the Lich King.",Portrait=M.."dungeons\\scholo\\malicia-portrait",Frame=M.."dungeons\\scholo\\malicia-frame",L="12753:17,51217:5,14611:4,14612:4,14614:4,70226:2,16710:4,23201:4,23200:4,18683:4,18684:4,18682:4,18681:4,18680:4,14641:4,14640:4,14638:4,14637:4,14636:4,14633:4,14632:4,14631:4,14629:4,14626:4,14624:4,14623:4,14622:4,14621:4,14620:4,14616:4,14615:4"},
{Id="11261",Name="Doctor Theolen Krastinov",Story="Known as \"The Butcher\", Krastinov is the servant of Kirtonos the Herald and the main torturer and provider of bodies and bodily parts for the Scholomance's necromancy experiments. His first victims were recruited from among the household of Caer Darrow. Among them were servants of the Barov family, Eva and Lucien Sarkhoff. Trapped, tortured and maimed for months, they vowed vengeance on Krastinov even beyond the grave.",Portrait=M.."dungeons\\scholo\\krastinov-portrait",Frame=M.."dungeons\\scholo\\krastinov-frame",L="16684:14,51217:5,14612:4,14614:4,14611:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14626:4,14624:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,70226:2,14617:2,23201:4,23200:4,18684:4,18683:4,18681:4,18682:4,18680:4,14641:4"},
{Id="10901",Name="Lorekeeper Polkelt",Story="Lorekeeper Polkelt was once the keeper of knowledge, knowledge that has sadly been lost, however, as he is now a shambling, unintelligent monster.",Portrait=M.."dungeons\\scholo\\polkelt-portrait",Frame=M.."dungeons\\scholo\\polkelt-frame",L="12753:17,16705:17,51217:5,14611:4,14612:4,14614:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,14641:4,70226:2,23201:4,23200:4,18684:4,18683:4,18682:4,18681:4,18680:4"},
{Id="10507",Name="The Ravenian",Story="The Ravenian is a monstrous abomination of unparalleled hunger, serving as the school's ultimate 'disciplinary' measure. Stitched together from the strongest remains available to the cult, he resides in the lower pits of the academy where he is fed the failures and the weak. Unlike the more intelligent faculty, the Ravenian is a creature of pure, gluttonous instinct, acting as a massive wall of rotting flesh between intruders and the school's most guarded secrets.",Portrait=M.."dungeons\\scholo\\ravenian-portrait",Frame=M.."dungeons\\scholo\\ravenian-frame",L="12753:17,51217:5,14611:4,14612:4,14614:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,14641:4,18680:4,18681:4,18682:4,18683:4,23200:4,18684:4,23201:4,16716:4,70226:2"},
{Id="10504",Name="Lord Alexei Barov",Story="Lord Alexei Barov was the lord of Caer Darrow, Brill, Tarren Mill and Southshore. He was the father of Alexi, Weldon, and Jandice Barov and husband of Lady Illucia Barov. Like Jandice and Illucia, he is now an agent of the Scourge found in Scholomance.",Portrait=M.."dungeons\\scholo\\alexei-portrait",Frame=M.."dungeons\\scholo\\alexei-frame",L="16722:5,51217:5,14611:4,14612:4,14615:4,14614:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14638:4,14640:4,14637:4,14641:4,18680:4,18681:4,18682:4,18683:4,18684:4,23200:4,23201:4,70226:2"},
{Id="10502",Name="Lady Illucia Barov",Story="As the wife of Lord Alexei Barov, Illucia shared in the family's dark pact with Kel'Thuzad, trading the ancestral lands of Caer Darrow for the hollow promise of eternal life. Now a spectral shadow of her former noble self, she haunts the academy's study halls. Illucia retains the aristocratic arrogance she held in life, using her mastery of mind control and psychic agony to break the wills of those who dare trespass in her family's desecrated home.",Portrait=M.."dungeons\\scholo\\illucia-portrait",Frame=M.."dungeons\\scholo\\illucia-frame",L="12753:19,51217:5,14611:4,14612:4,14614:4,14615:4,14616:4,14620:4,14621:4,14622:4,14623:4,14624:4,14626:4,14629:4,14631:4,14632:4,14633:4,14636:4,14637:4,14638:4,14640:4,14641:4,18680:4,18681:4,18682:4,18683:4,18684:4,23200:4,23201:4,70226:2"},
{Id="1853",Name="Darkmaster Gandling",Story="Darkmaster Gandling is the headmaster of the School of Necromancy at Caer Darrow, appointed personally by Kel'Thuzad.",Portrait=M.."dungeons\\scholo\\gandling-portrait",Frame=M.."dungeons\\scholo\\gandling-frame",L="56107:30,51217:100,13398:14,13938:14,13944:14,13951:14,13953:14,13964:14,22433:14,16667:11,16677:11,16686:11,16693:11,16698:11,16707:11,16720:11,16727:11,16731:11,13501:10,47413:10,47415:10,14514:7,70226:3,13937:1"},
}}
ZLDB.DG["SFK"]={
Name="Shadowfang Keep",
Story="During the Third War, the wizards of the Kirin Tor battled against the undead armies of the Scourge. When the wizards of Dalaran died in battle, they would rise soon after - adding their former might to the growing Scourge. Frustrated by their lack of progress (and against the advice of his peers) the Archmage, Arugal elected to summon extra-dimensional entities to bolster Dalaran's diminishing ranks. Arugal's summoning brought the ravenous worgen into the world of Azeroth. The feral wolf-men slaughtered not only the Scourge, but quickly turned on the wizards themselves. The worgen sieged the keep of the noble, Baron Silverlaine. Situated above the tiny hamlet of Pyrewood, the keep quickly fell into shadow and ruin. Driven mad with guilt, Arugal adopted the worgen as his children and retreated to the newly dubbed 'Shadowfang Keep'. It's said he still resides there, protected by his massive pet, Fenrus - and haunted by the vengeful ghost of Baron Silverlaine.",
Background=M.."dungeons\\sfk\\background",
GridBackground=M.."dungeons\\sfk\\grid-background",
MapId=26,
IconScale=1,
MinLevel=20,
MaxLevel=28,
Entrances={{MapContinentId=2,MapCoordinateX=42.8,MapCoordinateY=67.5,MapZoneId=27}},
Type=T.Dungeon,
Key="SFK",
Bosses={
{Id="3914",Name="Rethilgore",Story="Rethilgore is one of the most vicious worgen, entrusted by Archmage Arugal to guard the prisoners who have been caught breaking into Shadowfang Keep. These include Deathstalker Adamant, Sorcerer Ashcrombe and Landen Stilwell.",Portrait=M.."dungeons\\sfk\\rethilgore-portrait",Frame=M.."dungeons\\sfk\\rethilgore-frame",MapCoordinateX=82.7,MapCoordinateY=77,MapIsBelow=true,L="80713:35,80714:35"},
{Id="3886",Name="Razorclaw the Butcher",Story="Razorclaw inhabits the former kitchen of Shadowfang Keep. He slaughtered many innocent humans in Shadowfang Keep when brought in by his master Arugal, hence his nickname.",Portrait=M.."dungeons\\sfk\\razorclaw-portrait",Frame=M.."dungeons\\sfk\\razorclaw-frame",MapCoordinateX=45.7,MapCoordinateY=58,L="1292:33,6226:33,6633:33"},
{Id="3887",Name="Baron Silverlaine",Story="Silverlaine was the former lord of Shadowfang Keep, but was killed when Archmage Arugal and his worgen took over the keep for their own sinister plans. He now haunts the dining room with some of his servants.",Portrait=M.."dungeons\\sfk\\silverlaine-portrait",Frame=M.."dungeons\\sfk\\silverlaine-frame",MapCoordinateX=37.2,MapCoordinateY=81.6,L="6321:50,6323:50,80715:35"},
{Id="61969",Name="Prelate Ironmane",Story="Once a man of peerless faith, Prelate Ironmane was renowned for sermons so moving they stirred the hearts of even the most devout holy men. While his friend Father Brightcopf managed to regain his free will after the Lich King's influence waned, Ironmane was not so fortunate. Consumed by the darkness of Shadowfang Keep and the blood magic of Arugal, he remains a loyal servant to the madness within the walls. He stands as a tragic monument to fallen grace, wielding the Light he once preached as a weapon of terror against any who seek to end the Keep's curse.",Portrait=M.."dungeons\\sfk\\ironmane-portrait",Frame=M.."dungeons\\sfk\\ironmane-frame",MapCoordinateX=12.1,MapCoordinateY=64.7,L="55382:25,55383:25,55384:25,55385:25"},
{Id="4278",Name="Commander Springvale",Story="A loyal soldier, the ghost of Commander Springvale haunts the council room, using unholy strikes to avenge his lord, Baron Silverlaine.",Portrait=M.."dungeons\\sfk\\springvale-portrait",Frame=M.."dungeons\\sfk\\springvale-frame",MapCoordinateX=47,MapCoordinateY=66.1,L="3191:50,6320:50,80717:35"},
{Id="4279",Name="Odo the Blindwatcher",Story="Odo lives in the dilapidated wooden structure hanging precariously off the side of the keep with two pet bats, a Blood Seeker and a Vile Bat. Although he lost his eyesight long ago (hence his nickname), he has adapted to using his other senses, much like his pets.",Portrait=M.."dungeons\\sfk\\odo-portrait",Frame=M.."dungeons\\sfk\\odo-frame",MapCoordinateX=76.6,MapCoordinateY=70.9,L="6318:50,6319:50"},
{Id="3872",Name="Deathsworn Captain",Story="An elusive human ghost, rarely seen among the general population of Shadowfang Keep. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\sfk\\deathsworn-portrait",Frame=M.."dungeons\\sfk\\deathsworn-frame",MapCoordinateX=78,MapCoordinateY=51,IsRare=true,L="6641:50,6642:50"},
{Id="4274",Name="Fenrus the Devourer",Story="Fenrus is the pet of Arugal, Archmage of Shadowfang Keep. Fenrus prowls the main study of Arugal's chambers. He is unbelievably large, and it is possible the worg was subject to dark magic at the hands of Arugal or the worgen.",Portrait=M.."dungeons\\sfk\\fenrus-portrait",Frame=M.."dungeons\\sfk\\fenrus-frame",MapCoordinateX=68.9,MapCoordinateY=34.3,MapIsBelow=true,L="3230:50,6340:50"},
{Id="3927",Name="Wolf Master Nandos",Story="He is the worgen master of the lesser worgs, and has his own pack which will fight heroes before they engage him. He is the last henchman of Arugal to obstruct the path.",Portrait=M.."dungeons\\sfk\\nandos-portrait",Frame=M.."dungeons\\sfk\\nandos-frame",MapCoordinateX=70.5,MapCoordinateY=28.9,L="80716:25,6314:25,3748:50"},
{Id="4275",Name="Archmage Arugal",Story="Archmage Arugal is a former mage of Dalaran who lived within the ruins of Shadowfang Keep and was later raised from the dead in the service of the Scourge. He is most notorious for having unleashed the worgen once more unto the world by freeing them from the Emerald Dream.",Portrait=M.."dungeons\\sfk\\arugal-portrait",Frame=M.."dungeons\\sfk\\arugal-frame",MapCoordinateX=73.8,MapCoordinateY=6.9,L="6220:33,6324:33,6392:33,51217:1"},
}}
ZLDB.DG["SMARM"]={
Name="Scarlet Monastery (Armory)",
Story="The monastery was once a proud bastion of Lordaeron's priesthood - a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful monastery was converted into a stronghold of the fanatical Scarlet Crusade. The crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed.",
Background=M.."dungeons\\smarm\\background",
GridBackground=M.."dungeons\\smarm\\grid-background",
MapId=24,
ZoneId=1,
IconScale=1,
MinLevel=34,
MaxLevel=42,
Entrances={{MapContinentId=2,MapCoordinateX=84.1,MapCoordinateY=44.2,MapDestinationZoneId=1,MapZoneId=25}},
Type=T.Dungeon,
Key="SMARM",
Bosses={
{Id="61982",Name="Armory Quartermaster Daghelm",Story="Once a promising apprentice to the master blacksmith Basil Frye, Daghelm chose to stay at the Monastery when the Scourge hit, while his mentor fled to the muck of the Undercity. The years of isolation and fanaticism have turned him into a psychotic zealot, obsessed with forging armor within the 'blessings' of the Light. He still carries his mentor's journal on Lightforge ingots, refusing to relinquish the precious notes even as the Crusade he serves crumbles into corruption around him.",Portrait=M.."dungeons\\smarm\\daghelm-portrait",Frame=M.."dungeons\\smarm\\daghelm-frame",MapCoordinateX=57.4,MapCoordinateY=38.5,MapId=1,L="55474:25,55475:25,55476:25,55477:25"},
{Id="3975",Name="Herod",Story="Herod is one of the four Scarlet Crusade leaders in the Scarlet Monastery. A champion of the Scarlet Crusade, he is known for his brutish reputation.",Portrait=M.."dungeons\\smarm\\herod-portrait",Frame=M.."dungeons\\smarm\\herod-frame",MapCoordinateX=78.7,MapCoordinateY=1,MapId="1",L="7717:25,7718:25,7719:25,10330:25,51217:1"},
}}
