Entrances={{MapContinentId=2,MapCoordinateX=68.3,MapCoordinateY=21.1,MapDestinationZoneId=3,MapZoneId=25}},
Type=T.Dungeon,
Key="SMGY",
Bosses={
{Id="3983",Name="Interrogator Vishas",Story="James Vishas is the Scarlet Crusade's lead interrogator at the Scarlet Monastery. He enjoys torturing any captured undead and takes great pride in his work. Vishas is known for his unrelenting sadism, cruel expertise, and high pitched voice.",Portrait=M.."dungeons\\smgy\\vishas-portrait",Frame=M.."dungeons\\smgy\\vishas-frame",MapCoordinateX=72.1,MapCoordinateY=59.8,MapId=3,L="7682:25,7683:25,80741:25,80742:25,51217:1"},
{Id="61972",Name="Duke Dreadmoore",Story="Not much is known about Duke Dreadmoore, a death knight believed to be a harbinger of Naxxramas. Recently captured by the Scarlet Crusade, he lies imprisoned within the monastery’s underground cells beneath the torture chambers, where he is subjected to relentless experimentation. Though bound and studied, Dreadmoore remains far from broken, biding his time and awaiting the moment to unleash the full extent of his dark power upon his captors.",Portrait=M.."dungeons\\smgy\\dreadmoore-portrait",Frame=M.."dungeons\\smgy\\dreadmoore-frame",MapCoordinateX=77.6,MapCoordinateY=38.2,MapId=3,L="55386:25,55388:25,55387:25,55389:25"},
{Id="6489",Name="Ironspine",Story="An elusive undead, rarely seen accross the graveyard of the monastery. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\smgy\\ironspine-portrait",Frame=M.."dungeons\\smgy\\ironspine-frame",MapCoordinateX=48.9,MapCoordinateY=66.2,MapId=3,IsRare=true,L="7688:33,7687:33,7686:33"},
{Id="6490",Name="Azshir the Sleepless",Story="An elusive human ghost, rarely seen accross the graveyard of the monastery. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\smgy\\azshir-portrait",Frame=M.."dungeons\\smgy\\azshir-frame",MapCoordinateX=41.1,MapCoordinateY=46.6,MapId=3,IsRare=true,L="7708:33,7709:33,7731:33"},
{Id="6488",Name="Fallen Champion",Story="An elusive undead, rarely seen accross the graveyard of the monastery. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\smgy\\champion-portrait",Frame=M.."dungeons\\smgy\\champion-frame",MapCoordinateX=26.3,MapCoordinateY=45.7,MapId=3,IsRare=true,L="7689:33,7690:33,7691:33"},
{Id="4543",Name="Bloodmage Thalnos",Story="Thalnos earned repute in the Scarlet Crusade for the brutal torture methods he used to \"purify\" new recruits. Ultimately the sadistic mage contracted the plague of undeath and arose as a fearsome skeletal being. The vengeful Thalnos prowled the monastery's graveyard commanding apparitions and zombified creatures to attack anyone who trespasses on his unholy domain.",Portrait=M.."dungeons\\smgy\\thalnos-portrait",Frame=M.."dungeons\\smgy\\thalnos-frame",MapCoordinateX=24.3,MapCoordinateY=56.2,MapId=3,MapIsBelow=true,L="7685:50,7684:35,80743:15,51217:1"},
}}
