IconScale=1,
MinLevel=32,
MaxLevel=40,
Entrances={{MapContinentId=2,MapCoordinateX=79.2,MapCoordinateY=60.2,MapDestinationZoneId=4,MapZoneId=25}},
Type=T.Dungeon,
Key="SMLIB",
Bosses={
{Id="3974",Name="Houndmaster Loksey",Story="Houndmaster Loksey is one of the four leaders of the Scarlet Monastery, and the captain in charge of training the hounds that the Scarlet Crusade uses to track down their enemies. Loksey commands the loyalty of fearsome dogs that can tear their victims apart limb by limb within minutes.",Portrait=M.."dungeons\\smlib\\loksey-portrait",Frame=M.."dungeons\\smlib\\loksey-frame",MapCoordinateX=29.4,MapCoordinateY=84.4,MapId=4,L="7710:33,3456:33,7756:33,51217:1"},
{Id="61983",Name="Brother Wystan",Story="Brother Wystan serves as a gatekeeper of the Monastery's archives, fanatically protecting the 'heretical' objects the Crusade has seized from the outside world. Among his collection is a Thorium Tuned Servo, a complex piece of engineering he considers an affront to the Light. While many mages like Elias have fled the order after witnessing the elite's descent into madness and necromancy, Wystan remains a stalwart shield, ensuring no 'unnatural' influence leaves the Library's walls.",Portrait=M.."dungeons\\smlib\\wystan-portrait",Frame=M.."dungeons\\smlib\\wystan-frame",MapCoordinateX=71.8,MapCoordinateY=40.8,MapId=4,L="55470:25,55471:25,55472:25,55473:25"},
{Id="6487",Name="Arcanist Doan",Story="Doan acts as the keeper of the Scarlet Monastery's library; a guardian of the arcane that the Scarlet Crusade is rumored to distrust. Yet he is indeed a trusted official of the Crusade, keeping a vital key that granted access to Scarlet operations across the Plaguelands. Arcanist Doan believes that arcane magic is the only way to rid Lordaeron of the Scourge.",Portrait=M.."dungeons\\smlib\\doan-portrait",Frame=M.."dungeons\\smlib\\doan-frame",MapCoordinateX=83.4,MapCoordinateY=74.6,MapId=4,L="7711:25,7712:25,7713:25,7714:25,51217:1"},
}}
ZLDB.DG["ST"]={
Name="The Temple of Atal'Hakkar",
Story="Thousands of years ago, the Gurubashi empire was plunged into a civil war by a powerful sect of priests, the Atal'ai, who sought to summon to Azeroth an avatar of their god of blood, Hakkar the Soulflayer. The Gurubashi people exiled the Atal'ai to the Swamp of Sorrows, where the priests built the Temple of Atal'Hakkar. Ysera, Aspect of the green dragonflight, sank the temple beneath the swamp and assigned wardens to ensure that the summoning rituals never be performed again.",
Background=M.."dungeons\\st\\background",
GridBackground=M.."dungeons\\st\\grid-background",
MapId=6,
IconScale=0.9,
MinLevel=46,
MaxLevel=54,
Entrances={{MapContinentId=2,MapCoordinateX=70.1,MapCoordinateY=54.6,MapZoneId=30}},
Type=T.Dungeon,
Key="ST",
Bosses={
{Id="8580",Name="Atal'alarion",Story="Atal'alarion is the sworn protector of the idol found on the lowest level of the temple.",Portrait=M.."dungeons\\st\\atalalarion-portrait",Frame=M.."dungeons\\st\\atalalarion-frame",MapCoordinateX=50,MapCoordinateY=45.5,MapIsBelow=true,L="10798:33,10799:33,10800:33,51217:5,70226:2"},
{Id="5708",Name="Spawn of Hakkar",Story="One of the many spawns of Hakkar, wandering through the halls of the sunken temple...",Portrait=M.."dungeons\\st\\spawn-portrait",Frame=M.."dungeons\\st\\spawn-frame",MapCoordinateX=50,MapCoordinateY=66.3,MapIsBelow=true,L="10801:47,10802:26"},
{Id="5713",Name="Gasher",Story="One of the six trolls protectors, keeping the dreamer asleep...",Portrait=M.."dungeons\\st\\gasher-portrait",Frame=M.."dungeons\\st\\gasher-frame",MapCoordinateX=55.1,MapCoordinateY=32.6,L="10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2"},
{Id="5717",Name="Mijan",Story="One of the six trolls protectors, keeping the dreamer asleep...",Portrait=M.."dungeons\\st\\mijan-portrait",Frame=M.."dungeons\\st\\mijan-frame",MapCoordinateX=60.4,MapCoordinateY=45.9,L="10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2"},
{Id="5712",Name="Zolo",Story="One of the six trolls protectors, keeping the dreamer asleep...",Portrait=M.."dungeons\\st\\zolo-portrait",Frame=M.."dungeons\\st\\zolo-frame",MapCoordinateX=55.3,MapCoordinateY=59.2,L="10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2"},
{Id="5716",Name="Zul'Lor",Story="One of the six trolls protectors, keeping the dreamer asleep...",Portrait=M.."dungeons\\st\\zullor-portrait",Frame=M.."dungeons\\st\\zullor-frame",MapCoordinateX=45,MapCoordinateY=59.4,L="10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2"},
{Id="5715",Name="Hukku",Story="One of the six trolls protectors, keeping the dreamer asleep...",Portrait=M.."dungeons\\st\\hukku-portrait",Frame=M.."dungeons\\st\\hukku-frame",MapCoordinateX=39.6,MapCoordinateY=45.8,L="10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2"},
{Id="5714",Name="Loro",Story="One of the six trolls protectors, keeping the dreamer asleep...",Portrait=M.."dungeons\\st\\loro-portrait",Frame=M.."dungeons\\st\\loro-frame",MapCoordinateX=45,MapCoordinateY=32.2,L="10783:7,10784:7,10785:7,10786:7,10787:7,10788:7,70226:2"},
{Id="5710",Name="Jammal'an the Prophet",Story="Jammal'an is the current leader of the Atal'ai, the extremist sect of priests who fanatically worship Hakkar. While in deep meditation, Jammal'an received instructions on how to resurrect Hakkar by using the blood of his draconic foes, the green dragonflight. Jammal'an and his undead bodyguard Ogom the Wretched stand ready to oppose any who would prevent Hakkar's return, though the prophet's actions may unleash upon Azeroth an even more terrible force: the Emerald Nightmare.",Portrait=M.."dungeons\\st\\jammalan-portrait",Frame=M.."dungeons\\st\\jammalan-frame",MapCoordinateX=76,MapCoordinateY=45.5,L="10806:33,10807:33,10808:33,51217:5,70226:2,10803:33,10804:33,10805:33"},
{Id="5721",Name="Dreamscythe",Story="One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.",Portrait=M.."dungeons\\st\\dreamscythe-portrait",Frame=M.."dungeons\\st\\dreamscythe-frame",MapCoordinateX=43.2,MapCoordinateY=39.7,L="10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2"},
{Id="5720",Name="Weaver",Story="One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.",Portrait=M.."dungeons\\st\\weaver-portrait",Frame=M.."dungeons\\st\\weaver-frame",MapCoordinateX=56,MapCoordinateY=51.4,L="10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2"},
{Id="5719",Name="Morphaz",Story="One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.",Portrait=M.."dungeons\\st\\morphaz-portrait",Frame=M.."dungeons\\st\\morphaz-frame",MapCoordinateX=49.9,MapCoordinateY=86.8,L="10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2"},
{Id="5722",Name="Hazzas",Story="One of the four drake under the direct command of Eranikus, the Dreamer. They are watching over him and prevent any potential intruder from waking him from his slumber.",Portrait=M.."dungeons\\st\\hazzas-portrait",Frame=M.."dungeons\\st\\hazzas-frame",MapCoordinateX=44,MapCoordinateY=86.8,L="10795:5,10796:5,10797:5,12243:5,12463:5,12464:5,12465:5,12466:5,51217:5,70226:2"},
{Id="5709",Name="Shade of Eranikus",Story="Eranikus, former consort to Ysera the Dreamer, was sent to guard the ruins of Atal'Hakkar and prevent Hakkar's emergence. Once within the temple, he and his retinue were corrupted by its dark forces, and he became a shade, pulled between the realms of the Emerald Dream and the physical plane. Despite his corruption, Eranikus may still call upon his powers as a green dragon to spew corrosive acid at his enemies or trap them in a deep slumber.",Portrait=M.."dungeons\\st\\eranikus-portrait",Frame=M.."dungeons\\st\\eranikus-frame",MapCoordinateX=66.5,MapCoordinateY=87.7,L="10454:100,10828:17,10829:17,10833:17,10835:17,10836:17,10837:17,10847:1,70226:3"},
{Id="8443",Name="Avatar of Hakkar",Story="Hakkar was notorious for demanding sacrifices from his followers. Many millennia ago, he instructed the Atal'ai to bring for this avatar, using blood ritually drained from living victims to feed him. The Atal'ai priests now seek to raise Hakkar's avatar with a modified version of this ritual, one that involves sacrificing green dragons. If the Atal'ai succeed, the re-emergence of Hakkar's avatar could spell doom for Azeroth.",Portrait=M.."dungeons\\st\\avatar-portrait",Frame=M.."dungeons\\st\\avatar-frame",MapCoordinateX=24.2,MapCoordinateY=45.5,L="10838:17,10842:17,10843:17,10844:17,10845:17,10846:17,51217:5,12462:2,70226:2"},
}}
ZLDB.DG["STOCKADES"]={
Name="The Stockade",
Story="The Stockades are a high-security prison complex, hidden beneath the canal district of Stormwind city. Presided over by Warden Thelwater, the Stockades are home to petty crooks, political insurgents, murderers and a score of the most dangerous criminals in the land. Recently, a prisoner-led revolt has resulted in a state of pandemonium within the Stockades - where the guards have been driven out and the convicts roam free. Warden Thelwater has managed to escape the holding area and is currently enlisting brave thrill-seekers to venture into the prison and kill the uprising's mastermind - the cunning felon, Bazil Thredd.",
Background=M.."dungeons\\stockades\\background",
GridBackground=M.."dungeons\\stockades\\grid-background",
MapId=8,
IconScale=1,
MinLevel=23,
MaxLevel=32,
Entrances={{MapContinentId=2,MapCoordinateX=50.8,MapCoordinateY=67.6,MapZoneId=28}},
Type=T.Dungeon,
Key="STOCKADES",
Bosses={
{Id="1696",Name="Targorr the Dread",Story="Targorr the Dread served the Blackrock orcs under Gath'Ilzogg as supreme executioner. His methods were ruthless, even by orcish standards. Men who fought bravely to defend Stormwind were tortured on his whim. Targorr was captured and sent to the Stockade, however due to the corrupt and inefficient legal system he was not executed as his actions so richly deserved. During the uprising in the Stockade, the ruthless orc fell in line with the Defias rioters.",Portrait=M.."dungeons\\stockades\\targorr-portrait",Frame=M.."dungeons\\stockades\\targorr-frame",MapCoordinateX=50,MapCoordinateY=21.2,Abilities={{Effect="Targorr the Dread becomes enraged, increasing his physical damage and attack speed for 2 minutes.",Flags={F.Heal},Icon="Spell_Shadow_UnholyFrenzy",Id="8599",Name="Enrage"},{Effect="Targorr the Dread gains a chance to do two additional attacks.",Icon="Ability_GhoulFrenzy",Id="3417",Name="Thrash"}},L="80721:50,80722:50"},
{Id="1666",Name="Kam Deepfury",Story="Kam Deepfury, according to Alliance intelligence in Dun Modr, has been determined as the organizer of the explosion that destroyed one of the bridges in the Thandol Span, as well as the death of one of Longbraid the Grim's kin. Unlike most other prisoners in the Stockade, he is not a member of the Defias Brotherhood.",Portrait=M.."dungeons\\stockades\\kam-portrait",Frame=M.."dungeons\\stockades\\kam-frame",MapCoordinateX=69,MapCoordinateY=30.2,Abilities={{Effect="Kam Deepfury assumes a defensive stance, reducing incoming damage.",Icon="Ability_Warrior_DefensiveStance",Id="7164",Name="Defensive Stance"},{Effect="Kam Deepfury slams his shield against an enemy, dealing damage and stunning them for 2 seconds.",Icon="Ability_Warrior_ShieldBash",Id="8242",Name="Shield Slam"},{Effect="Kam Deepfury raises his shield, reducing all incoming damage by 60% for 12 seconds.",Icon="Ability_Warrior_ShieldWall",Id="871",Name="Shield Wall"}},L="80723:90,2280:1"},
{Id="1717",Name="Hamhock",Story="Some rumors spread throughout Stormwind that Hamhock was a captured ogre from Duskwood, possibly making him a Splinter Fist Ogre. If this were true, he would fall under the possible command of Zzarc'Vul, leader of the clan at Vul'Gol Ogre Mound. Alternatively, he could be a captured member of the Defias Brotherhood.",Portrait=M.."dungeons\\stockades\\hamhock-portrait",Frame=M.."dungeons\\stockades\\hamhock-frame",MapCoordinateX=78.2,MapCoordinateY=45.8,Abilities={{Effect="Hamhock is taken by bloodlust, increasing him and his allies' attack speed by 30% for 30 seconds.",Flags={F.Heal},Icon="Spell_Nature_BloodLust",Id="6742",Name="Bloodlust"},{Effect="Hamhock casts a lightning bolt at an enemy, jumping to two other targets and dealing 190 to 220 nature damage to each.",Flags={F.Heal,F.Interruptible,F.Important},Icon="Spell_Nature_ChainLightning",Id="421",Name="Chain Lightning"}},L="80724:50,80725:50"},
{Id="1716",Name="Bazil Thredd",Story="Bazil Thredd is the lieutenant and most trusted assistant of Edwin VanCleef. He was caught during the riots leading to the death of Queen Tiffin and imprisoned, later taking lead over the bandits of the Defias Brotherhood in the Stockade.",Portrait=M.."dungeons\\stockades\\bazil-portrait",Frame=M.."dungeons\\stockades\\bazil-frame",MapCoordinateX=85.8,MapCoordinateY=51.6,Abilities={{Effect="Bazil Thredd shouts, empowering him and other allies granting them extra melee attack power for 2 minutes.",Icon="Ability_Warrior_BattleShout",Id="9128",Name="Battle Shout"},{Effect="Bazil Thredd throws a smoke bomb, stunning all nearby enemies for 4 seconds.",Flags={F.Important},Icon="Ability_Hibernation",Id="7964",Name="Smoke Bomb"}},L="80729:35,80730:35,80731:30"},
{Id="1720",Name="Bruegal Ironknuckle",Story="An elusive dwarf, rarely seen among the general incarcerated population of Stormwind's Stockades. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\stockades\\bruegal-portrait",Frame=M.."dungeons\\stockades\\bruegal-frame",MapCoordinateX=31.1,MapCoordinateY=41.9,IsRare=true,L="2941:33,2942:33,3228:33"},
{Id="1663",Name="Dextren Ward",Story="Ward had been caught stealing bodies from Raven Hill Cemetery and selling them to Morbent Fel, a crime that ultimately led to his capture and grim notoriety.",Portrait=M.."dungeons\\stockades\\dextren-portrait",Frame=M.."dungeons\\stockades\\dextren-frame",MapCoordinateX=14.4,MapCoordinateY=20.9,Abilities={{Effect="Dextren Ward shouts at nearby enemies, causing them to flee in fear for 6 seconds.\
\
Make sure to clear the rooms around the encounter or you might accidentally overpull while feared!",Flags={F.Important},Icon="Ability_GolemThunderClap",Id="5246",Name="Frightening Shout"},{Effect="Dextren Ward strikes his target for additional physical damage.",Icon="Ability_Rogue_Ambush",Id="11976",Name="Strike"}},L="80726:35,80727:35,80728:30"},
}}
ZLDB.DG["STRAT"]={
Name="Stratholme",
Story="Once the jewel of northern Lordaeron, the city of Stratholme is where Prince Arthas turned against his mentor, Uther Lightbringer, and slaughtered hundreds of his own subjects who were believed to have contracted the dreaded plague of undeath. Arthas' downward spiral and ultimate surrender to the Lich King soon followed. The broken city is now inhabited by the undead Scourge -- led by the powerful lich, Kel'Thuzad. A contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan, also holds a portion of the ravaged city. The two sides are locked in constant, violent combat. Those adventurers brave (or foolish) enough to enter Stratholme will be forced to contend with both factions before long. It is said that the city is guarded by three massive watchtowers, as well as powerful necromancers, banshees and abominations. There have also been reports of a malefic Death Knight riding atop an unholy steed, dispensing indiscriminate wrath on all those who venture within the realm of the Scourge.",
Background=M.."dungeons\\strat\\background",
GridBackground=M.."dungeons\\strat\\grid-background",
MapId=27,
IconScale=0.7,
MinLevel=58,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=30.8,MapCoordinateY=14.8,MapZoneId=12},{MapContinentId=2,MapCoordinateX=47.7,MapCoordinateY=23.4,MapZoneId=12}},
Type=T.Dungeon,
Key="STRAT",
Bosses={
{Id="10393",Name="Skul",Story="An elusive skeletal mage, rarely seen among the general population of Stratholme. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\strat\\skul-portrait",Frame=M.."dungeons\\strat\\skul-frame",MapCoordinateX=56.4,MapCoordinateY=84.9,IsRare=true,L="13395:33,13394:33,13396:33,70226:2"},
{Id="10558",Name="Hearthsinger Forresten",Story="The Culling of Stratholme claimed the lives of innumerable people whose only crime was being in the doomed city. A traveling singer and piccolo player named Forresten was one such victim. He continues to wander the city in death, unable to accept his tragic fate.",Portrait=M.."dungeons\\strat\\hearthsinger-portrait",Frame=M.."dungeons\\strat\\hearthsinger-frame",MapCoordinateX=72.5,MapCoordinateY=66,IsRare=true,L="13378:20,13379:20,13383:20,13384:20,16682:20,70226:2"},
{Id="10516",Name="The Unforgiven",Story="Lylia was a blade of righteousness among her people. After Arthas commanded his forces to purge the city, her sanity was ripped apart from seeing countless innocents die by her hand. She fell on her sword to escape the madness around her, and she now exists as a spectral being forever denied absolution for her heinous acts.",Portrait=M.."dungeons\\strat\\unforgiven-portrait",Frame=M.."dungeons\\strat\\unforgiven-frame",MapCoordinateX=66.6,MapCoordinateY=57,L="13404:20,13405:20,13408:20,13409:20,16717:20,51217:5,70226:2"},
{Id="10808",Name="Timmy the Cruel",Story="Timmison was infamous for his savagery on the field of battle. Some speculate his sadism stemmed from the ceaseless bullying he endured as a child. Now reborn as a Scourge monstrosity, his mind shattered, he is tormented by those memories, causing him to answer to the name he once loathed: Timmy.",Portrait=M.."dungeons\\strat\\timmy-portrait",Frame=M.."dungeons\\strat\\timmy-frame",MapCoordinateX=46,MapCoordinateY=67.5,L="13400:20,13401:20,13402:20,13403:20,16724:20,51217:5,70226:2"},
{Id="11032",Name="Malor the Zealous",Story="A crazed member of the Scarlet Crusade, he guards his own strongbox and won't let anyone near it.",Portrait=M.."dungeons\\strat\\malor-portrait",Frame=M.."dungeons\\strat\\malor-frame",MapCoordinateX=40.9,MapCoordinateY=69.2,L="81016:11,81017:11,81018:11,81019:11,81122:11,81123:11,81124:11,81125:11,81131:11,83575:10,51217:5,70226:2"},
{Id="11120",Name="Crimson Hammersmith",Story="A hammersmith from the Crimson Legion. Not much is known about him, other than he is very protective of his blacksmithing plans.",Portrait=M.."dungeons\\strat\\hammersmith-portrait",Frame=M.."dungeons\\strat\\hammersmith-frame",MapCoordinateX=29.8,MapCoordinateY=73.5,L="18781:40,124:6"},
{Id="10997",Name="Cannon Master Willey",Story="The chief cannoneer of the Scarlet Crusade, Willey will use his cannons no matter the circumstance.",Portrait=M.."dungeons\\strat\\willey-portrait",Frame=M.."dungeons\\strat\\willey-frame",MapCoordinateX=25.4,MapCoordinateY=75.6,L="13380:10,13381:10,13382:10,16708:10,18721:10,22403:10,22404:10,22405:10,22406:10,22407:10,12839:6,51217:5,70226:2"},
{Id="10811",Name="Archivist Galford",Story="Archivist Galford guards the archives of the Scarlet Bastion in Stratholme.",Portrait=M.."dungeons\\strat\\galford-portrait",Frame=M.."dungeons\\strat\\galford-frame",MapCoordinateX=38.2,MapCoordinateY=89.2,L="13385:20,13386:20,13387:20,16692:20,18716:20,22897:14,70226:2,51217:5"},
{Id="10812",Name="Grand Crusader Dathrohan",Story="The Grand Crusader of the Scarlet Crusade, Saidan Dathrohan give orders from the Scarlet Bastion in Stratholme. Rumors spread about him, putting into question his true intents and even his identity...",Portrait=M.."dungeons\\strat\\dathrohan-portrait",Frame=M.."dungeons\\strat\\dathrohan-frame",MapCoordinateX=35.1,MapCoordinateY=93.4,L="51217:100,83501:17,83502:17,83504:17,83505:17,83503:17,83506:17,12103:10,13348:10,13358:10,13359:10,13360:10,13369:10,16725:10,18717:10,18718:10,18720:10,47413:10,47415:10,14512:6,83500:5,13520:3,70226:3,13353:2"},
{Id="10435",Name="Magistrate Barthilas",Story="Barthilas was among those innocents purged by Arthas and his forces during the Culling of Stratholme. The Lich King eventually raised the former magistrate from the grave and commanded the hulking undead monstrosity to guard his ruined home.",Portrait=M.."dungeons\\strat\\barthilas-portrait",Frame=M.."dungeons\\strat\\barthilas-frame",MapCoordinateX=81.6,MapCoordinateY=62.5,L="12382:100,13376:17,18722:17,18725:17,18726:17,18727:17,23198:17,51217:5,70226:2"},
{Id="10809",Name="Stonespine",Story="An elusive gargoyle, rarely seen among the general population of Stratholme. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\strat\\stonespine-portrait",Frame=M.."dungeons\\strat\\stonespine-frame",MapCoordinateX=83.5,MapCoordinateY=43,IsRare=true,L="13397:33,13399:33,13954:33,70226:2"},
{Id="10437",Name="Nerub'enkan",Story="Nerub'enkan was a fearsome warrior during the War of the Spider. Ultimately, she succumbed to her wounds and was raised into undeath as an obedient minion of the Scourge. Now the nerubian guards a ziggurat in Stratholme as fiercely as she defended her home in life.",Portrait=M.."dungeons\\strat\\nerubenkan-portrait",Frame=M.."dungeons\\strat\\nerubenkan-frame",MapCoordinateX=75.7,MapCoordinateY=38.2,L="51217:5,13530:20,13531:20,13532:20,13533:20,13529:20,16675:20,18738:20,18739:20,18740:20,70226:2"},
{Id="10436",Name="Baroness Anastari",Story="While she lived, Anastari took what she wanted, no matter the cost. Death has done little to change that. Her soul ripped from her body, Anastari became a banshee, and she has abandoned her love of material trinkets in favor of possessions of a far more sinister kind.",Portrait=M.."dungeons\\strat\\anastari-portrait",Frame=M.."dungeons\\strat\\anastari-frame",MapCoordinateX=90.2,MapCoordinateY=39,L="70226:2,13535:20,13537:20,13538:20,13539:20,13534:20,16704:20,18728:20,18729:20,18730:20,51217:5"},
{Id="10438",Name="Maleki the Pallid",Story="Maleki was among the first to join the Cult of the Damned, showing tremendous aptitude in harnessing the chill of the grave. Driven by an insatiable desire for power, the mage fervently hones his skills in dark magic to prepare for when he will be remade as a lich.",Portrait=M.."dungeons\\strat\\maleki-portrait",Frame=M.."dungeons\\strat\\maleki-frame",MapCoordinateX=84.4,MapCoordinateY=17.4,L="13525:20,13526:20,13527:20,13528:20,13524:20,16691:20,18734:20,18735:20,18737:20,12833:6,51217:5,70226:2"},
{Id="10439",Name="Ramstein the Gorger",Story="Ramstein is one of the Scourge's most infamous abominations, a horror stitched together from numerous corpses and empowered by a ceaseless hunger. This monster committed unspeakable atrocities on countless innocent souls when Scourge forces overran Stratholme.",Portrait=M.."dungeons\\strat\\ramstein-portrait",Frame=M.."dungeons\\strat\\ramstein-frame",MapCoordinateX=65.5,MapCoordinateY=16.2,L="13372:14,13373:14,13374:14,13375:14,13515:14,16737:14,18723:14,51217:5,70226:2"},
{Id="10440",Name="Baron Rivendare",Story="Baron Rivendare is a powerful death knight in the service of the Lich King, coordinating the efforts of the Scourge in the Plaguelands. Ruling over the city of Stratholme, he currently battles with agents of the Argent Dawn sent to Stratholme to kill him.",Portrait=M.."dungeons\\strat\\rivendare-portrait",Frame=M.."dungeons\\strat\\rivendare-frame",MapCoordinateX=60.2,MapCoordinateY=16.6,L="51217:100,22408:20,22409:20,22410:20,22411:20,22412:20,13340:14,13344:14,13345:14,13346:14,13349:14,13361:14,13368:14,16668:11,16678:11,16687:11,16694:11,16699:11,16709:11,16719:11,16732:11,16728:11,47413:10,47415:10,70226:3,13505:1,13335:1"},
}}
ZLDB.DG["SV"]={
Name="Stormwind Vault",
Story="The Stormwind Vault was built to hold the kingdom's most dangerous criminals and magical threats. At its heart lies Arc'Tiras, a powerful crystal that has driven the guards mad and corrupted the Runic Constructs meant to patrol its halls. Now, the Vault is a maze of chaos...",
Background=M.."dungeons\\sv\\background",
GridBackground=M.."dungeons\\sv\\grid-background",
MapId=37,
IconScale=1,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=62.8,MapCoordinateY=58.6,MapZoneId=28},{MapContinentId=2,MapCoordinateX=29.4,MapCoordinateY=61.8,MapZoneId=13}},
Type=T.Dungeon,
Key="SV",
Bosses={
{Id="80853",Name="Aszosh Grimflame",Story="Aszosh Grimflame was once a necrolyte of the Shadow Council, raised as a death knight by Gul'dan. Now he commands the bones of the fallen and drains the strength of all who oppose him. His dark presence has twisted the Vault's halls, and only the brave can hope to stop his relentless hunger for power.",Portrait=M.."dungeons\\sv\\aszosh-portrait",Frame=M.."dungeons\\sv\\aszosh-frame",MapCoordinateX=37.7,MapCoordinateY=38.5,Abilities={{Effect="Aszosh Grimflame launches arcane missiles at the enemy, causing 192 arcane damage every 1 second for 5 seconds.",Icon="Spell_Nature_StarFall",Id="10212",Name="Arcane Missiles"},{Effect="Aszosh Grimflame curses his enemy, reducing their strength and stamina by 50 for 60 seconds.",Flags={F.Curse},Icon="Spell_Shadow_AntiShadow",Id="18702",Name="Curse of the Darkmaster"}},L="60504:17,60418:17,60419:17,60425:17,60431:17,60434:17,51217:5,70226:1"},
{Id="80852",Name="Tham'Grarr",Story="Not much is known about Tham'Grarr, other than he is a fearsome ogre, known for his brutal strength and violent temper.",Portrait=M.."dungeons\\sv\\tham-portrait",Frame=M.."dungeons\\sv\\tham-frame",MapCoordinateX=68.6,MapCoordinateY=90.1,Abilities={{Effect="Tham'Grarr shouts at nearby enemies, causing them to flee in fear for 8 seconds.",Flags={F.Important},Icon="Ability_GolemThunderClap",Id="5246",Name="Intimidating Shout"},{Effect="Tham'Grarr inflicts heavy damage on his target and leaves them wounded, reducing the effectiveness of any healing by 50% for 5 seconds.",Flags={F.Heal},Icon="Ability_Warrior_SavageBlow",Id="22859",Name="Mortal Cleave"},{Effect="Tham'Grarr counterattacks any enemy that strikes him in melee for 15 seconds.\
\
Melee attacks made from behind cannot be counterattacked.",Flags={F.DPS,F.Important},Icon="Ability_Warrior_Challange",Id="22857",Name="Retaliation"}},L="60502:17,60415:17,60416:17,60417:17,60424:17,60435:17,51217:5,70226:1"},
{Id="80850",Name="Black Bride",Story="The Black Bride is a tragic figure, bound by obsessive love for Damian. She attacks any who come near, seeing them as defilers of her devotion, and speaks of her love for The Ripper even in death.",Portrait=M.."dungeons\\sv\\bride-portrait",Frame=M.."dungeons\\sv\\bride-frame",MapCoordinateX=55.9,MapCoordinateY=10.8,Abilities={{Effect="The Black Bride curses nearby enemies, reducing their chance to hit by 10% for 12 seconds.",Flags={F.Curse},Icon="Spell_Nature_Drowsy",Id="16867",Name="Banshee Curse"},{Effect="The Black Bride wails with anguish, inflicting shadow damage to an enemy.",Icon="Spell_Shadow_ShadowBolt",Id="16565",Name="Banshee Wail"},{Effect="The Black Bride takes control of one of her enemies, and start attacking their allies!\
\
Dealing enough damage to the possessed player will free them from the bride!",Flags={F.Important},Icon="Spell_Shadow_Charm",Id="17244",Name="Possess"},{Effect="The Black Bride silences all enemies in a 10 yards radius, preventing them from casting spells for 10 seconds.",Flags={F.Magic},Icon="Spell_Holy_Silence",Id="18327",Name="Silence"}},L="60408:20,60409:20,60410:20,60411:20,60436:17,51217:5,70226:1"},
{Id="80851",Name="Volkan Cruelblade",Story="Volkan Cruelblade is a member of the Burning Blade clan. He fights with deadly skill, seeking freedom and vengeance against all who oppose him.",Portrait=M.."dungeons\\sv\\volkan-portrait",Frame=M.."dungeons\\sv\\volkan-frame",MapCoordinateX=71.6,MapCoordinateY=43.1,MapIsBelow=true,Abilities={{Effect="Volkan puts nearby enemies to sleep for 10 seconds.\
\
Any damage caused will awaken them.",Flags={F.Important},Icon="Spell_Nature_Sleep",Id="9256",Name="Deep Sleep"},{Effect="Volkan lets out a psychic scream, causing an enemy to be frozen in fear for 8 seconds.",Flags={F.Important},Icon="Spell_Shadow_PsychicScream",Id="15398",Name="Psychic Scream"},{Effect="Volkan hurls missiles of dark magic, inflicting 255 shadow damage to each enemy within 30 yards.",Flags={F.Heal},Icon="Spell_Shadow_ShadowBolt",Id="20741",Name="Shadow Bolt Volley"},{Effect="Volkan lashes enemies in a 20 yards radius with dark magic, inflicting 740 shadow damage to each of them.",Flags={F.Heal},Icon="Spell_Shadow_ShadowBolt",Id="20603",Name="Shadow Shock"}},L="60412:20,60413:20,60414:20,60432:20,60503:20,51217:5,70226:1"},
{Id="80854",Name="Damian",Story="Damian, also known as The Ripper, is a deadly and elusive killer who strikes from the shadows. He delights in combat, hunting those who cross his path with ruthless precision, and vanishes as easily as he appears.",Portrait=M.."dungeons\\sv\\damian-portrait",Frame=M.."dungeons\\sv\\damian-frame",MapCoordinateX=46.5,MapCoordinateY=43.4,Abilities={{Effect="Damian drains the life from an enemy, transferring 70 health to himself every second for 5 seconds.",Flags={F.Interruptible},Icon="Spell_Shadow_LifeDrain02",Id="11700",Name="Drain Life"},{Effect="Damian immolates an enemy, burning them for 258 fire damage and an additional 485 fire damage over 15 seconds.",Flags={F.Heal,F.Magic},Icon="Spell_Fire_Immolation",Id="11668",Name="Immolate"},{Effect="Damian vanishes, ambushing an enemy when he reappears.",Icon="Ability_Vanish",Id="1856",Name="Vanish"}},L="60421:20,60423:20,60427:20,60433:20,60500:20,60422:1,51217:5,70226:1"},
{Id="93107",Name="Arc'Tiras",Story="Arc'Tiras is a powerful and sentient crystal of magic, locked deep within the Stormwind Vault. Its unstable energy has driven the guards mad and twisted the Vault into a maze of madness.",Portrait=M.."dungeons\\sv\\arc-portrait",Frame=M.."dungeons\\sv\\arc-frame",MapCoordinateX=46.4,MapCoordinateY=79.3,L="40003:25,60501:25,60505:25,60506:25,60420:25,60426:25,60429:25,60430:25,51217:80,83570:15"},
}}
ZLDB.DG["SWR"]={
Name="Stormwrought Ruins",
Story="The island of Balor was once a bustling merchant paradise, governed by the Balor family as a prosperous vessel state of Stormwind. This era of trade and tranquility ended during the Second War when the Stormreaver orcs and the Shadow Council brought depravity to its shores. Today, the once-resplendent castle sits in ruins atop the cliffs, haunted by the spirits of those tethered to their former home by demonic cruelty. While SI:7 and goblin scavengers pick through the rubble for lost antiquities, the Shadow Council conducts vile experiments within the depths, threatening to anchor the isle in eternal darkness.",
Background=M.."dungeons\\swr\\background",
GridBackground=M.."dungeons\\swr\\grid-background",
MapId=42,
IconScale=0.6,
MinLevel=32,
MaxLevel=44,
Entrances={{MapContinentId=2,MapCoordinateX=57.1,MapCoordinateY=60.1,MapZoneId=5},{MapContinentId=2,MapCoordinateX=56.2,MapCoordinateY=84.9,MapZoneId=5}},
Type=T.Dungeon,
Key="SWR",
Bosses={
{Id="62548",Name="Oronok Torn-Heart",Story="As one of Gul'dan's most capable lieutenants, Oronok was entrusted with the Pendant of Uth'okk, a gemstone of immense power. He currently lurks within the depths of the ruins, overseeing the new uprising of the Shadow Council. His presence is a reminder of the Old Horde's hatred, and he remains a primary target for those seeking to reclaim the power of the pendant for the Horde.",Portrait=M.."dungeons\\swr\\oronok-portrait",Frame=M.."dungeons\\swr\\oronok-frame",MapCoordinateX=45.1,MapCoordinateY=25.7,L="58135:25,58136:25,58137:25,58177:25"},
{Id="62547",Name="Dagar the Glutton",Story="Dagar is a despicable being whose history of malice stretches back to the formation of the Shadow Council. A fanatical follower of Gul'dan's legacy, his hatred burns like the lava pools of Blackrock Mountain. He stands as a brutal enforcer within the castle, guarding the occupied halls against any who would disrupt the Council's work.",Portrait=M.."dungeons\\swr\\dagar-portrait",Frame=M.."dungeons\\swr\\dagar-frame",MapCoordinateX=50.5,MapCoordinateY=27,L="58130:25,58132:25,58133:25,58176:25"},
{Id="62552",Name="Librarian Theodorus",Story="The Balor family amassed a sheer unimaginable amount of knowledge in their library over decades of successful trade. Theodorus serves as the current guardian of these dusty tomes, including the hidden practices of trade authored by Sir Walton Balor. He ensures that the secrets of Balorian commerce do not fall into the hands of Stormwind's spies.",Portrait=M.."dungeons\\swr\\theodorus-portrait",Frame=M.."dungeons\\swr\\theodorus-frame",MapCoordinateX=47.4,MapCoordinateY=35.9,L="58138:25,58139:25,58140:25,58141:25"},
{Id="62549",Name="Duke Balor the IV",Story="The scions of the Balor family reigned over their island with watchful eyes and merciful souls until the castle was cursed. Though the Duke's bones may have turned to ash, his presence remains tied to the throne room. He is a tragic figure of a fallen merchant legacy, his sigil ring and crown serving as the last remaining physical proof of his family's former sovereignty.",Portrait=M.."dungeons\\swr\\balor-portrait",Frame=M.."dungeons\\swr\\balor-frame",MapCoordinateX=50.4,MapCoordinateY=39.5,L="58145:25,58144:25,58143:25,58142:25"},
{Id="62551",Name="Chieftain Stormsong",Story="Chieftain Stormsong is a critical figurehead in the Stormreaver chain of command, acting as a 'head of the hydra' for the occupation. He oversees the orcish forces within the ruins, coordinating with the Shadow Council to ensure their resurgence remains unchallenged. Liquidating him is essential to breaking the orcish grip on the castle courtyard.",Portrait=M.."dungeons\\swr\\stormsong-portrait",Frame=M.."dungeons\\swr\\stormsong-frame",MapCoordinateX=39.5,MapCoordinateY=47.9,L="75:6,58149:25,58148:25,58147:25,58146:25"},
{Id="62550",Name="Deathlord Tidebane",Story="Barbaros, captain of the Bilgerats, sailed to the cursed isle of Balor chasing stolen secrets and the promise of buried treasure. His greed proved fatal — ambushed by the Stormreaver orcs, he was dragged to Stormwrought Castle and put to the sword. Yet death was not the end. The dark powers enthroned within those halls seized his corpse and bound the soul of a death knight into his flesh, giving rise to Deathlord Tidebane. The captain who once commanded the seas now serves as a vessel of undying darkness, forever imprisoned within the ruins he sought to plunder.",Portrait=M.."dungeons\\swr\\tidebane-portrait",Frame=M.."dungeons\\swr\\tidebane-frame",MapCoordinateX=32.7,MapCoordinateY=66.9,L="58150:25,58151:25,58152:25,58153:25,24:6,58276:1,70:6,950:1"},
{Id="62652",Name="Subjugator Halthas Shadecrest",Story="Aside from his established presence within the ruins of Stormwrought Castle, very little is known about the past or the specific motives of Subjugator Halthas Shadecrest.",Portrait=M.."dungeons\\swr\\halthas-portrait",Frame=M.."dungeons\\swr\\halthas-frame",MapCoordinateX=32.8,MapCoordinateY=91.9,L="58183:25,58184:25,58185:25,58186:25,83:6"},
{Id="62664",Name="Mycellakos",Story="Mycellakos is a massive, living fungus that originated from a source of contamination deep beneath the ruined castle. Its core radiates a dark, twisted magic that has brought the surrounding fungi into a state of unnatural life. As the primary infector of the isle, it must be purged to stop the spread of its necrotic tissue.",Portrait=M.."dungeons\\swr\\mycellakos-portrait",Frame=M.."dungeons\\swr\\mycellakos-frame",MapCoordinateX=23.9,MapCoordinateY=38.3,L="58179:25,58180:25,58181:25,58182:25"},
{Id="62661",Name="Eldermaw the Primordial",Story="The primordial beast known as Eldermaw remains an enigma to scholars, with no documentation existing to explain its habitation within the Stormwrought Ruins.",Portrait=M.."dungeons\\swr\\eldermaw-portrait",Frame=M.."dungeons\\swr\\eldermaw-frame",MapCoordinateX=22.5,MapCoordinateY=25.7,L="58190:25,58189:25,58188:25,58187:25"},
{Id="62665",Name="Lady Drazare",Story="Historical accounts are silent regarding Lady Drazare; she is recognized solely as one of the powerful entities dwelling within the ruins of Balor.",Portrait=M.."dungeons\\swr\\drazare-portrait",Frame=M.."dungeons\\swr\\drazare-frame",MapCoordinateX=30.7,MapCoordinateY=19.3,L="58194:25,58193:25,58192:25,58191:25"},
{Id="62670",Name="Remains of the Innocent",Story="This haunting abomination was born from the cruel intent of the Shadow Council, manifesting as a mass of tormented young souls. O'jin and other sensitive spirits can hear the cries of these poor children, who were used as raw materials for the Council's vile experiments. Only by slaying this abomination can the innocent souls finally be set free.",Portrait=M.."dungeons\\swr\\remains-portrait",Frame=M.."dungeons\\swr\\remains-frame",MapCoordinateX=26.4,MapCoordinateY=10.2,L="58195:25,58196:25,58197:25,58198:25"},
{Id="62673",Name="Ighal'for",Story="A high-ranking and powerful warlock of the Shadow Council, Ighal'for is a disciple of the deranged Cho'gall. He wields a broken Bloodstone Pendant to channel void energies and summon aberrations from beyond the Nether. His fanatical devotion to his demon overlords makes him the primary architect of the horrors currently unfolding within the castle.",Portrait=M.."dungeons\\swr\\mergothid-portrait",Frame=M.."dungeons\\swr\\mergothid-frame",MapCoordinateX=30.7,MapCoordinateY=5.9,L="58199:1,58204:20,58203:20,58202:20,58201:20,58200:20"},
}}
ZLDB.DG["UBRS"]={
Name="Upper Blackrock Spire",
Story="The history of this imposing fortress is long and complex. Carved into the fiery core of Blackrock Mountain by the Dark Iron clan centuries ago, and eventually taken by the black dragon Nefarian and his brood, the upper reaches of Blackrock Spire are now home to the Ironmarch vanguard. As preparations to use the Spire as the staging ground for a full-scale invasion of Azeroth continue, the Iron Horde has set up a terrifying contingency plan: a doomsday weapon within the heart of Blackrock Mountain.",
Background=M.."dungeons\\ubrs\\background",
GridBackground=M.."dungeons\\ubrs\\grid-background",
MapId=17,
IconScale=0.8,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=79,MapCoordinateY=33,MapZoneId=6}},
Type=T.Dungeon,
Key="UBRS",
Bosses={
{Id="9816",Name="Pyroguard Emberseer",Story="Long ago, Pyroguard Emberseer, a loyal minion of the mighty Ragnaros the Firelord, incinerated dozens of Blackrock orcs during a climactic battle at the Burning Steppes. Ultimately Emberseer was defeated and imprisoned within Blackrock Mountain, where his potent energy is now siphoned for use in accelerating the incubation of Nefarian's black dragon eggs.",Portrait=M.."dungeons\\ubrs\\pyroguard-portrait",Frame=M.."dungeons\\ubrs\\pyroguard-frame",L="58199:1,58204:20,58203:20,58202:20,58201:20,58200:20,12905:20,12926:20,12927:20,12929:20,16672:20,23320:8,51217:5,70226:2"},
{Id="10264",Name="Solakar Flamewreath",Story="Gaining favor within the black dragonflight is a mixed blessing. Solakar Flamewreath is entrusted with the care of Nefarian's dragonspawn, but he has been warned he will pay a terrible price for any whelp that dies under his supervision--or simply fails to live up to expectations.",Portrait=M.."dungeons\\ubrs\\solakar-portrait",Frame=M.."dungeons\\ubrs\\solakar-frame",L="12589:20,12603:20,12606:20,12609:20,16695:20,18657:6,51217:5,70226:2"},
{Id="10509",Name="Jed Runewatcher",Story="An elusive orc, rarely seen among the general population of Upper Blackrock Spire. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\ubrs\\jed-portrait",Frame=M.."dungeons\\ubrs\\jed-frame",IsRare=true,L="12604:33,12605:33,12930:33,70226:2"},
{Id="10899",Name="Goraluk Anvilcrack",Story="Goraluk Anvilcrack is a renowned blacksmith. Unfortunately, he sold his soul to the satyr Lorax, but broke the deal and ran away to Upper Blackrock Spire with a rune covered breastplate.",Portrait=M.."dungeons\\ubrs\\goraluk-portrait",Frame=M.."dungeons\\ubrs\\goraluk-frame",L="18779:15,12728:14,12834:14,12837:14,13498:14,13502:14,18047:14,18048:14,70226:2"},
{Id="10429",Name="Warchief Rend Blackhand",Story="After the Horde was defeated in the Second War, Rend Blackhand, son of the first warchief, brought the remnants of his clan to Blackrock Spire and fought the Dark Iron dwarves for possession of the stronghold. Rend allied his orcs with Nefarian and the black dragonflight, who routed the dwarves and expelled them from Blackrock's upper reaches.",Portrait=M.."dungeons\\ubrs\\rend-portrait",Frame=M.."dungeons\\ubrs\\rend-frame",L="12587:23,12935:23,18102:23,18103:23,12588:17,12936:17,16733:17,18104:17,22247:17,12583:8,12940:8,12939:8,51217:5,70226:3,12590:1,12952:20,12953:20,12960:20,16669:20,22225:20,12871:4,13522:3"},
{Id="10430",Name="The Beast",Story="Nefarian's dragonkin take obscene delight in the barbaric torture of Ragnaros's captured minions. Despite suffering unimaginable agony, one core hound remained lucid enough to be retrained, and his ferocity makes him an ideal guard in the upper levels of Blackrock Spire.",Portrait=M.."dungeons\\ubrs\\beast-portrait",Frame=M.."dungeons\\ubrs\\beast-frame",L="24101:13,12709:10,12963:10,12964:10,12965:10,12966:10,12967:10,12968:10,12969:10,16729:10,22311:10,51217:5,70226:2"},
{Id="16042",Name="Lord Valthalak",Story="A drakonid noble and a warlock of immense power, Valthalak was the former General of Blackrock Spire before Drakkisath rose to power. He was slain by the Veiled Blade mercenary company for his spellbook, but ended up avenging himself even after his death using his necromantic powers.",Portrait=M.."dungeons\\ubrs\\valthalak-portrait",Frame=M.."dungeons\\ubrs\\valthalak-frame",L="22302:25,22336:25,22339:25,22342:25,22335:25,22337:25,22340:25,22343:25,51217:5"},
{Id="10363",Name="General Drakkisath",Story="A cunning and ruthless strategist, Drakkisath commands Nefarian's armies in the war with Ragnaros. After securing victories against the Dark Irons, General Drakkisath's forces are positioned to drive the dwarves out of Blackrock Mountain once and for all.",Portrait=M.."dungeons\\ubrs\\drakkisath-portrait",Frame=M.."dungeons\\ubrs\\drakkisath-frame",L="51217:100,22253:25,22267:25,22268:25,22269:25,12602:25,13098:25,13141:25,13142:25,16666:11,16674:11,16688:11,16690:11,16700:11,16706:11,16721:11,16726:11,16730:11,13090:10,47413:10,47415:10,15730:4,70226:3,13519:3,12592:1"},
}}
ZLDB.DG["ULDA"]={
Name="Uldaman",
Story="Uldaman is an ancient Titan vault that has laid buried deep within the earth since the world's creation. Dwarven excavations have recently penetrated this forgotten city, releasing the Titans' first failed creations: the Troggs. Legends say that the Titans created troggs from stone. When they deemed the experiment a failure, the Titans locked the troggs away and tried again - resulting in the creation of the dwarven race. The secrets of the dwarves' creation are recorded on the fabled Discs of Norgannon - massive Titan artifacts that lie at the very bottom of the ancient city. Recently, the Dark Iron dwarves have launched a series of incursions into Uldaman, hoping to claim the discs for their fiery master, Ragnaros. However, protecting the buried city are several guardians - giant constructs of living stone that crush any hapless intruders they find. The Discs themselves are guarded by a massive, sapient Stonekeeper called Archaedas. Some rumors even suggest that the dwarves' stone-skinned ancestors, the earthen, still dwell deep within the city's hidden recesses.",
Background=M.."dungeons\\ulda\\background",
GridBackground=M.."dungeons\\ulda\\grid-background",
MapId=10,
IconScale=0.8,
MinLevel=41,
MaxLevel=50,
Entrances={{MapContinentId=2,MapCoordinateX=36.8,MapCoordinateY=28.1,MapZoneId=35},{MapContinentId=2,MapCoordinateX=65.5,MapCoordinateY=43.4,MapZoneId=4}},
Type=T.Dungeon,
Key="ULDA",
Bosses={
{Id="6906",Name="The Lost Dwarves",Story="Seeking fame and, more importantly, fortune, the three brothers Eric, Olaf, and Baelog took on a contract from the Explorers' League to delve deep into the halls of Uldaman and clear a path for a group of researchers. For these three dwarves, however, \"clearing a path\" unfortunately entailed \"getting hopelessly lost in an ancient labyrinth.\" Proud dwarves to the end, they fight to prevent the secrets of Uldaman and the Explorers' League from falling into the hands of the Horde.",Portrait=M.."dungeons\\ulda\\dwarves-portrait",Frame=M.."dungeons\\ulda\\dwarves-frame",MapCoordinateX=58.7,MapCoordinateY=92.2,L="9399:100,9401:50,9400:50,9394:50,9398:50,9403:50,9404:50"},
{Id="6910",Name="Revelosh",Story="Some luminaries in Ironforge's prestigious Explorers' League have theorized an ancestral link between their people and the troggs, and pointed towards the troggs' hoarding of titan artifacts as a reflection of the dwarves' own reverence for such wondrous devices. If that is true, the trogg known as Revelosh can be considered the trogg equivalent of an archaeologist, although any historically minded adventurers who encounter him would be more inclined to call him a thief.",Portrait=M.."dungeons\\ulda\\revelosh-portrait",Frame=M.."dungeons\\ulda\\revelosh-frame",MapCoordinateX=53.2,MapCoordinateY=72.5,L="9387:25,9388:25,9389:25,9390:25"},
{Id="7228",Name="Ironaya",Story="The titans did not construct the Uldaman complex directly but utilized various servants to create its megalithic halls. The Pantheon entrusted the watcher Ironaya with overseeing the construction and maintenance of Uldaman, but as time passed, the once awe-inspiring vault fell to ruin. Within the map chamber, Ironaya has spent millennia in a form of stasis, analyzing the original master plan drawn up by Khaz'goroth and attempting to find a way to restore the complex to its original functionality.",Portrait=M.."dungeons\\ulda\\ironaya-portrait",Frame=M.."dungeons\\ulda\\ironaya-frame",MapCoordinateX=37,MapCoordinateY=73.8,L="9407:33,9408:33,9409:33,51217:1"},
{Id="7023",Name="Obsidian Sentinel",Story="The Obsidian Sentinel was responsible for guarding Uldaman's secrets until it was affected by corruption by an unknown force. Originally crafted from the same stone as the halls of Uldaman itself, this keeper has had the majority of its body replaced with dark glass capable of reflecting spells. Whatever was responsible for the Obsidian Sentinel's transformation must be incredibly potent, for it is not easy to alter the enchanted stone of a titan construct.",Portrait=M.."dungeons\\ulda\\sentinel-portrait",Frame=M.."dungeons\\ulda\\sentinel-frame",MapCoordinateX=29.1,MapCoordinateY=60},
{Id="7206",Name="Ancient Stone Keeper",Story="One of many golems that staffed and operated the great titan vault, the Ancient Stone Keeper was part of a small group that served as an intermediary between the watchers left in control of the facility and their many servants. With the corruption of the Obsidian Sentinel, the Ancient Stone Keeper is the last of its kind, performing its duty by protecting the secrets of the titans as best it can until its inevitable shutdown.",Portrait=M.."dungeons\\ulda\\keeper-portrait",Frame=M.."dungeons\\ulda\\keeper-frame",MapCoordinateX=47.5,MapCoordinateY=44.3,L="9410:50,9411:35,80746:15"},
{Id="7291",Name="Galgann Firehammer",Story="Reacting to the discovery of Uldaman by Bronzebeard dwarves, the Dark Iron clan mounted an invasion of the vault to stop their ancestral foes from accessing the powerful artifacts within. Galgann Firehammer, a senator from Shadowforge City, was sent to oversee the continued excavation of Uldaman so that the emperor may harness the artifacts' destructive potential against the Dark Irons' enemies.",Portrait=M.."dungeons\\ulda\\galgann-portrait",Frame=M.."dungeons\\ulda\\galgann-frame",MapCoordinateX=26.6,MapCoordinateY=32.6,L="11311:25,11310:25,9419:25,9412:25"},
{Id="4854",Name="Grimlok",Story="In trogg society, the biggest, strongest, and most vicious trogg often becomes chieftain through displays of power. Grimlok is a comparative genius in that he has maintained control of the Stonevault troggs through intimidation and what might be considered crude psychological warfare. Having trained a deadly basilisk, Grimlok uses the threat of petrification by his beast to keep any would-be usurpers in line.",Portrait=M.."dungeons\\ulda\\grimlok-portrait",Frame=M.."dungeons\\ulda\\grimlok-frame",MapCoordinateX=22.1,MapCoordinateY=26,L="9414:33,9415:33,9416:33,51217:1"},
{Id="2748",Name="Archaedas",Story="Deep within Uldaman is a chamber containing one of the greatest treasures of the titans, created by Norgannon himself. However, thus far no explorers have managed to gain access to the relic, for any attempt at doing so activates the great watcher Archaedas, an immense guardian who easily dispatches treasure seekers through his powerful attacks and a veritable army of servants. Crafted from some of the oldest, strongest stone taken from Uldaman's depths, Archaedas is a foe as formidable as he is ancient.",Portrait=M.."dungeons\\ulda\\archaedas-portrait",Frame=M.."dungeons\\ulda\\archaedas-frame",MapCoordinateX=41.6,MapCoordinateY=16.6,MapIsBelow=true,L="9413:33,9418:33,11118:33,51217:5"},
}}
ZLDB.DG["WC"]={
Name="Wailing Caverns",
Story="Years ago, the famed druid Naralex and his followers descended into the shadowy Wailing Caverns, named for the mournful cry one hears when steam bursts from the cave system's fissures. Naralex planned to use the underground springs to restore lushness to the arid Barrens. But upon entering the Emerald Dream, he saw his vision of regrowth turn into a waking nightmare, one that has plagued the caverns ever since.",
Background=M.."dungeons\\wc\\background",
GridBackground=M.."dungeons\\wc\\grid-background",
MapId=18,
IconScale=0.9,
MinLevel=16,
MaxLevel=25,
Entrances={{MapContinentId=1,MapCoordinateX=54.9,MapCoordinateY=66.7,MapZoneId=33}},
Type=T.Dungeon,
Key="WC",
Bosses={
{Id="3653",Name="Kresh",Story="An ancient resident of the Wailing Caverns, this giant turtle wanders the underground caves, his resilient mind unaffected by Naralex's relentless nightmares. Don't be fooled by his happy disposition; Kresh has thwarted many adventurers who longed to steal his massive shell",Portrait=M.."dungeons\\wc\\kresh-portrait",Frame=M.."dungeons\\wc\\kresh-frame",MapCoordinateX=44.3,MapCoordinateY=28.5,L="13245:33,80710:33,6447:33"},
{Id="3669",Name="Lord Cobrahn",Story="Jarlaxla's skill at harnessing animal forms earned him renown among the druids of the Cenarion Circle. However, the Wailing Caverns' corruption twisted his unique abilities. Now, Jarlaxla has perfected a deadly serpentine form, renaming himself Cobrahn to reflect his vicious new found power.",Portrait=M.."dungeons\\wc\\cobrahn-portrait",Frame=M.."dungeons\\wc\\cobrahn-frame",MapCoordinateX=32.5,MapCoordinateY=45.3,L="6460:33,6465:33,10410:33"},
{Id="5912",Name="Deviate Faerie Dragon",Story="An elusive faerie dragon, rarely seen among the denizens of Wailing Caverns. It is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter it in the first place...",Portrait=M.."dungeons\\wc\\deviate-portrait",Frame=M.."dungeons\\wc\\deviate-frame",MapCoordinateX=73.7,MapCoordinateY=29.8,IsRare=true,L="5243:50,6632:50"},
{Id="61968",Name="Zandara Windhoof",Story="As slippery as the shadows themselves, the Kolkar centaur found their way into a hidden branch of the Winding Chasm through the narrowest of cracks. Leading this invasion is the zealous Zandara Windhoof, who has audaciously claimed the Wailing Caverns as her own birthright. Her presence is a direct insult to the Earthmother, bringing nothing but destruction to a place already suffering under the weight of Naralex's failed dream.",Portrait=M.."dungeons\\wc\\zandara-portrait",Frame=M.."dungeons\\wc\\zandara-frame",MapCoordinateX=67,MapCoordinateY=16.7,L="55371:50,55369:25,55370:25"},
{Id="3670",Name="Lord Pythas",Story="A childhood friend of Naralex, the warrior Aryn was a quick study in druidism. Despite his training, the acolyte was defenseless against the corruption that would strip away his sanity. Aryn has taken on the name Pythas, combining his impressive melee prowess with his druidic arsenal to vanquish intruders.",Portrait=M.."dungeons\\wc\\pythas-portrait",Frame=M.."dungeons\\wc\\pythas-frame",MapCoordinateX=88.1,MapCoordinateY=23.4,L="6472:33,6473:33,80711:33"},
{Id="3674",Name="Skum",Story="Skum first journeyed to the Wailing Caverns for relief from the Barrens' hostile environment. Like many of the caves' other inhabitants, he quickly succumbed to corruption. His veins now pulse with dark energies that have transformed him into a mighty and ruthless beast beyond redemption.",Portrait=M.."dungeons\\wc\\skum-portrait",Frame=M.."dungeons\\wc\\skum-frame",MapCoordinateX=93.8,MapCoordinateY=63.1,L="6448:33,6449:33,80712:33"},
{Id="61965",Name="Vangros",Story="Naralex's attempt to restore the Barrens inadvertently birthed a waking nightmare, causing irreparable damage to the balance of Kalimdor. Vangros is a testament to the volatility of these involuntary powers; a manifestation of the rampant, violent overgrowths that have begun to move of their own accord within the stone labyrinth. This creature radiates a corrupted druidic magic, serving as a dangerous countermeasure against any who seek to navigate the cursed maze and free the Dreamer from his eternal slumber.",Portrait=M.."dungeons\\wc\\vangros-portrait",Frame=M.."dungeons\\wc\\vangros-frame",MapCoordinateX=86.2,MapCoordinateY=80.9,L="55374:50,55372:25,55373:25"},
{Id="3673",Name="Lord Serpentis",Story="The Druids of the Fang's leader was once Naralex's finest student. His tragic downfall stemmed from his desire to become a shan'do, or honored teacher like Naralex. As insanity took root, Serpentis rallied his brethren to his side and formed the Druids of the Fang.",Portrait=M.."dungeons\\wc\\serpentis-portrait",Frame=M.."dungeons\\wc\\serpentis-frame",MapCoordinateX=69,MapCoordinateY=42.9,L="10411:25,6469:25,6459:25,5970:25"},
{Id="3671",Name="Lady Anacondra",Story="Scarletleaf was the first to volunteer for Naralex's self-appointed mission to the Barrens. After her master's nightmare shattered her mind, the young acolyte cast aside her name, now envisioning a sinister reptilian future for Azeroth.",Portrait=M.."dungeons\\wc\\anacondra-portrait",Frame=M.."dungeons\\wc\\anacondra-frame",MapCoordinateX=50.5,MapCoordinateY=25,L="5404:25,6446:25,10412:25,80709:25,23800:1"},
{Id="5775",Name="Verdan the Everliving",Story="Little is known about this creature prior to Naralex's arrival at the Wailing Caverns. Thought to be the caves' original guardian, Verdan the Everliving could not escape the corruption that befell its home. Verdan is allied with the insane druids and maintains its vigil against those who trespass into its domain.",Portrait=M.."dungeons\\wc\\verdan-portrait",Frame=M.."dungeons\\wc\\verdan-frame",MapCoordinateX=64.2,MapCoordinateY=37.5,L="6629:33,6630:33,6631:33"},
{Id="3654",Name="Mutanus the Devourer",Story="From the darkest corners of Naralex's twisted mind, the corruption plaguing the Emerald Dream has manifested in the form of the druid's worst enemy: murlocs. The aberration known as Mutanus has come to the waking world to devour any who seek to liberate Naralex from the Nightmare's clutches.",Portrait=M.."dungeons\\wc\\mutanus-portrait",Frame=M.."dungeons\\wc\\mutanus-frame",MapCoordinateX=46.7,MapCoordinateY=12.1,L="6461:25,6463:25,6627:25,81006:25,51217:1"},
}}
ZLDB.DG["WHC"]={
Name="Windhorn Canyon",
Story="This ancient canyon has been home to many tauren tribes who have in years past fought for the dominance of its flowing waters and shelter from the dangers of Kalimdor. The cultures and traditions of many have lived within Windhorn Canyon, which can be seen from the ancient shelters carved into the mountainside, to the relics coveted by the Tauren. As of recently the Windhorn Tauren were expelled and driven away by the Grimtotem who have conquered it, and claimed it for their own.",
Background=M.."dungeons\\whc\\background",
GridBackground=M.."dungeons\\whc\\grid-background",
MapId=45,
IconScale=1,
MinLevel=26,
MaxLevel=30,
Entrances={{MapContinentId=1,MapCoordinateX=68.7,MapCoordinateY=25.7,MapZoneId=34}},
Type=T.Dungeon,
Key="WHC",
Bosses={
{Id="pathun",Name="Pathun Duskhide",Story="Whatever brought Pathun Duskhide to the canyon, it was not recorded. Whatever kept him there, even less so.",Portrait=M.."dungeons\\whc\\pathun-portrait",Frame=M.."dungeons\\whc\\pathun-frame",MapCoordinateX=33.1,MapCoordinateY=44.3,L="33025:25,33026:25,33028:25,33027:25,70242:6"},
{Id="ahgktos",Name="Ahgk'tos the Pure",Story="Pure in what regard, and by whose measure - those who might have answered are long gone from Windhorn Canyon.",Portrait=M.."dungeons\\whc\\ahgktos-portrait",Frame=M.."dungeons\\whc\\ahgktos-frame",MapCoordinateX=26.3,MapCoordinateY=9.7,L="33024:25,33022:25,33023:25,33021:25"},
{Id="vortalus",Name="Ambassador Vortalus",Story="Windhorn Canyon holds no record of Ambassador Vortalus - only the title, and the threat it implies.",Portrait=M.."dungeons\\whc\\vortalus-portrait",Frame=M.."dungeons\\whc\\vortalus-frame",MapCoordinateX=36.8,MapCoordinateY=62,MapIsBelow=true,Abilities={{Effect="Vortalus stuns a random enemy, rendering them unable to move or attack for 4 seconds.",Flags={F.Interruptible,F.Important},Icon="spell_nature_earthbind",Id="6982",Name="Gust of Wind"},{Effect="Vortalus creates a lightning bolt that chains between all enemies.",Flags={F.Interruptible},Icon="spell_nature_chainlightning",Id="vortaluschainlightning",Name="Chain Lightning"}},L="33030:25,33031:25,33029:25,33032:25"},
{Id="walgan",Name="Walgan Bloodcaller",Story="The name Walgan Bloodcaller has passed through no chronicle, left no mark - nothing but the name itself.",Portrait=M.."dungeons\\whc\\walgan-portrait",Frame=M.."dungeons\\whc\\walgan-frame",MapCoordinateX=18.2,MapCoordinateY=68.7,L="33082:25,33035:25,42275:25,33033:25"},
{Id="narlgom",Name="Bonespeaker Narlgom",Story="Among the Grimtotem who seized Windhorn Canyon, Bonespeaker Narlgom is counted - and that is, in full, the extent of what is known.",Portrait=M.."dungeons\\whc\\narlgom-portrait",Frame=M.."dungeons\\whc\\narlgom-frame",MapCoordinateX=36.8,MapCoordinateY=56.8,MapIsBelow=true,L="42276:25,33040:25,33038:25,33037:25"},
{Id="stormhoof",Name="Prophet Stormhoof",Story="Prophets speak of things to come. If Prophet Stormhoof ever did, no one was left to write it down.",Portrait=M.."dungeons\\whc\\stormhoof-portrait",Frame=M.."dungeons\\whc\\stormhoof-frame",MapCoordinateX=40.5,MapCoordinateY=56,MapIsBelow=true,Abilities={{Effect="Stormhoof corrupts a random enemy, dealing shadow damage over time.",Flags={F.Curse},Icon="spell_shadow_abominationexplosion",Id="stormhoofcorruption",Name="Corruption"}},L="33043:25,33042:25,33044:25,33041:25,70244:6"},
{Id="shalk",Name="Chieftain Shalk Blackwind",Story="He conquered. He rules. Beyond that, the canyon offers nothing of Chieftain Shalk Blackwind.",Portrait=M.."dungeons\\whc\\shalk-portrait",Frame=M.."dungeons\\whc\\shalk-frame",MapCoordinateX=48.6,MapCoordinateY=44,L="33047:33,33046:33,33045:33,42277:1,70243:6,33048:25"},
}}
ZLDB.DG["ZF"]={
Name="Zul'Farrak",
Story="Zul'Farrak was once the shining jewel of Tanaris, ferociously protected by the cunning Sandfury tribe. Despite the trolls' tenacity, this isolated group was forced to surrender much of its territory throughout history. Now, it appears that Zul'Farrak's inhabitants are creating a horrific army of undead trolls to conquer the surrounding region. Other disturbing rumors tell of an ancient creature sleeping within the city--one that, if awakened, will rain death and destruction across Tanaris.",
Background=M.."dungeons\\zf\\background",
GridBackground=M.."dungeons\\zf\\grid-background",
MapId=5,
IconScale=0.8,
MinLevel=42,
MaxLevel=51,
Entrances={{MapContinentId=1,MapCoordinateX=39.2,MapCoordinateY=20.1,MapZoneId=24}},
Type=T.Dungeon,
Key="ZF",
Bosses={
{Id="10082",Name="Zerillis",Story="An elusive troll, rarely seen accross the city of Zul'Farrak. He is said to possess lots of coveted items that many wish they could lay their hands on, if only they could encounter him in the first place...",Portrait=M.."dungeons\\zf\\zerillis-portrait",Frame=M.."dungeons\\zf\\zerillis-frame",MapCoordinateX=52.4,MapCoordinateY=41.6,IsRare=true,L="12470:19"},
{Id="7272",Name="Theka the Martyr",Story="Long ago, the martyr Theka was slain in the brutal war between the qiraji and the trolls. Zul'Farrak still stands because of his brave sacrifice. Even in death he maintains a vigil over his beloved city, and it is said that the dozens of insectoid warriors who killed him were cursed to live as mindless scarabs, scuttling at the martyr's side.",Portrait=M.."dungeons\\zf\\theka-portrait",Frame=M.."dungeons\\zf\\theka-frame",MapCoordinateX=52.9,MapCoordinateY=26.2},
{Id="8127",Name="Antu'sul",Story="Antu'sul prefers his sul'lithuz basilisks strong and ruthless. He treats these scaled beasts like family, and he is known to strike down anyone--even fellow trolls--who harm his precious children. Rather than give his opponents a proper burial, Antu'sul allows the basilisks to feast on whoever dares cross him.",Portrait=M.."dungeons\\zf\\antusul-portrait",Frame=M.."dungeons\\zf\\antusul-frame",MapCoordinateX=64.4,MapCoordinateY=27.6,L="9379:25,9639:25,9640:25,9641:25,51217:1,9243:2"},
{Id="7271",Name="Witch Doctor Zum'rah",Story="The powerful loa Bwonsamdi watches over the spirits of the Darkspear trolls, but many of the Sandfury tribe's fallen members are offered no such protection after death. These tortured spirits obey Zum'rah, a cruel witch doctor who uses his dark magic to force the city's dead into unending service.",Portrait=M.."dungeons\\zf\\zumrah-portrait",Frame=M.."dungeons\\zf\\zumrah-frame",MapCoordinateX=44.2,MapCoordinateY=17.5,L="18082:50,18083:50,51803:8,9243:2,51217:1"},
{Id="7275",Name="Shadowpriest Sezz'ziz",Story="Nekrum Gutchewer has mysteriously lived well past his natural life, but his decaying body remains strong enough to aid Sezz'ziz. Together, these two trolls have gathered sacrifices to the mythic beast Gahz'rilla, who slumbers at the city's heart. Many troll followers eagerly await the terrifying creature's awakening, and they will do anything to see the ritual through.",Portrait=M.."dungeons\\zf\\sezzziz-portrait",Frame=M.."dungeons\\zf\\sezzziz-frame",MapCoordinateX=29.4,MapCoordinateY=16.8,L="9470:25,9473:25,9474:25,9475:25,9243:2,51217:1"},
{Id="7267",Name="Chief Ukorz Sandscalp",Story="Chief Ukorz Sandscalp is obsessed with restoring his tribe to its former glory. He was raised on stories of a time when trolls lorded over their ancient lands without interference from goblins, gnomes, pirates, ogres, and other foreign interlopers. Sandscalp has called on his trusted comrade Ruuzlu to help him begin a new chapter in Sandfury history in the only way their tribe knows how: with swift and blinding violence.",Portrait=M.."dungeons\\zf\\ukorz-portrait",Frame=M.."dungeons\\zf\\ukorz-frame",MapCoordinateX=42.3,MapCoordinateY=33.7,L="9476:20,9477:20,9478:20,9479:20,11086:20,9243:2,51217:5"},
{Id="7273",Name="Gahz'rilla",Story="Legend has it that Gahz'rilla was an adored pet of the Old Gods, or even a demigod in her own right. Whatever the truth is, the Sandfury trolls have worshiped this monstrous hydra for thousands of years. Ever wary of the beast's icy wrath, the trolls will only rouse Gahz'rilla when they have plentiful sacrifices to sate the ravenous creature's appetite.",Portrait=M.."dungeons\\zf\\gahzrilla-portrait",Frame=M.."dungeons\\zf\\gahzrilla-frame",MapCoordinateX=31.5,MapCoordinateY=41.3,L="9469:50,9467:30,80747:20,51217:1"},
{Id="62495",Name="Zel'jeb the Ancient",Story="While Chief Ukorz Sandscalp was once a promising leader whose mind was eventually warped by dark magics, Zel'jeb represents the older, lingering shadows of the Sandfury tribe. This ancient troll serves as a grim reminder of the magic that began the corruption of the city's leadership, helping to fuel the brutal and cold nature that now defines the chief's inner sanctum. As the sands of Zul'Farrak shift, Zel'jeb stands alongside the tribe's most fanatical warriors, ensuring that the legacy of their warped power does not simply drift away like sand on the dunes.",Portrait=M.."dungeons\\zf\\zeljeb-portrait",Frame=M.."dungeons\\zf\\zeljeb-frame",MapCoordinateX=14.1,MapCoordinateY=32,L="58116:25,58117:25,58118:25,58119:25"},
{Id="62498",Name="Farraki Arena",Story="The Farraki Arena is a reputed battleground where trolls from all accross the city of Zul'Farrak come and compete in bloody death matches.",Portrait=M.."dungeons\\zf\\arena-portrait",Frame=M.."dungeons\\zf\\arena-frame",MapCoordinateX=43.8,MapCoordinateY=58.3,L="58092:25,58093:25,58094:25,58095:25"},
}}
ZLDB.R["AQ20"]={
Name="Ruins of Ahn'Qiraj",
Story="During the final hours of the War of the Shifting Sands, the combined forces of the night elves and the four dragonflights drove the battle to the very heart of the qiraji empire, to the fortress city of Ahn'Qiraj. Yet at the city gates, the armies of Kalimdor encountered a concentration of silithid war drones more massive than any they had encountered before. Ultimately the silithid and their qiraji masters were not defeated, but merely imprisoned inside a magical barrier, and the war left the cursed city in ruins. A thousand years have passed since that day, but the qiraji forces have not been idle. A new and terrible army has been spawned from the hives, and the ruins of Ahn'Qiraj are teeming once again with swarming masses of silithid and qiraji. This threat must be eliminated, or else all of Azeroth may fall before the terrifying might of the new qiraji army.",
Background=M.."raids\\aq20\\background",
GridBackground=M.."raids\\aq20\\grid-background",
MapId=15,
IconScale=0.8,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=58.7,MapCoordinateY=14.1,MapZoneId=14}},
Type=T.Raid,
Key="AQ20",
Bosses={
{Id="15348",Name="Kurinnaxx",Story="Deep in the marrow of the hive, the Horde led by Varok Saurfang faced Kurinnaxx when they raided the ruins.",Portrait=M.."raids\\aq20\\kurinnaxx-portrait",Frame=M.."raids\\aq20\\kurinnaxx-frame",MapCoordinateX=56,MapCoordinateY=35.9,Abilities={{Effect="Kurinnaxx strike up to three enemies in front of him, dealing weapon damage plus an additional 200 physical damage.\
\
This attack applies Mortal Wounds on the target.",Flags={F.Tank,F.Important},Icon="Ability_Warrior_Cleave",Id="26350",Name="Cleave",SubAbilities={{Effect="A stacking debuff that reduces healing received by 10% for 30 seconds.\
\
This effect stacks rapidly, requiring tanks to swap at 3 to 4 stacks to avoid being overwhelmed.",Flags={F.Tank,F.Important},Icon="Ability_CriticalStrike",Id="25646",Name="Mortal Wound"}}},{Effect="Kurinnaxx creates sand traps beneath random players that expand over time and detonate after a few seconds.\
\
Affected players are silenced and have their melee and ranged hit chance reduced by 75% for 20 seconds.\
\
Players should move out of traps immediately. Spreading out reduces the risk of multiple players being affected.",Icon="INV_Misc_Dust_02",Id="25656",Name="Sand Trap"},{Effect="At 30% health. Kurinnaxx becomes enraged, increasing his damage dealt significantly.",Flags={F.Deadly,F.Important},Icon="Spell_Shadow_UnholyFrenzy",Id="kurinnaxxenrage",Name="Enrage"}},L="20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:25,20885:25,20888:25,20889:25,21498:17,21499:17,21500:17,21501:17,21502:17,21503:17"},
{Id="15341",Name="General Rajaxx",Story="During the War of the Shifting Sands, the monstrous, towering Rajaxx commanded the qiraji and silithid in battle, swinging clawed limbs and shouting commands to his soldiers. During the war, he clashed with Fandral and Valstann Staghelm, the leaders of the night elf forces, and later personally executed Valstann by ripping him in two with his claws.",Portrait=M.."raids\\aq20\\rajaxx-portrait",Frame=M.."raids\\aq20\\rajaxx-frame",MapCoordinateX=58.6,MapCoordinateY=49.3,L="20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:25,20885:25,20888:25,20889:25,21492:17,21493:17,21494:17,21495:17,21496:17,21497:17,81004:10"},
{Id="15340",Name="Moam",Story="The Twin Emperors intended to use Moam as a colossal weapon, knowing that its strengths would help it survive in the thick of melee as well as magical combat-but they did not expect for the construct's abilities to advance further without their own assistance.",Portrait=M.."raids\\aq20\\moam-portrait",Frame=M.."raids\\aq20\\moam-frame",MapCoordinateX=32.9,MapCoordinateY=36.7,L="22220:15,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:25,20886:25,20888:25,20890:25,21455:11,21468:11,21469:11,21470:11,21473:11,21474:11,21475:11,21476:11,21477:11,21467:25,21471:25,21472:25,21479:25"},
{Id="15370",Name="Buru the Gorger",Story="Lurking beneath the ruins, Buru the Gorger is a massive silithid colossus with an insatiable appetite. It feeds on any intruders who stumble into its hatchery, crushing them with immense physical force before consuming them to sustain its massive bulk.",Portrait=M.."raids\\aq20\\buru-portrait",Frame=M.."raids\\aq20\\buru-frame",MapCoordinateX=70.1,MapCoordinateY=62.4,L="20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:17,20885:17,20886:17,20888:17,20889:17,20890:17,21485:14,21486:14,21487:14,21488:14,21489:14,21490:14,21491:14"},
{Id="15369",Name="Ayamiss the Hunter",Story="Ayamiss is the matriarch of the deadly silithid wasp swarm that infests the Ruins of Ahn'Qiraj. From the air, she commands her brood to sacrifice any who enter her domain, using their life force to feed the writhing larvae waiting to hatch below.",Portrait=M.."raids\\aq20\\ayamiss-portrait",Frame=M.."raids\\aq20\\ayamiss-frame",MapCoordinateX=61.8,MapCoordinateY=90,L="20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:4,21279:4,21280:4,21281:4,21282:4,21283:4,21284:4,21285:4,21287:4,21288:4,21289:4,21290:4,21291:4,21292:4,21293:4,21294:4,21295:4,21296:4,21297:4,21298:4,21299:4,21300:4,21302:4,21303:4,21304:4,21306:4,21307:4,20884:17,20885:17,20886:17,20888:17,20889:17,20890:17,21466:12,21478:12,21479:12,21480:12,21481:12,21482:12,21483:12,21484:12"},
{Id="15339",Name="Ossirian the Unscarred",Story="Ossirian serves the twin Emperors to the best of his ability, despite the frustration of being eternally bound to a single location. The bones of Grakkarond have become a sacred site to the Anubisaths; a testimony to their ability to defeat even the most powerful of enemies.",Portrait=M.."raids\\aq20\\ossirian-portrait",Frame=M.."raids\\aq20\\ossirian-frame",MapCoordinateX=43.3,MapCoordinateY=69.3,L="21220:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21214:11,21279:11,21280:11,21281:11,21282:11,21283:11,21288:11,21291:11,21297:11,21284:11,21285:11,21287:11,21289:11,21292:11,21294:11,21295:11,21296:11,21298:11,21457:15,21459:10,21460:15,21461:15,21462:15,21463:15,21464:15,21452:18,21453:18,21454:18,21456:18,21458:18,21715:10,21290:11,21293:11,21299:11,21300:11,21302:11,21303:11,21304:11,21306:11,21307:11,20886:50,20890:50,132:6"},
}}
ZLDB.R["AQ40"]={
Name="Temple of Ahn'Qiraj",
Story="At the heart of Ahn'Qiraj lies an ancient temple complex. Built in the time before recorded history, it is both a monument to unspeakable gods and a massive breeding ground for the qiraji army. Since the War of the Shifting Sands ended a thousand years ago, the Twin Emperors of the qiraji empire have been trapped inside their temple, barely contained behind the magical barrier erected by the bronze dragon Anachronos and the night elves.",
Background=M.."raids\\aq40\\background",
GridBackground=M.."raids\\aq40\\grid-background",
MapId=28,
ZoneId=2,
IconScale=0.8,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=46.4,MapCoordinateY=7.7,MapDestinationZoneId=2,MapZoneId=14}},
Type=T.Raid,
Key="AQ40",
Bosses={
{Id="15263",Name="The Prophet Skeram",Story="The Prophet Skeram is an important religious leader in Ahn'Qiraj, and author of The Prophecy of C'Thun.",Portrait=M.."raids\\aq40\\skeram-portrait",Frame=M.."raids\\aq40\\skeram-frame",MapCoordinateX=46,MapCoordinateY=51.7,MapId=2,L="22222:15,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21128:10,21698:18,21699:18,21700:18,21701:18,21702:18,21703:10,21704:15,21705:15,21706:15,21707:15,21708:15,21814:15,21232:4,21237:4"},
{Id="15544",Name="Silithid Royalty",Story="The Silithid Royalty consists of Lord Kri, Princess Yauj, and Vem. This deadly trio serves the Qiraji empire by coordinating the insectoid swarms. They fight as one cohesive unit, flying into a blood-frenzied rage if one of their own falls in combat.",Portrait=M.."raids\\aq40\\trio-portrait",Frame=M.."raids\\aq40\\trio-frame",MapCoordinateX=28.5,MapCoordinateY=49.6,MapId=1,L="21688:25:n3,21689:25:n3,21690:25:n3,21691:25:n3,21682:20:n4,21683:20:n4,21684:20:n4,21686:20:n4,21687:20:n4,21603:25:n5,21680:25:n5,21681:25:n5,21685:25:n5,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21692:17,21693:17,21694:17,21695:17,21696:17,21697:17"},
{Id="15516",Name="Battleguard Sartura",Story="Battleguard Sartura is the leader of the Qiraji battleguards.",Portrait=M.."raids\\aq40\\sartura-portrait",Frame=M.."raids\\aq40\\sartura-frame",MapCoordinateX=44.6,MapCoordinateY=33.6,MapId=1,L="20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21666:10,21667:15,21668:15,21669:15,21670:15,21671:15,21672:15,21648:18,21673:10,21674:18,21675:18,21676:18,21678:18"},
{Id="15510",Name="Fankriss the Unyielding",Story="A colossal sand reaver and spawn of the legendary Ouro, Fankriss the Unyielding dwells deep within the tunnels of the Temple of Ahn'Qiraj. He fiercely guards the subterranean pathways of the temple, ambushing interlopers alongside endless waves of silithid hatchlings.",Portrait=M.."raids\\aq40\\fankriss-portrait",Frame=M.."raids\\aq40\\fankriss-frame",MapCoordinateX=62.2,MapCoordinateY=22.6,MapId=1,L="20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21650:10,21651:18,21652:18,21663:18,21664:18,21665:18,21627:15,21635:10,21639:15,21645:15,21647:15,22396:15,22402:15"},
{Id="15299",Name="Viscidus",Story="Viscidus is a massive, noxious slime lurking within the dark depths of the temple. Believed to be an ancient, gelatinous entity kept by the Qiraji, it is nearly impervious to physical harm and must be frozen solid before it can be shattered into vulnerable pieces.",Portrait=M.."raids\\aq40\\viscidus-portrait",Frame=M.."raids\\aq40\\viscidus-frame",MapCoordinateX=72.2,MapCoordinateY=17.9,MapId=1,L="20928:100,20932:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21622:14,21623:14,21624:14,21625:14,21626:14,21677:14,22399:14"},
{Id="15509",Name="Princess Huhuran",Story="Princess Huhuran is a massive, highly toxic silithid wasp stationed deep within the Temple of Ahn'Qiraj. She relentlessly defends the hive, unleashing devastating volleys of acidic poison and frenzied attacks to melt through the armor of any who dare threaten the Qiraji brood.",Portrait=M.."raids\\aq40\\huhuran-portrait",Frame=M.."raids\\aq40\\huhuran-frame",MapCoordinateX=43.5,MapCoordinateY=50.1,MapId=1,L="20928:100,20932:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21616:17,21617:17,21618:17,21619:17,21620:17,21621:17"},
{Id="15276",Name="The Twin Emperors",Story="The clever brothers Vek'lor and Vek'nilash are known as the Twin Emperors. They rule over the qiraji from the sanctuary of their temple.",Portrait=M.."raids\\aq40\\twins-portrait",Frame=M.."raids\\aq40\\twins-frame",MapCoordinateX=60.7,MapCoordinateY=69.9,MapId=1,L="20735:6,20930:100,21232:4,21237:4,21597:17,21598:17,21599:17,21600:17,21601:17,21602:17,20726:6,20926:100,21604:14,21605:14,21606:14,21607:14,21608:14,21609:14,21679:14"},
{Id="15517",Name="Ouro",Story="The ancient sand worm, Ouro, is a being of legendary power. He is rumored to have been created by the Old God C'Thun himself as a mockery of life. His skin is unnaturally thick, nearly impregnable. It's flexible and allows him to move with the speed and grace of a much smaller creature.",Portrait=M.."raids\\aq40\\ouro-portrait",Frame=M.."raids\\aq40\\ouro-frame",MapCoordinateX=30.4,MapCoordinateY=81.4,MapId=1,L="20927:100,20931:100,20727:1,20728:1,20729:1,20730:1,20731:1,20734:1,20736:1,21232:4,21237:4,21610:17,21611:17,21615:17,23557:17,23558:17,23570:17,21612:17,21613:17,21614:17,55553:17,55554:17,55555:17"},
{Id="15727",Name="C'Thun",Story="C'Thun is the Old God of madness and chaos, one of the four ancient and powerful creatures who ruled the world of Azeroth long ago before being defeated and imprisoned by servants of the titans. C'Thun created the qiraji and resided within the city of Ahn'Qiraj in Silithus.",Portrait=M.."raids\\aq40\\cthun-portrait",Frame=M.."raids\\aq40\\cthun-frame",MapCoordinateX=33.3,MapCoordinateY=49.1,MapId=1,L="20929:100,20933:100,21221:100,21126:8,21585:18,21586:18,21596:18,22730:18,22731:18,21134:8,21581:21,21582:21,21583:21,21839:8,22732:21,36550:1,21579:15,41077:8,60003:8"},
}}
ZLDB.R["BWL"]={
Name="Blackwing Lair",
Story="In the dark recesses of the mountain's peak, Nefarian, the eldest son of Deathwing, conducts some of his most awful experimentation, controlling mighty beings like puppets and combining the eggs of different dragonflights with horrific results. Should he prove successful, even darker pursuits rest on the horizon. And, yet, the Lord of Blackrock is not a mere scientist - he is a great dragon cornered in his lair. Can he truly be defeated by mortal hands?",
Background=M.."raids\\bwl\\background",
GridBackground=M.."raids\\bwl\\grid-background",
MapId=20,
IconScale=1,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=64.1,MapCoordinateY=71.7,MapZoneId=6}},
Type=T.Raid,
Key="BWL",
Bosses={
{Id="12435",Name="Razorgore the Untamed",Story="Razorgore the Untamed is a dragonspawn of the black dragonflight. He has been tasked by the lord of Blackwing Lair, Nefarian, with guarding the numerous and precious black dragon eggs located in the first room of the instance. To this end, Razorgore has been given command of a cohort of orcs and other forces, and will stop at nothing to ensure that no harm comes to his grave charges.",Portrait=M.."raids\\bwl\\razorgore-portrait",Frame=M.."raids\\bwl\\razorgore-frame",MapCoordinateX=54.1,MapCoordinateY=72.5,MapIsBelow=true,L="16904:11,16911:11,16918:11,16926:11,16934:11,16935:11,16943:11,16951:11,16959:11,19334:10,19335:10,19336:20,19337:20,19369:20,19370:20"},
{Id="13020",Name="Vaelastrasz the Corrupt",Story="Vaelastrasz the Corrupt was corrupted by Nefarian and now serves him unwillingly.",Portrait=M.."raids\\bwl\\vaelastrasz-portrait",Frame=M.."raids\\bwl\\vaelastrasz-frame",MapCoordinateX=46.5,MapCoordinateY=47,MapIsBelow=true,L="16818:11,16903:11,16910:11,16925:11,16933:11,16936:11,16944:11,16952:11,16960:11,19339:20,19340:20,19346:10,19348:10,19371:20,19372:20"},
{Id="12017",Name="Broodlord Lashlayer",Story="Broodlord Lashlayer is a black drakonid in Nefarian's service who guards the Halls of Strife in Blackwing Lair, blocking the way into Nefarian's inner sanctum.",Portrait=M.."raids\\bwl\\broodlord-portrait",Frame=M.."raids\\bwl\\broodlord-frame",MapCoordinateX=52,MapCoordinateY=66.3,L="20383:100,16898:11,16906:11,16912:11,16919:11,16927:11,16941:11,16949:11,16957:11,16965:11,19341:20,19342:20,19350:10,19351:10,19373:20,19374:20,33083:7"},
{Id="11983",Name="Firemaw",Story="Firemaw is a black dragon found patrolling the Crimson Laboratories. He is one of three powerful black drakes who guard the way to their master, Nefarian.",Portrait=M.."raids\\bwl\\firemaw-portrait",Frame=M.."raids\\bwl\\firemaw-frame",MapCoordinateX=44.3,MapCoordinateY=42.1,L="19343:12,19344:12,19365:12,19398:12,19399:12,19400:12,19401:12,19402:12,16899:7,16907:7,16913:7,16920:7,16928:7,16940:7,16948:7,16956:7,16964:7,19353:7,19355:7,19394:7,19395:7,19396:7,19397:7"},
{Id="ezzel",Name="Ezzel Darkbrewer",Story="Ezzel Darkbrewer might be a goblin of small stature but he is by no means a pushover. With an arsenal of chemical concoctions and a brilliant mind sharpened by many years in the field, he's ready to thwart any intruders stepping into his employer's laboratory. Oh, and don't forget the lumbering ogre he's atop of.",Portrait=M.."raids\\bwl\\ezzel-portrait",Frame=M.."raids\\bwl\\ezzel-frame",MapCoordinateX=16.8,MapCoordinateY=55.8,L="33073:7,33074:7,33075:7,33076:7,33077:7,33078:7,33079:7,33080:7,33081:7,33086:7,33083:7,33084:7,33085:7"},
{Id="14601",Name="Ebonroc",Story="Ebonroc is a black dragon found patrolling the Crimson Laboratories. He is one of three powerful black drakes who guard the way to their master, Nefarian.",Portrait=M.."raids\\bwl\\ebonroc-portrait",Frame=M.."raids\\bwl\\ebonroc-frame",MapCoordinateX=38.4,MapCoordinateY=32,L="16899:7,16907:7,16913:7,16920:7,16928:7,16940:7,16948:7,16956:7,16964:7,19353:7,19355:7,19394:7,19395:7,19396:7,19397:7,19345:17,19368:17,19403:17,19405:17,19406:17,19407:17"},
{Id="11981",Name="Flamegor",Story="Flamegor is a black dragon found patrolling the Crimson Laboratories. He is one of three powerful black drakes who guard the way to their master, Nefarian.",Portrait=M.."raids\\bwl\\flamegor-portrait",Frame=M.."raids\\bwl\\flamegor-frame",MapCoordinateX=45.7,MapCoordinateY=22.2,L="19357:17,19367:17,19430:17,19431:17,19432:17,19433:17,16899:7,16907:7,16913:7,16920:7,16928:7,16940:7,16948:7,16956:7,16964:7,19353:7,19355:7,19394:7,19395:7,19396:7,19397:7"},
{Id="14020",Name="Chromaggus",Story="Chromaggus is a two-headed dragon beast creation of Nefarian, who acts as a dutiful protector of Blackwing Lair. Despite his canine appearance, he's actually a dragonkin (more specifically a drakeadon). The victims of Chromaggus' radiating affliction were transformed into drakonid.",Portrait=M.."raids\\bwl\\chromaggus-portrait",Frame=M.."raids\\bwl\\chromaggus-frame",MapCoordinateX=49.4,MapCoordinateY=52,L="16832:11,16902:11,16917:11,16924:11,16932:11,16937:11,16945:11,16953:11,16961:11,19349:10,19352:10,19385:20,19387:20,19388:20,19389:20,19347:10,19361:10,19386:16,19390:16,19391:16,19392:16,19393:16,33084:20"},
{Id="11583",Name="Nefarian",Story="Nefarian is the eldest son of Deathwing and his Prime Consort Sintharia. Like his father and his younger twin sister Onyxia, he has a human guise, appearing as Victor Nefarius, Lord of Blackrock. Holding the Blackrock clan and various clans of ogres under his control, Nefarian rules from his lair at the top of Blackrock Spire",Portrait=M.."raids\\bwl\\nefarian-portrait",Frame=M.."raids\\bwl\\nefarian-frame",MapCoordinateX=75.4,MapCoordinateY=52.1,L="19003:100,16897:11,16905:11,16916:11,16923:11,16931:11,16942:11,16950:11,16958:11,16966:11,19360:10,19363:10,19375:20,19376:20,19377:20,19378:20,19356:10,19364:10,19379:20,19380:20,19381:20,19382:20,36551:1"},
}}
ZLDB.R["ES"]={
Name="Emerald Sanctum",
Story="The Emerald Sanctum, a sacred refuge within the Dreamway, has fallen under the shadow of an insidious darkness. Once a baston of tranquility where the Green Dragonflight performed their most holy rituals, it has become a staging ground for the Nightmare's corruption. Now, the very defenders of the Dream have succumbed to malevolent whispers, threatening to turn the power of the 'Awakening' against Azeroth itself.",
Background=M.."raids\\es\\background",
GridBackground=M.."raids\\es\\grid-background",
MapId=38,
IconScale=1,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=20.6,MapCoordinateY=60.6,MapZoneId=15}},
Type=T.Raid,
Key="ES",
Bosses={
{Id="60747",Name="Erennius",Story="Once a noble hero dedicated to the cause of the Green Dragonflight, Erennius could not withstand the relentless pull of the Nightmare. The corruption sank deep into his heart during the ritual of the Awakening, twisting him into a powerful agent of evil. He now stands as a tragic sentinel of the Sanctum, his former heroism replaced by an unyielding hunger to spread the taint that claimed him.",Portrait=M.."raids\\es\\erennius-portrait",Frame=M.."raids\\es\\erennius-frame",MapCoordinateX=67.3,MapCoordinateY=39.3,L="61652:100"},
{Id="60748",Name="Solnius",Story="Known as Solnius the Awakener, this dragon was one of Ysera's most cherished children and the sworn protector of the sacred Awakening ritual. Having succumbed to the alluring whispers of the Nightmare, Solnius has betrayed his lineage. He now wields the sacred powers of the Dream to serve the darkness, overseeing the corruption of the very realm he was born to safeguard.",Portrait=M.."raids\\es\\solnius-portrait",Frame=M.."raids\\es\\solnius-frame",MapCoordinateX=70.4,MapCoordinateY=23.2,L="30018:2,61205:17,61206:17,61208:17,61209:17,61211:17,61214:17,61207:17,61210:17,61212:17,61213:17,61239:17,61448:17,41076:17,61203:17,61204:17,61237:17,61238:17,61455:17,51361:15,61196:25,61215:100,61217:4,61218:4,61424:4,61428:4,61432:4,70000:4,61444:35,61733:2,61522:17:h,61523:17:h,61524:17:h,61525:17:h,61526:17:h,61527:17:h,42165:60:h"},
}}
ZLDB.R["KARA10"]={
Name="Lower Karazhan Halls",
Story="The lower reaches of Karazhan are a haunting echo of the tower's vibrant past, where spectral guests and servants are eternally bound to a single moment in time. Councilmen and dukes wander these corridors as tormented phantoms, often unaware of their own demise and still demanding the luxuries of room service and fine wine. Beneath the surface of these ghostly festivities, however, lies a darker reality: the tower has become a focal point for cursed artifacts like the Scythe of Elune and is prowled by a vicious pack of worgen. Those who navigate these halls must contend with spirits trapped in a loop of madness and the undead castellan who keeps the master's secrets under lock and key.",
Background=M.."raids\\kara10\\background",
GridBackground=M.."raids\\kara10\\grid-background",
MapId=29,
IconScale=1,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=43.6,MapCoordinateY=75.6,MapZoneId=9}},
Type=T.Raid,
Key="KARA10",
Bosses={
{Id="61319",Name="Master Blacksmith Rolfen",Story="The blacksmiths of Karazhan were once tasked with maintaining the intricate weaponry and armor of Medivh's guests. In death, Master Blacksmith Rolfen remains at his anvil, though his work is now fueled by the spectral essences that permeate the tower. He is said to guard rare smithing plans that many would kill to possess, ensuring that even in the afterlife, the forge of the Prophet never truly grows cold.",Portrait=M.."raids\\kara10\\rolfen-portrait",Frame=M.."raids\\kara10\\rolfen-frame",MapCoordinateX=60.8,MapCoordinateY=82.5,MapIsBelow=true,L="61805:1,61806:1,61807:1,61808:1"},
{Id="61221",Name="Brood Queen Araxxna",Story="The dark arcane energy leaking from Medivh's experiments has twisted the natural wildlife within the tower's foundations. Araxxna, a massive arachnid, has claimed the shadowed corners of the lower halls as her nesting ground. She and her endless brood feast on the lost spirits and unwary explorers who wander too far from the guest chambers, weaving webs of solidified mana to trap her prey.",Portrait=M.."raids\\kara10\\araxxna-portrait",Frame=M.."raids\\kara10\\araxxna-frame",MapCoordinateX=82.6,MapCoordinateY=25.3,MapIsBelow=true,L="8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,37011:20,51217:100,58275:100,61243:20,61260:20,61268:20,61270:20,61297:20,61244:14,61245:14,61269:14,61272:14,61278:14,61283:14,61816:14,70102:1"},
{Id="61224",Name="Grizikil",Story="A hoarder by nature, the creature known as Grizikil lurks at the end of the guest halls, surrounded by a mountain of stolen trinkets. Among his most bizarre treasures is a comically large candle, a colossal candlestick said to be essential for strange experiments within the Master's Library. He is fiercely protective of his stash, viewing any who approach as common thieves looking to plunder his 'status symbols'.",Portrait=M.."raids\\kara10\\grizikil-portrait",Frame=M.."raids\\kara10\\grizikil-frame",MapCoordinateX=90.6,MapCoordinateY=38.6,L="8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,51217:100,61251:20,61253:20,61276:20,61291:20,61292:20,61252:14,61261:14,61267:14,61288:14,61289:14,61298:14,61450:14,70102:1"},
{Id="61223",Name="Clawlord Howlfang",Story="Clawlord Howlfang is the tyrannical leader of the worgen that have infested Karazhan. Attracted by the presence of the Scythe of Elune-which was brought to the tower by a mysterious Dark Rider-Howlfang has asserted his dominance over the various tribes lurking in the shadows. By severing his grasp, one might hope to quell the feral devastation that threatens to consume the lower halls.",Portrait=M.."raids\\kara10\\clawlord-portrait",Frame=M.."raids\\kara10\\clawlord-frame",MapCoordinateX=69.1,MapCoordinateY=55.5,L="8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,51217:100,55552:100,61248:20,61249:20,61273:20,61281:20,61293:20,61250:14,61263:14,61271:14,61274:14,61285:14,61290:14,61451:14,70102:1,70226:3"},
{Id="61222",Name="Lord Blackwald II",Story="Lord Blackwald II is a wretched being who reveled in the dark acquisition of the Scythe of Elune. His malevolence resonates through the halls, finding a twisted satisfaction in the possession of the powerful, cursed relic. He guards the artifact with a fanaticism born of long-term exposure to its shadow-bound power, serving as a grim reminder that Karazhan's residents are as much prisoners of their own desires as they are of the tower's walls.",Portrait=M.."raids\\kara10\\blackwald-portrait",Frame=M.."raids\\kara10\\blackwald-frame",MapCoordinateX=69.1,MapCoordinateY=74.3,L="8547:1,13517:1,58401:1,61177:1,61178:1,61180:1,61189:1,61190:1,61191:1,61192:1,61219:1,61739:1,70001:1,51217:100,61184:2,61246:20,61247:20,61262:20,61266:20,61443:20,61255:14,61279:14,61282:14,61286:14,61287:14,61294:14,61449:14,70102:1,70226:3,42166:10"},
{Id="61225",Name="Moroes",Story="The cursed and undead castellan of Karazhan, Moroes continues his duties as if the master were still in residence. He is a cunning and fierce protector of the tower's inner workings, specifically guarding the Key to the Upper Chambers. While he appears as a simple servant, his combat prowess and refusal to allow prying eyes into the forbidden sections of the tower make him one of the most formidable obstacles in Lower Karazhan.",Portrait=M.."raids\\kara10\\moroes-portrait",Frame=M.."raids\\kara10\\moroes-frame",MapCoordinateX=34.9,MapCoordinateY=25.3,L="8547:1,13517:2,58401:1,61177:1,61178:1,61180:1,61189:2,61190:2,61191:2,61192:2,61219:2,61739:1,70001:2,51217:100,61256:10,61257:10,61264:10,61265:10,61275:10,61277:10,61284:10,61299:10,61453:10,61454:10,70102:2"},
}}
ZLDB.R["KARA40"]={
Name="Tower of Karazhan",
Story="Built upon a volatile focal point of ley lines, the tower of the Guardian Medivh remains a place of shifting realities. While the lower halls are haunted by the spirits of the past, the upper reaches have torn open a gateway to the shattered remains of Outland. Within the 'Rock of Desolation' wing, the Burning Legion has established a bridgehead, led by their most cunning commanders who seek to use the tower's power to consume Azeroth.",
Background=M.."raids\\kara40\\background",
GridBackground=M.."raids\\kara40\\grid-background",
MapId=40,
ZoneId=2,
IconScale=1,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=45.9,MapCoordinateY=71.1,MapDestinationZoneId=2,MapZoneId=9}},
Type=T.Raid,
Key="KARA40",
Bosses={
{Id="61939",Name="Keeper Gnarlmoon",Story="A bloodmage of legendary power and a foul 'pricolich,' Gnarlmoon has entrenched himself within the tower's heart. He draws upon the cursed ley lines of Deadwind Pass to fuel his malevolent blood magic and guard the tower's dark secrets.",Portrait=M.."raids\\kara40\\gnarlmoon-portrait",Frame=M.."raids\\kara40\\gnarlmoon-frame",MapCoordinateX=61.7,MapCoordinateY=44.8,MapId=2,L="55078:25,55081:25,55084:25,55285:25,55079:25,55080:25,55082:25,55083:25"},
{Id="61946",Name="Ley-Watcher Incantagos",Story="Enthralled by the unpredictable power of the tower, this former defender of Kel'Theril now stands as a sentinel of the arcane. He is unable to break away from the very energies that have warped his mind into a weapon of the tower.",Portrait=M.."raids\\kara40\\incantagos-portrait",Frame=M.."raids\\kara40\\incantagos-frame",MapCoordinateX=49.3,MapCoordinateY=80.5,MapId=2,MapIsBelow=true,L="41403:100,55085:25,55087:25,55090:25,55091:25,55086:25,55089:25,55099:25,55507:25"},
{Id="61951",Name="Anomalus",Story="A volatile elemental manifestation of pure arcane pressure created by the tower's intense magical convergence. Its 'cosmic residue' is so saturated with ley energy that it is essential for the restoration of the Guardian's legendary artifacts.",Portrait=M.."raids\\kara40\\anomalus-portrait",Frame=M.."raids\\kara40\\anomalus-frame",MapCoordinateX=63.4,MapCoordinateY=77.2,MapId=2,L="55092:25,55095:25,55096:25,55279:25,55093:25,55097:25,55098:25,55106:25"},
{Id="61958",Name="Echo of Medivh",Story="A spectral trace of the Guardian's second life, lingering in the fabric of the tower's ley lines. This echo represents Medivh's power and regret, serving as the final gatekeeper for those seeking the knowledge of the Upper Chambers.",Portrait=M.."raids\\kara40\\medivh-portrait",Frame=M.."raids\\kara40\\medivh-frame",MapCoordinateX=27.4,MapCoordinateY=39.8,MapId=2,L="55094:25,55107:25,55111:25,55112:25,55108:25,55109:25,55110:25,55276:25"},
{Id="59967",Name="Chess Event",Story="A twisted recreation of Medivh's favorite game, where the pieces are imbued with the spirits of the tower's victims. Survival requires both tactical mastery and the ability to withstand the lethal magical cheats orchestrated by the tower's lingering consciousness.",Portrait=M.."raids\\kara40\\king-portrait",Frame=M.."raids\\kara40\\king-frame",MapCoordinateX=60.3,MapCoordinateY=35.5,MapId=2,L="55088:1,55100:1,55101:1,55102:1,55103:1,55104:1,55105:1,55274:1,55483:50,55484:50,20739:2,55482:20"},
{Id="59981",Name="Sanv Tas'dal",Story="A Draenei whose spirit was further fractured by the spatial anomalies within this wing of the tower. Trapped within the Rock of Desolation, Sanv Tas'dal has been driven to a feral desperation, wielding the remnants of his shamanic heritage and dark voodoo to defend his meager territory from any intruders.",Portrait=M.."raids\\kara40\\sanv-portrait",Frame=M.."raids\\kara40\\sanv-frame",MapCoordinateX=44.7,MapCoordinateY=35.6,MapId=1,L="55113:14,55114:14,55115:14,55116:14,55117:14,55118:14,55119:14,55485:50,55486:50,55482:20,69001:100"},
{Id="59961",Name="Rupturan the Broken",Story="A massive, sentient formation of stone and earth that was shattered during the destruction of Draenor. Reconstituted by the chaotic energies of the tower's rift, this literal 'broken' monolith now stands as a mindless, crushing force of nature, physically embodying the shattered landscape of the Rock of Desolation.",Portrait=M.."raids\\kara40\\rupturan-portrait",Frame=M.."raids\\kara40\\rupturan-frame",MapCoordinateX=49.3,MapCoordinateY=25,MapId=1,L="55120:14,55121:14,55122:14,55123:14,55124:14,55125:14,55126:14,55487:50,55488:50,55482:20"},
{Id="59991",Name="Kruul",Story="High Lord Kruul, the 'Burning Shadow,' has utilized the rift within Karazhan to lead a demonic vanguard. A Doomlord of immense malice, he seeks to claim the Guardian's power to fuel the Legion's conquest across the Twisting Nether.",Portrait=M.."raids\\kara40\\kruul-portrait",Frame=M.."raids\\kara40\\kruul-frame",MapCoordinateX=48.9,MapCoordinateY=75.6,MapId=1,L="55127:11,55128:11,55129:11,55130:11,55131:11,55132:11,55489:50,55490:50,55506:11,55510:11,55511:11,55482:20"},
{Id="93333",Name="Mephistroth",Story="A master of Nathrezim manipulation who orchestrates the Legion's movements from the shadows of the Rock of Desolation. Mephistroth thrives on the despair of the tower's trapped spirits, aiming to turn Karazhan into a permanent gateway for the Burning Crusade.",Portrait=M.."raids\\kara40\\mephistroth-portrait",Frame=M.."raids\\kara40\\mephistroth-frame",MapCoordinateX=52.2,MapCoordinateY=68.1,MapId=1,L="41447:100,55346:6,55347:6,55348:6,55349:6,55350:6,55351:8,55352:8,55353:8,55354:8,55355:8,55356:8,55357:8,55512:8,55513:8,55482:20,55491:100,55492:100,55579:100,92082:5"},
}}
ZLDB.R["MC"]={
Name="Molten Core",
Story="The Molten Core lies at the very bottom of Blackrock Depths. It is the heart of Blackrock Mountain and the exact spot where, long ago in a desperate bid to turn the tide of the dwarven civil war, Emperor Thaurissan summoned the elemental Firelord, Ragnaros, into the world. Though the firelord is incapable of straying far from the blazing Core, it is believed that his elemental minions command the Dark Iron dwarves, who are in the midst of creating armies out of living stone. The burning lake where Ragnaros lies sleeping acts as a rift connecting to the plane of fire, allowing the malicious elementals to pass through. Chief among Ragnaros' agents is Majordomo Executus - for this cunning elemental is the only one capable of calling the Firelord from his slumber.",
Background=M.."raids\\mc\\background",
GridBackground=M.."raids\\mc\\grid-background",
MapId=11,
IconScale=0.9,
MinLevel=58,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=38.3,MapCoordinateY=36.1,MapZoneId=6},{MapContinentId=14,MapCoordinateX=66.5,MapCoordinateY=29.3,MapZoneId=1}},
Type=T.Raid,
Key="MC",
Bosses={
{Id="52145",Name="Incindis",Story="Documentation regarding Incindis is remarkably scarce, noting him only as a formidable resident of the Molten Core.",Portrait=M.."raids\\mc\\incindis-portrait",Frame=M.."raids\\mc\\incindis-frame",MapCoordinateX=55.1,MapCoordinateY=11.1,L="16812:25,16826:25,16839:25,16860:25,16849:25,16862:25,17077:5,18861:5,18870:5,18872:5,18875:5,18878:5,18879:5,19145:5,19146:5,19147:5,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,58205:20,58206:20,58207:20,58208:20,58209:20"},
{Id="12118",Name="Lucifron",Story="Among the ranks of the flamewakers, overseers and their guards constantly jockey for higher status among the hierarchy of elementals in hopes of gaining favor with Ragnaros. Lucifron is no exception. He has clashed with Gehennas on several occasions, particularly during their incarceration within the Elemental Plane. This rivalry has now extended to the Molten Core where Lucifron quietly waits for his opportunity to capitalize on any weakness shown by the other flamewakers. Lucifron, and his two Flamewaker Protector guards, can be found watching over the enormous core hound Magmadar, favored pet of Ragnaros.",Portrait=M.."raids\\mc\\lucifron-portrait",Frame=M.."raids\\mc\\lucifron-frame",MapCoordinateX=63.6,MapCoordinateY=44.9,L="16665:100,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16805:30,16863:30,17077:4,18861:4,18870:4,18872:4,18875:4,18878:4,18879:4,19145:4,19146:4,19147:4,16800:20,16829:20,16837:20,16859:20,17109:20"},
{Id="11982",Name="Magmadar",Story="A terrifying behemoth composed of igneous rock and roiling magma, Magmadar serves as the origin of the core hounds that roam the earthen halls of Molten Core. Favored among Ragnaros's pets, Magmadar is protected by the flamewaker Lucifron and surrounded by vicious packs of ravenous hounds. It is said that while Ragnaros was imprisoned in the Elemental Plane, the Firelord would feed the remains of his captured enemies to the eagerly awaiting twin maws of Magmadar. As a result, the hound grew strong and loyal, and even now Magmadar's savage ferocity remains uncontested.",Portrait=M.."raids\\mc\\magmadar-portrait",Frame=M.."raids\\mc\\magmadar-frame",MapCoordinateX=67,MapCoordinateY=32.8,L="18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16796:20,16810:20,16814:20,16822:20,17069:20,16835:17,16843:17,16847:17,16855:17,16867:17,17065:17,17073:20,18203:20,18820:5,18821:5,18822:5,18823:5,18824:5,18829:5,18861:5,19136:5,19142:5,19143:5,19144:5"},
{Id="12057",Name="Garr",Story="As one of the two chief lieutenants serving under Ragnaros, Garr plays a key role in the current success of the Firelord and his spreading influence. Garr, like Baron Geddon, holds half of Bindings of the Windseeker, which contains the remaining essence of Thunderaan, Prince of Air. Tales say that after centuries of partnership, Geddon became suspicious of Garr and felt the elemental sought both halves of the talisman. Thus, relations between the two powers are strained. Both Garr and Baron Geddon draw their considerable might from the blazing runes carved deep into the floor of Molten Core.",Portrait=M.."raids\\mc\\garr-portrait",Frame=M.."raids\\mc\\garr-frame",MapCoordinateX=32.7,MapCoordinateY=74.8,L="17782:4,18564:5,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16834:17,16842:17,16846:17,16854:17,16866:17,17066:17,16795:20,16808:20,16813:20,16821:20,17071:20,17105:20,18820:5,18821:5,18822:5,18823:5,18824:5,18829:5,18832:20,18861:5,19136:5,19142:5,19143:5,19144:5"},
{Id="12056",Name="Baron Geddon",Story="When Ragnaros was ripped from the Elemental Plane by the Sorcerer-Thane Thaurissan, several subjects from the Firelands followed in his wake. Baron Geddon fought against the titans and aided in the betrayal of Thunderaan, Prince of Air. The Firelord devoured the essence of the prince, but was unable to consume him entirely. Thus, the remaining energies were trapped within a talisman of elemental binding, which Ragnaros split into two perfect halves which he gave to his two lieutenants.",Portrait=M.."raids\\mc\\geddon-portrait",Frame=M.."raids\\mc\\geddon-frame",MapCoordinateX=51.8,MapCoordinateY=80,L="18563:6,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16836:8,16844:30,18820:8,18821:8,18822:8,18823:8,18829:4,18861:8,19136:8,19142:8,19143:8,19144:8,16797:33,16807:33,17110:33,16856:8,18824:8"},
{Id="12264",Name="Shazzrah",Story="Of all the flamewakers who followed Ragnaros into the world of Azeroth, Shazzrah is the most talented in the realm of the arcane. He is aware that his colleague Baron Geddon suspects the elemental Garr of treachery. The conflict between Baron Geddon and Garr suits Shazzrah well, for in fact it is Shazzrah who seeks to posses both halves of the Talisman of Elemental Binding so that he might find a way to siphon its energies for his own use. Ragnaros was very likely aware of his underling's penchant for duplicity when he split the talisman in half and entrusted the pieces to Baron Geddon and Garr.",Portrait=M.."raids\\mc\\shazzrah-portrait",Frame=M.."raids\\mc\\shazzrah-frame",MapCoordinateX=54.1,MapCoordinateY=85.2,L="18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16803:25,16811:25,16824:25,17077:2,18861:2,18870:2,18872:2,18875:2,18878:2,18879:2,19145:2,19146:2,19147:2,16801:33,16831:33,16852:33"},
{Id="12098",Name="Sulfuron Harbinger",Story="Among the most favored of the flamewakers, Sulfuron Harbinger is the terrifying herald of Ragnaros himself. From the infernal depths of the Molten Core, the Harbinger commands Ambassador Flamelash and the other lesser flamewakers in the outside world. Sulfuron Harbinger answers only to Executus and guards the rune of Koro, one of several runes that empower the Firelord's servants. Sulfuron Harbinger keeps Shazzrah in particular under close watch, believing that Shazzrah seeks to betray Ragnaros. Flanked by four of the Firelord's most fervid priests, the Harbinger prepares for the day when the elemental lord of fire claims the world of Azeroth for his own.",Portrait=M.."raids\\mc\\sulfuron-portrait",Frame=M.."raids\\mc\\sulfuron-frame",MapCoordinateX=77.9,MapCoordinateY=84.9,L="16823:30,16868:30,17077:4,18861:4,18870:4,18872:4,18875:4,18878:4,18879:4,19145:4,19146:4,19147:4,16816:33,16848:33,17074:33"},
{Id="11988",Name="Golemagg the Incinerator",Story="The most feared soldiers of Ragnaros's elemental forces are the molten giants, and among them Golemagg the Incinerator is unrivaled for his sheer brutality and savage efficiency. So absolute is the molten behemoth's power that he has cowed two core ragers - offspring of the colossal beast Magmadar - which he now uses as pets. For this affront, he has earned Magmadar's eternal and unwavering ire, although the fearsome creature has yet to act on his savage impulses.",Portrait=M.."raids\\mc\\golemagg-portrait",Frame=M.."raids\\mc\\golemagg-frame",MapCoordinateX=66,MapCoordinateY=65,L="17203:80,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,16798:25,16809:25,16815:25,16820:25,16833:20,16841:20,16845:20,16853:20,16865:20,17072:25,17103:25,18820:2,18821:2,18822:2,18823:2,18824:2,18829:2,18842:25,18861:2,19136:2,19142:2,19143:2,19144:2"},
{Id="65020",Name="Twin Golems",Story="Apart from their confirmed status as guardians of the Firelord's domain, the history of the Twin Golems remains entirely unrecorded.",Portrait=M.."raids\\mc\\golems-portrait",Frame=M.."raids\\mc\\golems-frame",MapCoordinateX=67.1,MapCoordinateY=49.6,L="18820:11,18821:11,18822:11,18823:11,18824:11,18829:11,18861:11,19136:11,19142:11,19143:11,19144:11,58210:17,58212:17,58215:17,58237:17,58238:17,58242:17,18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,58211:25,58213:25,58239:25,58241:25,58246:100"},
{Id="57642",Name="Sorcerer-Thane Thaurissan",Story="Sorcerer-Thane Thaurissan was the leader of the shadowy sorcerers of the Dark Iron clan before and during the War of the Three Hammers. He was the one responsible for summoning the Firelord Ragnaros into Azeroth.",Portrait=M.."raids\\mc\\sorcerer-portrait",Frame=M.."raids\\mc\\sorcerer-frame",MapCoordinateX=88.1,MapCoordinateY=45,L="18252:1,18257:1,18259:1,18260:1,18264:1,18265:1,18290:1,18291:1,18292:1,21371:1,18820:11,18821:11,18822:11,18823:11,18824:11,18829:11,18861:11,19136:11,19142:11,19143:11,19144:11,58210:17,58212:17,58215:17,58237:17,58238:17,58242:17,58214:25,58240:25,58243:25,58244:25"},
{Id="12018",Name="Majordomo Executus",Story="At the top of the elemental hierarchy, just beneath Ragnaros himself, resides Majordomo Executus. This flamewaker gained his exalted status by proving to be nearly invincible in the battles that raged within the elemental plane. Rumor has it that Executus supplanted Baron Geddon, and the two have been rivals ever since. Although this rumor has yet to be confirmed, there is certainly no doubt that Ragnaros does not tolerate failure. Thus, the lesser flamewakers (and, of course, Baron Geddon) eagerly await a misstep by Executus, anticipating their chance to vie for the coveted attention of the Firelord.",Portrait=M.."raids\\mc\\executus-portrait",Frame=M.."raids\\mc\\executus-frame",MapCoordinateX=79.3,MapCoordinateY=70.8,L="18806:20,18809:20,18810:20,18812:20,19140:20,18803:20,18805:20,18808:20,18811:20,19139:20,18646:50,18703:50,42178:30"},
{Id="11502",Name="Ragnaros",Story="Lying at the bottom of Blackrock Mountain, Ragnaros is striving to find a way home, as well as to gather his strength once again so he can burn away Azeroth and take it for his own. Meanwhile, in Sulfuron Keep and elsewhere across the Firelands, his elemental princes battle constantly for dominance. He and his dwarven minions took control of the Blackrock mountain's volcanic depths and made war on the orcs in the Upper Blackrock Spire, which served as the seat of power for Nefarian the black dragon. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain.",Portrait=M.."raids\\mc\\ragnaros-portrait",Frame=M.."raids\\mc\\ragnaros-frame",MapCoordinateX=55.3,MapCoordinateY=60.3,L="17204:6,19017:100,16901:12,16909:12,16915:12,16922:12,16930:12,16938:12,16954:12,16962:12,18814:20,18815:20,18816:20,18817:20,19138:20,16946:12,17063:20,17102:20,17106:20,17107:20,19137:20,17076:8,17082:8,17104:8,92080:1,70171:100"},
}}
ZLDB.R["NAXX"]={
Name="Naxxramas",
Story="Naxxramas was originally an ancient, subterranean nerubian ziggurat. During the War of the Spider, the undead Anub'arak led an army of Scourged nerubians to conquer the ziggurat for the Lich King Ner'zhul. Under Anub'arak's oversight, the Scourge then altered the structure into a potent war machine.",
Background=M.."raids\\naxx\\background",
GridBackground=M.."raids\\naxx\\grid-background",
MapId=33,
ZoneId=1,
IconScale=0.8,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=2,MapCoordinateX=41,MapCoordinateY=29.5,MapDestinationZoneId=1,MapZoneId=12}},
Type=T.Raid,
Key="NAXX",
Bosses={
{Id="16028",Name="Patchwerk",Story="Patchwerk is one of Kel'Thuzad's most powerful abominations. His strength and speed came as a shock to those that faced him in combat. Far from a sluggish, mindless undead, Patchwerk used his immense power to pulverize any adversary with a flurry of potent, powerful attacks. When word of his existence first reached the ears of the Brotherhood, none believed the tales of an abomination with such immense speed and strength. Fewer still believed it when he fell the first time.",Portrait=M.."raids\\naxx\\patchwerk-portrait",Frame=M.."raids\\naxx\\patchwerk-frame",MapCoordinateX=38.3,MapCoordinateY=45.7,MapId=1,L="22726:30,22354:33,22361:33,22368:33,22815:20,22818:20,22820:20,22960:20,22961:20"},
{Id="15931",Name="Grobbulus",Story="Carrying the same plague slime that flows through Naxxramas within its hulking form, Grobbulus is a flesh giant, the first successful one of its kind, created to build a formidable army capable of quickly spreading the undead plague by injecting the living ooze into the bodies of their foe. The recipient of this foul injection would usually flee to his allies, bringing them down with him.",Portrait=M.."raids\\naxx\\grobbulus-portrait",Frame=M.."raids\\naxx\\grobbulus-frame",MapCoordinateX=47,MapCoordinateY=29.6,MapId=1,L="22726:30,22354:33,22361:33,22368:33,22803:20,22810:20,22967:20,22968:20,22988:20"},
{Id="15932",Name="Gluth",Story="The undead plague-dog Gluth sits obediently within Naxxramas, awaiting orders from his masters. Gluth's appetite is so voracious that even the living were not enough to satisfy his hunger. It is rumored that Feugen was said to feed him an army of zombies daily, which Gluth uses to knit his own decaying flesh back together, recycling the remains of undead too weak to use in combat.",Portrait=M.."raids\\naxx\\gluth-portrait",Frame=M.."raids\\naxx\\gluth-frame",MapCoordinateX=37.9,MapCoordinateY=27,MapId=1,L="22726:30,22354:8,22355:8,22356:8,22358:8,22361:8,22362:8,22363:8,22365:8,22368:8,22369:8,22370:8,22372:8,22813:20,22981:20,22983:20,22994:20,23075:20"},
{Id="15928",Name="Thaddius",Story="Pieced together from the flesh of innocent women and children, this massive abomination dwells in one of Naxxramas' experimental laboratories, flanked by two huge wights-Stalagg and Feugen. Powerful bolts of electricity arc through the laboratory, supercharging Thaddius and his wight minions. It is said that the souls contained in Thaddius are fused together - eternally bound within that foul prison of flesh.",Portrait=M.."raids\\naxx\\thaddius-portrait",Frame=M.."raids\\naxx\\thaddius-frame",MapCoordinateX=29,MapCoordinateY=13.3,MapId=1,L="22353:33,22360:33,22367:33,22801:20,22808:20,23000:20,23001:20,23070:20"},
{Id="15956",Name="Anub'Rekhan",Story="One of the minions raised by the Lich King was the Crypt Lord Anub'Rekhan. In life, he was one of the nerubians' most powerful spider lords. Now, he guards the doors of the Spider Wing.",Portrait=M.."raids\\naxx\\anubrekhan-portrait",Frame=M.."raids\\naxx\\anubrekhan-frame",MapCoordinateX=54.9,MapCoordinateY=29,MapId=1,L="22726:30,22355:33,22362:33,22369:33,22935:20,22936:20,22937:20,22938:20,22939:20,42167:20"},
{Id="15953",Name="Grand Widow Faerlina",Story="Once one of the high-ranking members of the Cult of the Damned under Kel'Thuzad, in death she breeds and takes care of the seemingly endless amount of arachnids that swarm from the depths of the citadel. A master of poisons, she has a keen understanding of what makes mortals suffer. The poisons she concocts come from the spiderlings produced by Maexxna.",Portrait=M.."raids\\naxx\\faerlina-portrait",Frame=M.."raids\\naxx\\faerlina-frame",MapCoordinateX=62.3,MapCoordinateY=23.2,MapId=1,L="22726:30,22355:33,22362:33,22369:33,22806:20,22940:20,22941:20,22942:20,22943:20"},
{Id="15952",Name="Maexxna",Story="A massive spider taken from the depths of Northrend's mountains many ages ago. She was captured within the dread citadel Naxxramas, where she gives birth to her brood. She feasts on those foolish enough to enter the necropolis, feeding her spawn with their corpses and producing spider after spider that Kel'Thuzad uses to his own foul ends.",Portrait=M.."raids\\naxx\\maexxna-portrait",Frame=M.."raids\\naxx\\maexxna-frame",MapCoordinateX=75.9,MapCoordinateY=11.9,MapId=1,L="22726:30,22357:33,22364:33,22371:33,22804:20,22807:20,22947:20,22954:20,23220:20,37012:30"},
{Id="15954",Name="Noth the Plaguebringer",Story="Noth the Plaguebringer was once a reputable mage of Dalaran, who heard the call of the Lich King in much the same way Kel'Thuzad did. Also driven by power, he accepted the summons to serve the needs of the Scourge with his skills in necromancy and curse-weaving. However, when Noth saw that the Third War was taking numerous innocent lives, he began second-guessing his decision to join Kel'Thuzad. Kel'Thuzad swiftly dealt with Noth's growing compassion by freezing the living heart in Noth's chest.",Portrait=M.."raids\\naxx\\noth-portrait",Frame=M.."raids\\naxx\\noth-frame",MapCoordinateX=56.5,MapCoordinateY=73.3,MapId=1,L="22726:30,22356:33,22363:33,22370:33,22816:14,23005:14,23006:14,23028:14,23029:14,23030:14,23031:14"},
{Id="15936",Name="Heigan the Unclean",Story="The mastermind behind the magic of the cauldrons that quickly spread the undead plague through Lordaeron, corrupting not just the humans but flora and fauna in the area as well. The entire wilderness surrounding Lordaeron is now referred to as \"the Plaguelands\" - thanks in no small part to Heigan's handiwork.",Portrait=M.."raids\\naxx\\heigan-portrait",Frame=M.."raids\\naxx\\heigan-frame",MapCoordinateX=65.6,MapCoordinateY=67,MapId=1,L="22726:30,22356:33,22363:33,22370:33,23019:20,23033:20,23035:20,23036:20,23068:20"},
{Id="16011",Name="Loatheb",Story="A prime example of how the plague manifested in the local flora and fauna is the twisted fen creeper Loatheb. In a twisted mockery of the plant kingdom's natural ability to regenerate, Loatheb can summon deadly spores that quickly spread a sickening miasma that turns magical healing arts against those who wield them.",Portrait=M.."raids\\naxx\\loatheb-portrait",Frame=M.."raids\\naxx\\loatheb-frame",MapCoordinateX=81,MapCoordinateY=56.4,MapId=1,L="22726:30,22352:33,22359:33,22366:33,22800:20,23037:20,23038:20,23039:20,23042:20"},
{Id="16061",Name="Instructor Razuvious",Story="The most feared of the Scourge’s death knight trainers, Instructor Razuvious was once the Lordaeronian knight Razuv Ivaldi, a veteran of the Horde’s siege during the Second War. In life he was a disciplined soldier, but in undeath he has become a ruthless instructor, shaping new death knights through brutality and absolute obedience. Surrounded by his loyal understudies, Razuvious enforces the will of the Scourge with unrelenting severity, forging his pupils into weapons as merciless as himself.",Portrait=M.."raids\\naxx\\razuvious-portrait",Frame=M.."raids\\naxx\\razuvious-frame",MapCoordinateX=36.3,MapCoordinateY=66.9,MapId=1,L="22726:30,22358:33,22365:33,22372:33,23004:17,23009:17,23014:17,23017:17,23018:17,23219:17"},
{Id="16060",Name="Gothik the Harvester",Story="A master of necromancy and conjuration, Gothik is said to be able to beckon forth legions of the undead at a moment's notice. It is with his guidance that even the weakest of Death Knights can raise the dead.",Portrait=M.."raids\\naxx\\gothik-portrait",Frame=M.."raids\\naxx\\gothik-frame",MapCoordinateX=49.4,MapCoordinateY=72.3,MapId=1,L="22726:30,22358:33,22365:33,22372:33,23020:20,23021:20,23023:20,23032:20,23073:20"},
{Id="16065",Name="The Four Horsemen",Story="The Four Horsemen are extremely powerful elite death knights originally created by the lich Kel'Thuzad to serve as his royal guard. The most feared and powerful soldiers of all the Scourge, the Archlich considered them his greatest creation.",Portrait=M.."raids\\naxx\\horsemen-portrait",Frame=M.."raids\\naxx\\horsemen-frame",MapCoordinateX=28.8,MapCoordinateY=85.8,MapId=1,L="22349:33,22350:33,22351:33,22726:30,22691:1,22809:1,22811:1,23025:1,23027:1,23071:1"},
{Id="15989",Name="Sapphiron",Story="Sapphiron is an ancient agent of the blue dragonflight who was killed by Arthas Menethil and raised as a powerful frost wyrm. He was subsequently sent to the halls of Naxxramas, where he guards the inner sanctum of the citadel's dread master, Kel'Thuzad.",Portrait=M.."raids\\naxx\\sapphiron-portrait",Frame=M.."raids\\naxx\\sapphiron-frame",MapCoordinateX=56.2,MapCoordinateY=67.2,MapId=2,L="23040:10,23041:10,23043:10,23045:10,23046:10,23047:10,23048:10,23049:10,23050:10,23242:10,23545:50,23547:50,23548:50,23549:50"},
{Id="15990",Name="Kel'Thuzad",Story="Once a prominent mage of the Kirin Tor, Kel'Thuzad was seduced by the dark whispers of the Lich King. Now a tremendously powerful Archlich, he serves as the ruler of Naxxramas and the commander of the Scourge in Lordaeron, zealously carrying out his master's will to extinguish all life on Azeroth.",Portrait=M.."raids\\naxx\\kelthuzad-portrait",Frame=M.."raids\\naxx\\kelthuzad-frame",MapCoordinateX=36.4,MapCoordinateY=22.6,MapId=2,L="22520:100,22798:9,22799:9,22802:9,22812:9,22819:9,22821:9,23053:9,23054:9,23056:9,23057:9,23577:9,55581:33,55582:33,55583:33,36666:1,81283:100"},
}}
ZLDB.R["ONY"]={
Name="Onyxia's Lair",
Story="Onyxia built the lair. The entrance to the lair was carved to look like the maw of the broodmother herself, with its inner pathway being magma-lined and the ground cracked, glowing with fire from beneath. The arching stone ceiling groans and shifts, creating constant rockfalls. The walls spill lava where the heat can't be contained.",
Background=M.."raids\\ony\\background",
GridBackground=M.."raids\\ony\\grid-background",
MapId=16,
IconScale=1.2,
MinLevel=60,
MaxLevel=60,
Entrances={{MapContinentId=1,MapCoordinateX=53.4,MapCoordinateY=77,MapZoneId=10}},
Type=T.Raid,
Key="ONY",
Bosses={
{Id="axelus",Name="Broodcommander Axelus",Story="The brood does not speak of its commanders to outsiders - Broodcommander Axelus least of all.",Portrait=M.."raids\\ony\\axelus-portrait",Frame=M.."raids\\ony\\axelus-frame",MapCoordinateX=46.6,MapCoordinateY=76.6,L="33087:8,33089:8,33098:8,33157:8,33149:8,33150:8,33151:8,33152:8,33153:8,33154:8,33155:8,33156:8"},
{Id="10184",Name="Onyxia",Story="Onyxia is the daughter of Deathwing and his Prime Consort Sintharia and the broodmother of the black dragonflight on Azeroth. Like her father and her older twin brother Nefarian, she has a human guise, appearing as the Stormwindian noblewoman Lady Katrana Prestor, though she is believed to have several other humanoid guises as well.",Portrait=M.."raids\\ony\\onyxia-portrait",Frame=M.."raids\\ony\\onyxia-frame",MapCoordinateX=70.8,MapCoordinateY=25,Abilities={{Effect="Initially, Onyxian Whelps will only spawn when the nests of eggs are touched or knocked into.\
\
After Onyxia flies, Onyxian Whelps will start to occasionally spawn and attack the raid.",Icon="INV_Misc_Head_Dragon_Black",Id="11262",Name="Onyxian Whelp"},{Effect="This stage lasts until Onyxia is at 65% health.",Id="onyxiastage1",Name="Stage One: Ground Phase",SubAbilities={{Effect="Onyxia sweeps her tail in a cone behind her, dealing 600 to 1,000 damage and knocking back all enemies hit.\
\
Tanks should slowly turn her tail towards the entry to allow the raid to stay at her sides.",Flags={F.Tank,F.Important},Icon="INV_Misc_MonsterScales_05",Id="15847",Name="Tail Sweep"},{Effect="Onyxia knocks back enemies in a cone in front, inflicting 560 to 940 damage.\
\
Tanks should position themselves against the back wall to avoid flying across the room.",Flags={F.Tank},Icon="INV_Misc_MonsterScales_14",Id="18500",Name="Wing Buffet"},{Effect="Onyxia breathes fire in a frontal cone, inflicting 3050 to 4000 fire damage to all enemies positioned in front of her.",Icon="Spell_Fire_Fire",Id="18435",Name="Flame Breath"}}},{Effect="Once Onyxia reaches 65% health, she will start walking towards the center of the room before taking flight.\
\
This stage will continue until Onyxia is at 40% health.",Id="onyxiastage2",Name="Stage Two: Flying Phase",SubAbilities={{Effect="Onyxia randomly targets players, inflicting 800 to 1200 fire damage to the player and anyone within an 8 yard radius.\
\
Players should spread out at least 8 yards apart from each other to minimize damage when Onyxia is not casting Deep Breath.",Flags={F.Important},Icon="Spell_Fire_FlameBolt",Id="18392",Name="Fireball"},{Effect="Onyxia will occasionally fly in a line through the middle of the room while breathing fire, dealing heavy fire damage to anyone in her path.\
\
Players must run to any side of whichever way she is facing to avoid taking damage.",Flags={F.Deadly,F.Important},Icon="Spell_Fire_Fire",Id="17086",Name="Deep Breath"},{Effect="When Onyxia takes off, Cindarion lands. He will be active for the entire stage until he is killed.",Flags={F.Tank,F.Important},Icon="INV_Misc_Head_Dragon_Black",Id="cindarion",Name="Cindarion",SubAbilities={{Effect="Cindarion casts flame breath, dealing fire damage to all enemies in front of him.",Flags={F.Deadly},Icon="Spell_Fire_Fire",Id="cindarionflamebreath",Name="Flame Breath"}}}}},{Effect="Once Onyxia reaches 40% health, she will land back on the ground.",Id="onyxiastage3",Name="Stage Three: Ground Phase",SubAbilities={{Effect="Onyxia sweeps her tail in a cone behind her, dealing 600 to 1,000 damage and knocking back all enemies hit.\
\
Tanks should slowly turn her tail towards the entry to allow the raid to stay at her sides.",Flags={F.Tank,F.Important},Icon="INV_Misc_MonsterScales_05",Id="15847",Name="Tail Sweep"},{Effect="Onyxia knocks back enemies in a cone in front, inflicting 560 to 940 damage.\
